def _object_type_oid(pg_oid: int) -> bytes:
    # The 16-byte OID all_types reports for a composite: its PostgreSQL oid,
    # zero-padded, the same bytes the view's `decode(lpad(to_hex(...)))` builds.
    return pg_oid.to_bytes(16, 'big')


# A REF locator this backend issues (#1127): a tag, the target type's and the
# object table's pg oids, and the row's hidden object id. It is opaque to the
# client, which only hands it back.
_REF_LOCATOR_TAG = b'PGREF1'


def _ref_locator(type_pg_oid: int, table_oid: int, row_id: object) -> bytes:
    raw_id = (
        row_id.bytes if isinstance(row_id, uuid.UUID) else uuid.UUID(str(row_id)).bytes
    )
    return _REF_LOCATOR_TAG + struct.pack('>II', type_pg_oid, table_oid) + raw_id


def _parse_ref_locator(locator: bytes) -> tuple[int, int, uuid.UUID] | None:
    tag = len(_REF_LOCATOR_TAG)
    if len(locator) != tag + 8 + 16 or not locator.startswith(_REF_LOCATOR_TAG):
        return None
    type_pg_oid, table_oid = struct.unpack('>II', locator[tag : tag + 8])
    return type_pg_oid, table_oid, uuid.UUID(bytes=locator[tag + 8 :])


def _served_lobs(value: DbObject, image: ObjectImage) -> DbObject:
    # A bound object's or collection's LOB attributes carry locators the Mirror
    # handed out; each becomes the content served under it, or NULL for one it
    # never served, as the passthrough binds it (#1256).
    def content(_attr: dict, locator: object) -> object:
        served = (
            image.served_lob(bytes(locator)) if isinstance(locator, bytes) else None
        )
        return served[0] if served is not None else None

    mapped = map_object_lobs(value, content)
    return mapped if isinstance(mapped, DbObject) else value


def _array_literal(values: list) -> str:
    # A PostgreSQL array literal of `values` (#1276): NULL for None, every other
    # element double-quoted with `"` and `\\` escaped, so a string, a timestamp
    # or an inner array literal all go in as text PostgreSQL parses by the
    # element type.
    def element(value: object) -> str:
        if value is None:
            return 'NULL'
        if isinstance(value, (bytes, bytearray)):
            text = '\\x' + bytes(value).hex()
        elif isinstance(value, datetime.datetime | datetime.date):
            text = (
                value.isoformat(sep=' ')
                if isinstance(value, datetime.datetime)
                else value.isoformat()
            )
        else:
            text = str(value)
        return '"' + text.replace('\\', '\\\\').replace('"', '\\"') + '"'

    return '{' + ','.join(element(v) for v in values) + '}'


def _pg_oid_of(oid: bytes) -> int | None:
    # The inverse of _object_type_oid; None for an OID that cannot be one of
    # ours (a real Oracle OID a client carried over, or a malformed one).
    if len(oid) != 16:
        return None
    value = int.from_bytes(oid, 'big')
    return value if 0 < value <= 0xFFFFFFFF else None


# PostgreSQL's xml type, and SYS.XMLTYPE's type id -- the same on 11g and 23ai
# (all_types.type_oid) -- which an XMLType column describes with (#1536).
_XML_OID = 142
_XMLTYPE_OID = bytes.fromhex('00000000000000000000000000020100')
# SYS.XMLTYPE as an attribute's or element's type: the image walkers frame a
# value of it as an XMLType image (#1537).
_XMLTYPE_DBTYPE = DbObjectType('SYS', 'XMLTYPE', _XMLTYPE_OID, 1, [])
# What DBMS_PICKLER.GET_TYPE_SHAPE answers for SYS.XMLTYPE, measured on a live
# 23ai: version 1, this TDS -- an opaque type's -- and no attributes. A client
# resolves an XMLType column's type through it before reading a value (#1536).
_XMLTYPE_TDS = bytes.fromhex(
    '00000029260100010001ff2900000000001e1b000000193a2afd0000000d01000000070000'
    '0000000000090007'
)


def _object_column_meta(name: str, typ: DbObjectType) -> ColumnMeta:
    # An object column describes as Oracle's does: ADT with the type's
    # identity, a 2000-byte data length, no max size and no character set --
    # the values a real server sends for one (#1127).
    return ColumnMeta(
        name=name.upper().encode('utf-8'),
        data_type=TNS_TYPE_ADT,
        data_length=2000,
        max_size=0,
        charset=0,
        csfrm=0,
        type_oid=typ.oid,
        type_schema=typ.schema.encode('ascii'),
        type_name=typ.name.encode('ascii'),
    )


# A session whose PostgreSQL connection is gone -- ALTER SYSTEM KILL SESSION ended
# its backend, or the server did -- answers every call as Oracle answers a killed
# session's: ORA-00028 (#1367). A client takes that code as the end of the
# connection (python-oracledb raises DPY-4011 and closes its side), where the
# ORA-00600 an escaping psycopg error became, or the ORA-00900 of an unmapped
# SQLSTATE, said neither. psycopg reports a terminated connection as closed.
def _session_terminated() -> BackendError:
    return BackendError('session has been terminated', ora_code=ORA_SESSION_TERMINATED)


def _while_connected(method):
    @functools.wraps(method)
    def call(self, *args, **kwargs):
        if self._conn.closed:
            raise _session_terminated()
        # A transaction begun in a pipeline (#1915) that something other
        # than commit() or rollback() ended -- a COMMIT a routine ran -- turns
        # autocommit off here, before the call.
        self._conn.end_own_transaction()
        try:
            return method(self, *args, **kwargs)
        except (_ObjectMissing, _UniqueViolation, _InvalidNumber) as error:
            if self._conn.closed:
                raise _session_terminated() from None
            worded = (
                self._missing_named(error)
                if isinstance(error, _ObjectMissing)
                else self._number_worded(error)
                if isinstance(error, _InvalidNumber)
                else self._unique_worded(error)
            )
            if worded is error:
                raise
            # An array's error keeps the rows it applied before it failed,
            # and their counts (#998, #1031): only the words change.
            worded.rowcount = error.rowcount
            worded.row_counts = list(error.row_counts)
            raise worded from error
        except (psycopg.Error, BackendError):
            if self._conn.closed:
                raise _session_terminated() from None
            raise

    return call


# The schema an auth database keeps the Mirror's accounts in (#879).
# The Mirror's own statements around an application's, never prepared (#1885):
# in a pipeline they follow the statement, so a statement that fails takes the
# Parse of the one psycopg was preparing with it, and psycopg, which counts it
# prepared, then names a statement the server never made.
_CONTROL_STATEMENT = re.compile(
    r'(?:SAVEPOINT|RELEASE SAVEPOINT|ROLLBACK TO SAVEPOINT) |'
    r'SELECT pg_current_xact_id_if_assigned\(\) IS NULL\b'
)


class _CountedCursor(psycopg.Cursor[Any]):
    # Counts the statements its connection sends (#1869), so an answer read in
    # one round trip is known to be still current: no statement ran since.
    # The prelude the connection holds goes first (#1875).
    def execute(self, query: Any, params: Any = None, **kwargs: Any) -> Any:
        conn = cast('_CountedConnection', self.connection)
        if isinstance(query, str) and _CONTROL_STATEMENT.match(query):
            kwargs.setdefault('prepare', False)
        (prelude, conn.prelude) = (conn.prelude, ())
        off = conn.pgconn.pipeline_status == psycopg.pq.PipelineStatus.OFF
        if prelude and off and params is not None:
            # In one round trip with the statement. Only a statement with
            # parameters: it goes as the extended query protocol anyway, the
            # only one a pipeline speaks, which refuses several commands in
            # one string.
            with conn.pipeline():
                for statement in prelude:
                    conn.cursor().execute(statement)
                conn.statements += 1
                super().execute(query, params, **kwargs)
            return self
        for statement in prelude:
            conn.cursor().execute(statement)
        conn.statements += 1
        return super().execute(query, params, **kwargs)

    def executemany(self, *args: Any, **kwargs: Any) -> None:
        conn = cast('_CountedConnection', self.connection)
        (prelude, conn.prelude) = (conn.prelude, ())
        for statement in prelude:
            conn.cursor().execute(statement)
        conn.statements += 1
        super().executemany(*args, **kwargs)


class _CountedConnection(psycopg.Connection[Any]):
    statements = 0
    # Whether the last pipelined statement left the transaction with no
    # transaction id, and the statement count it was read at (#1869). Kept
    # here so that it travels with the connection, as a parked one does.
    unwritten_at: tuple[bool, int] | None = None
    # Statements the next one sends first, in its round trip where it can
    # (#1875): the savepoint a PL/SQL call takes and its release. The end of
    # the transaction drops them, having released every savepoint.
    prelude: tuple[str, ...] = ()
    # The seconds spent waiting on PostgreSQL, every exchange psycopg makes
    # (#1881): what a migration profile tells apart from the Mirror's own time.
    wait_seconds = 0.0

    def wait(self, *args: Any, **kwargs: Any) -> Any:
        began = time.perf_counter()
        try:
            return super().wait(*args, **kwargs)
        finally:
            self.wait_seconds += time.perf_counter() - began

    def commit(self) -> None:
        self.prelude = ()
        super().commit()
        self.end_own_transaction()

    def rollback(self) -> None:
        self.prelude = ()
        super().rollback()
        self.end_own_transaction()

    def begin_in_pipeline(self, cursor: psycopg.Cursor[Any]) -> None:
        # Open a transaction with the pipeline's first command (#1915), where
        # psycopg's own BEGIN is a round trip of its own: it syncs after it.
        # The connection is then in autocommit for as long as the transaction
        # lasts -- psycopg's BEGIN is skipped, and autocommit cannot change
        # inside a transaction -- until its end turns it off again. Set before
        # the pipeline opens: inside one, setting it syncs, a round trip of its
        # own. Past the prelude, which goes with the statement after it, inside
        # the transaction; never prepared.
        assert self.autocommit
        psycopg.Cursor.execute(cursor, 'BEGIN', prepare=False)

    def end_own_transaction(self) -> None:
        # Back to psycopg's own transactions once one begun in a pipeline
        # has ended (#1915).
        connection: psycopg.Connection[Any] = self
        if (
            connection.autocommit
            and self.pgconn.transaction_status == psycopg.pq.TransactionStatus.IDLE
            and self.pgconn.pipeline_status == psycopg.pq.PipelineStatus.OFF
        ):
            connection.autocommit = False


# The SQLSTATE sys.ora_ddl_unchanged raises (#1889).
_SCHEMA_CHANGED = 'SDB01'
# Every DDL committed in the database adds a row to sys.ora_ddl_log, so that a
# session can tell its cached knowledge of the schema is stale when ANOTHER
# session changed it (#1887). A row per DDL rather than a counter in one row:
# an UPDATE would hold that row until the DDL commits, making concurrent DDL
# wait on each other. The generation is the row count with the highest id:
# a transaction that commits late adds an id below the highest, which the
# count still sees. The Mirror's own setup DDL, run at every connect, is not
# logged (seerdb.installing). An event trigger needs a superuser to create;
# without one the log is absent and nothing changes. The trigger's function
# runs for everyone's DDL, so it may not fail: an error in an event trigger
# fails the DDL that fired it.
_DDL_LOG_DDL = (
    'CREATE TABLE IF NOT EXISTS sys.ora_ddl_log (id bigserial PRIMARY KEY);'
    'CREATE OR REPLACE FUNCTION sys.ora_ddl_logged() RETURNS event_trigger '
    'LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$ BEGIN '
    # Only the installer's own setup DDL goes unlogged: the setting is any
    # session's to change (GHSA-336m-cp9c-m2fw).
    "IF current_setting('seerdb.installing', true) IS DISTINCT FROM 'on' OR "
    'session_user IS DISTINCT FROM (SELECT r.rolname FROM pg_roles r JOIN '
    "pg_namespace n ON n.nspowner = r.oid WHERE n.nspname = 'sys') THEN "
    'INSERT INTO sys.ora_ddl_log DEFAULT VALUES; END IF; '
    'EXCEPTION WHEN OTHERS THEN NULL; END $$;'
    'DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_event_trigger '
    "WHERE evtname = 'ora_ddl_log') THEN CREATE EVENT TRIGGER ora_ddl_log "
    'ON ddl_command_end EXECUTE FUNCTION sys.ora_ddl_logged(); END IF; END $$;'
)
# A statement rewritten from the schema runs behind this (#1889): it fails when
# the generation is no longer the one the rewrite was made at. Installed on its
# own, as a session whose role cannot replace the trigger's function still
# reads the log.
_DDL_GUARD_DDL = (
    'CREATE OR REPLACE FUNCTION sys.ora_ddl_unchanged(seen text) RETURNS void '
    'LANGUAGE plpgsql SET search_path = pg_catalog AS $$ BEGIN '
    "IF (SELECT count(*) || ':' || coalesce(max(id), 0) FROM sys.ora_ddl_log) "
    "IS DISTINCT FROM seen THEN RAISE EXCEPTION 'the schema changed' "
    f"USING ERRCODE = '{_SCHEMA_CHANGED}'; END IF; END $$;"
)
# Past this many rows the log is cut back to its last, at a connect; every
# session then reloads its schema knowledge once.
_DDL_LOG_KEPT = 200
_DDL_GENERATION = (
    "(SELECT count(*) || ':' || coalesce(max(id), 0) FROM sys.ora_ddl_log)"
)
# The transaction-id check (#1869), and with it the DDL generation (#1887).
_WRITTEN_CHECK = 'SELECT pg_current_xact_id_if_assigned() IS NULL'
# A query that may run with no transaction around it (#1916): a SELECT or a
# WITH, its literals masked, that takes no row lock, writes nothing it says so
# and opens no cursor -- whose portal would end with the transaction.
_PLAIN_QUERY = re.compile(r'\s*\(*\s*(?:SELECT|WITH)\b', re.IGNORECASE)
_NOT_A_PLAIN_QUERY = re.compile(
    r'\b(?:FOR\s+(?:NO\s+KEY\s+)?UPDATE|FOR\s+(?:KEY\s+)?SHARE|INSERT|UPDATE|DELETE|'
    r'MERGE|INTO|CURSOR)\b',
    re.IGNORECASE,
)


# Per-user mode (#1857): each Mirror user's session logs in to PostgreSQL as a
# role of its own, named as its schema is, which the Mirror makes on CREATE
# USER -- or at a configured account's first login -- and marks as its own.
# Every such role is a member of one group, which holds what they all may use
# of the installation: the dictionary to read, the records of their own to
# write (_USER_WRITTEN_RECORDS), a schema of its own for a package. Not the
# DBA's views and records, nor the translation report. PostgreSQL 16 is the
# floor: from it, a role with CREATEROLE manages only the roles it made. So
# the group is the installer's own, named after it: roles belong to the whole
# server, and another installer's group is not this one's to add members to.
_USER_GROUP_SUFFIX: Final = '_mirror_users'
# The group that reads the DBA's views (#2223): an administrator's role, and a
# role granted DBA (#1936), are members. The views run with the installer's
# rights, so they are all it needs, not the records under them.
_DBA_GROUP_SUFFIX: Final = '_mirror_dbas'
_DBA_VIEWS: Final = (
    'dba_directories',
    'proxy_users',
    'dba_sys_privs',
    'dba_role_privs',
)
_PER_USER_FLOOR: Final = 160000
# The schemas the installation makes: the dictionary's, and those of the Oracle
# packages it emulates, which a user's statements call into.
_INSTALLED_SCHEMAS: Final = (
    'sys',
    'system',
    'dbms_application_info',
    'dbms_debug_jdwp',
    'dbms_lob',
    'dbms_lock',
    'dbms_session',
    'dbms_sql',
    'dbms_utility',
)


def _scram_verifier(password: str, iterations: int = 4096) -> str:
    """A role's SCRAM-SHA-256 verifier, as PostgreSQL stores it (RFC 7677).

    Handed to CREATE / ALTER ROLE in place of the plaintext, which a server
    that logs its DDL would otherwise write down (GHSA-27rj-h7p6-pmqf). The
    Mirror's role passwords are its own, URL-safe ASCII, so SASLprep leaves
    them as they are.
    """
    salt = secrets.token_bytes(16)
    salted = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    stored = hashlib.sha256(hmac.new(salted, b'Client Key', 'sha256').digest()).digest()
    server = hmac.new(salted, b'Server Key', 'sha256').digest()
    encode = base64.b64encode
    return (
        f'SCRAM-SHA-256${iterations}:{encode(salt).decode()}$'
        f'{encode(stored).decode()}:{encode(server).decode()}'
    )


class _RoleUnverified(Exception):
    # A per-user login's role that its own connection could not verify, or an
    # installation not there to use (#1939): the login goes the installer's
    # way instead, which makes or repairs the role.
    pass


def _user_group_grants(group: str) -> str:
    # The group's grants on what this installation has: a part of it that
    # failed to install -- one that needs a superuser, say -- made no schema or
    # table to grant.
    def names(values: Iterable[str]) -> str:
        return 'ARRAY[' + ', '.join(_sql_text(value) for value in values) + ']'

    private = (
        'dba_directories',
        'proxy_users',
        'ora_proxy_grants',
        'ora_sys_privs',
        'dba_sys_privs',
        'dba_role_privs',
        # Who each open proxy session's proxy is: a session reads its own
        # through sys.ora_session_proxy() (GHSA-6qw5-v992-69fx).
        'ora_session_proxies',
        'ora_translation_log',
    )
    return (
        f'DO $$ DECLARE g text := {_sql_text(group)}; s text; t text; BEGIN '
        f'FOREACH s IN ARRAY {names(_INSTALLED_SCHEMAS)} LOOP '
        'IF to_regnamespace(quote_ident(s)) IS NOT NULL THEN '
        "EXECUTE format('GRANT USAGE ON SCHEMA %I TO %I', s, g); END IF; END LOOP; "
        "EXECUTE format('GRANT SELECT ON ALL TABLES IN SCHEMA sys TO %I', g); "
        # The product profile sqlplus reads at login (#2107).
        "IF to_regclass('system.product_privs') IS NOT NULL THEN "
        "EXECUTE format('GRANT SELECT ON system.product_privs TO %I', g); END IF; "
        "EXECUTE format('GRANT USAGE ON ALL SEQUENCES IN SCHEMA sys TO %I', g); "
        f'FOREACH t IN ARRAY {names(private)} LOOP '
        "IF to_regclass('sys.' || quote_ident(t)) IS NOT NULL THEN "
        "EXECUTE format('REVOKE SELECT ON sys.%I FROM %I', t, g); END IF; END LOOP; "
        f'FOREACH t IN ARRAY {names(_USER_WRITTEN_RECORDS)} LOOP '
        "IF to_regclass('sys.' || quote_ident(t)) IS NOT NULL THEN "
        "EXECUTE format('GRANT INSERT, UPDATE, DELETE ON sys.%I TO %I', t, g); "
        'END IF; END LOOP; '
        "EXECUTE format('GRANT CREATE ON DATABASE %I TO %I', current_database(), g); "
        'END $$'
    )


def _dba_group_grants(group: str) -> str:
    # The DBAs' group's grants: SELECT on each DBA view this installation has.
    views = 'ARRAY[' + ', '.join(_sql_text(v) for v in _DBA_VIEWS) + ']'
    return (
        f'DO $$ DECLARE g text := {_sql_text(group)}; v text; BEGIN '
        f'FOREACH v IN ARRAY {views} LOOP '
        "IF to_regclass('sys.' || quote_ident(v)) IS NOT NULL THEN "
        "EXECUTE format('GRANT SELECT ON sys.%I TO %I', v, g); END IF; END LOOP; "
        'END $$'
    )


def _dba_group(group: str) -> str:
    # The DBAs' group's name, from the users' group's: both the installer's.
    return group.removesuffix(_USER_GROUP_SUFFIX) + _DBA_GROUP_SUFFIX


# The databases whose group grants this process has made, so each is done once
# per process: a later process makes them again, after a dictionary that may
# have new tables.
_USER_GROUP_READY: dict[str, str] = {}
# ORA-01940, a DROP USER of a user with a session open (#1857).
_ORA_USER_CONNECTED = 1940


# A column's own value stands for NVL(column, x) only where the two compare
# alike: not a CHAR, which compares blank-padded where COALESCE's text would
# not, nor a domain (#1889).
_NVL_DROPPABLE_OIDS = frozenset(
    _NUMBER_OIDS | _BINARY_FLOAT_OIDS.keys() | _TEMPORAL_OIDS.keys() | {25, 1043}
)
_SQL_NAME = r'(?:"[^"]*"|[A-Za-z_][\w$#]*)'
# A FROM / UPDATE naming one table, optionally aliased (#1889).
_ONE_TABLE = re.compile(
    rf'\s*({_SQL_NAME}(?:\s*\.\s*{_SQL_NAME})?)(?:\s+(?:AS\s+)?({_SQL_NAME}))?\s*',
    re.IGNORECASE,
)
_COALESCE_CALL = re.compile(r'(?<![\w$#."])COALESCE\s*\(', re.IGNORECASE)
_COLUMN_REFERENCE = re.compile(rf'\s*(?:({_SQL_NAME})\s*\.\s*)?({_SQL_NAME})\s*')
# Any of these at the top level makes a statement more than one table's.
_NOT_ONE_TABLE = frozenset(
    {
        'JOIN',
        'UNION',
        'INTERSECT',
        'MINUS',
        'EXCEPT',
        'CONNECT',
        'START',
        'WITH',
        'LATERAL',
        'PIVOT',
        'UNPIVOT',
        'MODEL',
        'MATCH_RECOGNIZE',
    }
)
# The words that end a WHERE clause.
_AFTER_WHERE = frozenset(
    {'GROUP', 'HAVING', 'ORDER', 'FOR', 'RETURNING', 'FETCH', 'OFFSET', 'LIMIT'}
)


def _folded_name(name: str, contents: Sequence[str]) -> str:
    # A masked identifier as PostgreSQL resolves it: a quoted one as written,
    # any other folded to lower case.
    if name.startswith('"'):
        return _unmask_quoted(name, list(contents))[1:-1]
    return name.lower()


def _dead_nvl_candidates(
    sql: str,
) -> (
    tuple[
        str,
        tuple[str, ...],
        str,
        set[str],
        list[tuple[int, int, str, str | None, str]],
    ]
    | None
):
    # For a statement over one table with no subquery (#1889): the statement
    # masked (_masked_quoted) and its masked contents, the table as written,
    # the names its columns may be qualified by, and each COALESCE call in its
    # WHERE clause whose first argument is a column -- the call's span in the
    # masked text, the column as masked, its qualifier and its name, both
    # folded. None for any other statement.
    if 'coalesce' not in sql.lower():
        return None
    (masked, contents) = _masked_quoted(sql)
    (words, _rownums) = _top_level_words(masked)
    if not words or words[0][1] not in ('SELECT', 'UPDATE', 'DELETE'):
        return None
    kinds = [word for _at, word in words]
    selects = len(re.findall(r'(?i)\bSELECT\b', masked))
    if (
        _NOT_ONE_TABLE.intersection(kinds)
        or selects != (kinds[0] == 'SELECT')
        or re.search(r'\(\s*\+\s*\)', masked)
        or kinds.count('WHERE') != 1
    ):
        return None
    where = words[kinds.index('WHERE')][0]
    head = 'SET' if kinds[0] == 'UPDATE' else 'FROM'
    if kinds.count(head) != 1:
        return None
    at = words[kinds.index(head)][0]
    table_text = (
        masked[words[0][0] + len('UPDATE') : at]
        if head == 'SET'
        else masked[at + len(head) : where]
    )
    if head == 'SET' and at > where or not (one := _ONE_TABLE.fullmatch(table_text)):
        return None
    table = _unmask_quoted(one.group(1), list(contents))
    qualifier = one.group(2) or re.split(r'\s*\.\s*', one.group(1))[-1]
    end = next(
        (at for at, word in words if at > where and word in _AFTER_WHERE), len(masked)
    )
    calls: list[tuple[int, int, str, str | None, str]] = []
    for call in _COALESCE_CALL.finditer(masked, where, end):
        if calls and call.start() < calls[-1][1]:
            continue
        opening = call.end() - 1
        closing = _matching_paren(masked, opening)
        items = _top_level_items(masked, opening + 1, closing)
        if closing >= len(masked) or len(items) < 2:
            continue
        reference = _COLUMN_REFERENCE.fullmatch(masked, *items[0])
        if reference is None:
            continue
        calls.append(
            (
                call.start(),
                closing + 1,
                masked[items[0][0] : items[0][1]].strip(),
                None
                if reference.group(1) is None
                else _folded_name(reference.group(1), contents),
                _folded_name(reference.group(2), contents),
            )
        )
    if not calls:
        return None
    return (masked, contents, table, {_folded_name(qualifier, contents)}, calls)


# A CREATE INDEX up to its key list's `(` (#1897): the table it is on.
_CREATE_INDEX_KEYS = re.compile(
    rf'\s*CREATE\s+(?:UNIQUE\s+)?INDEX\s+(?:IF\s+NOT\s+EXISTS\s+)?{_SQL_NAME}\s+'
    rf'ON\s+({_SQL_NAME}(?:\s*\.\s*{_SQL_NAME})?)\s*\(',
    re.IGNORECASE,
)
# One key of that list that is a bare column, ASC or DESC.
_INDEX_KEY = re.compile(rf'\s*({_SQL_NAME})(\s+(?:ASC|DESC))?\s*', re.IGNORECASE)


def _index_key_spans(
    sql: str,
) -> tuple[str, tuple[str, ...], str, list[tuple[int, int, str]]] | None:
    # For a CREATE INDEX (#1897): the statement masked (_masked_quoted) and
    # its masked contents, the table as written, and the span in the masked
    # text of each key that is a bare column, with that column's name as
    # PostgreSQL resolves it. None for any other statement.
    (masked, contents) = _masked_quoted(sql)
    head = _CREATE_INDEX_KEYS.match(masked)
    if head is None:
        return None
    table = _unmask_quoted(head.group(1), list(contents))
    keys = []
    for start, stop in _top_level_items(
        masked, head.end(), _matching_paren(masked, head.end() - 1)
    ):
        key = _INDEX_KEY.fullmatch(masked, start, stop)
        if key is not None:
            keys.append(
                (key.start(1), key.end(1), _folded_name(key.group(1), contents))
            )
    return (masked, contents, table, keys)


# What the installed database is stamped with, as the `system` schema's
# comment (#1871): a digest of every DDL statement a setup runs -- the types,
# the helpers, the packages, the dictionary, the DDL log -- and the extensions
# present when it ran, so a seerdb whose installation differs, or a database
# that gained or lost orafce or pgvector, installs again. A matching stamp
# skips the installation: no CREATE OR REPLACE a connect.
_INSTALLATION_DIGEST: Final = hashlib.sha256(
    '\x00'.join(
        (
            _BFILE_TYPE_DDL,
            _TSTZ_TYPE_DDL,
            _LOB_TYPE_DDL,
            _INTERVALYM_TYPE_DDL,
            _DATE_TYPE_DDL,
            _ROWID_TYPE_DDL,
            _DATE_ARITHMETIC_DDL,
            _HELPER_FUNCTIONS_DDL,
            _ORAFCE_HELPERS_DDL,
            _UTL_RAW_DDL,
            _DBMS_UTILITY_DDL,
            _DBMS_SLEEP_DDL,
            _DBMS_APPLICATION_INFO_DDL,
            _DBMS_SQL_RETURN_RESULT_DDL,
            _DBMS_OUTPUT_LINES_DDL,
            _VECTOR_DDL,
            _DICTIONARY_STAMP,
            _DDL_LOG_DDL,
            _DDL_GUARD_DDL,
        )
    ).encode()
).hexdigest()
# The setup's parts that need an extension the database may not have: one
# that failed for want of it does not keep the stamp from being written.
_EXTENSION_PARTS: Final = {
    'orafce': 'orafce',
    'orafce helpers': 'orafce',
    'vector': 'vector',
}
# The setup's parts that need privileges a deployment may not grant (an
# event trigger needs a superuser): best effort, as they always were.
_PRIVILEGED_PARTS: Final = frozenset({'ddl log', 'ddl guard', 'utl_raw'})


# The oldest orafce the backend serves from (#800): 4.17 ships UTL_RAW, HEXTORAW
# and RAWTOHEX, which the backend no longer installs itself.
_ORAFCE_FLOOR: Final = (4, 17)


def _refused_orafce(version: str | None) -> str | None:
    # Why a database's orafce is refused, or None. An older one leaves UTL_RAW,
    # HEXTORAW and RAWTOHEX missing. A database without orafce is not refused:
    # the backend starts without it, and the idioms it covers fail as before.
    if version is None:
        return None
    try:
        found = tuple(int(part) for part in version.split('.')[:2])
    except ValueError:
        return None
    if found >= _ORAFCE_FLOOR:
        return None
    return (
        f'orafce {version} is installed in the database; the Mirror needs 4.17 '
        'or later. Run ALTER EXTENSION orafce UPDATE as its owner; if a Mirror '
        'before this release made a utl_raw schema of its own, that update '
        'fails on it, so drop that schema first'
    )


def _installation_stamp(extensions: str | None) -> str:
    return f'seerdb installation {_INSTALLATION_DIGEST} {extensions or ""}'.rstrip()


class _Installation(NamedTuple):
    # What a session's setup looks up in an installed database (#1871): the
    # types it registers adapters for and the catalogs it checks for. The same
    # for every session of one installation, so a process looks it up once.
    vector: tuple[int, int, int, CompositeInfo, CompositeInfo] | None
    tstz: CompositeInfo | None
    bfile: CompositeInfo | None
    domain_oids: dict[str, int]
    clob: Any
    blob: Any
    date: Any
    catalogs: tuple[bool, ...]


# Each installation a process has looked up, by its connection string, the
# database's oid and the installation stamp (#1871).
_INSTALLATIONS: dict[tuple[str, int, str], _Installation] = {}


class _TableColumn(NamedTuple):
    # A table column as the schema model knows it (#1887).
    name: str
    type_oid: int  # its declared type: a domain, where a result reports the base
    not_null: bool
    quoted: bool  # created with a quoted all-lower-case name (#1204)
    json: bool  # checked IS JSON (#1626)
    declared: tuple | None  # sys.ora_columns: type, length, precision, scale (#1386)
    tstz_precision: int | None  # a WITH TIME ZONE column's precision (#1308)
    invisible: bool  # INVISIBLE (#1195)
    typmod: int  # PostgreSQL's: a TIMESTAMP(p)'s p, -1 for none (#2162)


class PostgresBackend:
    """A :class:`~seerdb.server.Backend` over a psycopg connection.

    One instance per Mirror session. ``conninfo`` is a libpq connection string,
    e.g. ``host=127.0.0.1 port=5432 user=pyo password=... dbname=mirror``.

    The connection is transactional (``autocommit`` off), so the Mirror's
    commit / rollback are real: work persists only on commit and is discarded on
    rollback. Each statement runs inside an implicit ``SAVEPOINT`` so a failed
    statement rolls back only itself — the transaction (and any earlier
    uncommitted work) survives, matching Oracle's statement-level error model
    rather than PostgreSQL's abort-the-whole-transaction default.
    """

    capabilities = frozenset({Capability.TRANSACTIONS})
    # The sessionless transaction a session holds (#1746); none until begun,
    # also on a backend a test builds without __init__.
    _sessionless_id: bytes | None = None
    # Whether native PostgreSQL SQL is allowed (#1859); off on a backend a
    # test builds without __init__ too.
    _native_sql = False
    # The PostgreSQL text of the statement last run (#1881).
    _last_translated: str | None = None
    # This demo speaks the 12.1 WIRE protocol (field version), which is also the
    # release it reports (server_identity). Those were deliberately apart while
    # the wire was 11.2: the dialect reads the RELEASE to pick native
    # OFFSET/FETCH pagination and identity columns -- both of which PostgreSQL
    # runs directly -- instead of Oracle's nested-ROWNUM pagination, which has no
    # faithful PostgreSQL rewrite (#33). They now agree.
    #
    # 12.1 rather than 12.2, and deliberately: a modern thin client refuses any
    # server below protocol version 315, which is 12.1's, so this is the LOWEST
    # version at which one will talk to the Mirror at all (#1127). Going to 12.2
    # was measured too and costs far more -- and a client can negotiate DOWN to
    # 12.1 whichever we advertise, so 12.1 has to work regardless.
    field_version = FIELD_VERSION_12_1
    server_identity = IDENTITY_12_1
    # This backend has Oracle's DUAL (orafce's, and sys.dual), so the compat
    # wrapper hands it `... FROM DUAL` as the client sent it: the translation
    # report then sees the application's own text (#1561).
    has_dual = True

    def __init__(
        self,
        conninfo: str = '',
        *,
        credentials: Credentials | None = None,
        translation_report: bool = False,
        auth_conninfo: str | None = None,
        presents: str = '12.1',
        native_sql: bool = False,
        per_user_roles: bool = False,
    ) -> None:
        if per_user_roles and auth_conninfo is None:
            # A role's password is kept with its account (#1857).
            raise ValueError('per-user roles need an auth database (auth_conninfo)')
        if presents not in _PRESENTABLE:
            raise ValueError(
                f'presents must be one of {", ".join(_PRESENTABLE)}, not {presents!r}'
            )
        # The release this backend presents (#1704): its own wire field version
        # and identity, which the Mirror reads off it per session.
        (self.field_version, self.server_identity) = _PRESENTABLE[presents]
        release = _banner_release(self.server_identity.banner)
        (major, minor) = (int(part) for part in release.split('.')[:2])
        self._release = (major, minor)
        # Shared, not copied, when a dict is given: a launcher hands one map to
        # every backend it creates, and ALTER USER ... IDENTIFIED BY rewrites an
        # entry in place so the new password reaches the next login. A read-only
        # mapping is copied into a dict the rewrite can touch.
        self._credentials: dict[str, str] = (
            credentials if isinstance(credentials, dict) else dict(credentials or {})
        )
        # Where the accounts live: that map, or an auth database (#879).
        self._accounts = _AccountStore(self._credentials, auth_conninfo)
        # Per-user mode (#1857): each session runs as its user's own role once
        # the login checks out (open_session), and the connection string's
        # role -- the installer's -- does on its own connection only what a
        # DBA may: users, proxy grants, directories, editions, killing a
        # session. It needs PostgreSQL 16 and a role that may make roles.
        self._per_user = per_user_roles
        self._admin_conninfo = conninfo
        self._presents = presents
        # The translation report's switch, and whether a client may run
        # native PostgreSQL SQL at all (#1859): the operator's choice, off
        # unless the launcher turns it on. Off, a PG hint is a hint Oracle does
        # not know, and the session's dialect can't be switched.
        self._options = (translation_report, native_sql)
        # Whether the session has its PostgreSQL connection yet, and whether
        # it is the login user's own role's, made at login (#1939).
        self._connected = False
        self._became = False
        if per_user_roles and conninfo in _USER_GROUP_READY:
            # Per-user mode, once this process has set the installation up
            # and the users' group (#1939): the session connects at login,
            # straight as its user's role (authenticate), not first as the
            # installer only to swap the connection for the user's.
            self._conninfo = conninfo
            return
        self._connect(conninfo)

    def _connect(self, conninfo: str, role: str | None = None) -> None:
        """The session's PostgreSQL connection, set up: the presented
        release in its settings, the installation checked -- installed where
        it is missing or changed -- and what the session reads of it.

        With ``role``, per-user mode's login user (#1939), the connection is
        that user's role's, and the role is checked in the same round trip:
        marked as the Mirror's, made by this installer, a member of the
        users' group. A role that is not, or an installation that is not
        there, raises ``_RoleUnverified`` before anything is installed, for
        the installer's connection to put right."""
        release = _banner_release(self.server_identity.banner)
        (major, minor) = self._release
        group = _USER_GROUP_READY.get(self._admin_conninfo, '')
        self._conn = _CountedConnection.connect(conninfo, cursor_factory=_CountedCursor)
        # V$VERSION and DBMS_UTILITY.DB_VERSION read the presented release from
        # the session (#1704), so the shared dictionary serves either release.
        # In the same statement: whether the database's installation is this
        # seerdb's (#1871), which a connect then leaves alone.
        setup = self._at_once(
            "SELECT set_config('seerdb.release', %s, false), "
            "set_config('seerdb.banner', %s, false), "
            "set_config('seerdb.compatibility', %s, false), "
            "obj_description(to_regnamespace('system'), 'pg_namespace'), "
            "obj_description(to_regnamespace('sys'), 'pg_namespace'), "
            "(SELECT string_agg(extname, ' ' ORDER BY extname) FROM pg_extension "
            "WHERE extname IN ('orafce', 'vector')), "
            '(SELECT oid FROM pg_database WHERE datname = current_database()), '
            # The login user's role, checked as _ensure_user_role's fast path
            # checks it (#1939); any connection's is good.
            'CASE WHEN %s THEN coalesce((SELECT shobj_description(r.oid, '
            "'pg_authid') = %s AND pg_has_role(%s::text, r.oid, 'USAGE') AND "
            "pg_has_role(r.oid, %s::text, 'MEMBER') FROM pg_roles r "
            'WHERE r.rolname = current_user), false) ELSE true END, '
            # The data version the database's records are at (#1862).
            "obj_description(to_regclass('sys.ora_data_version'), 'pg_class')",
            (
                release,
                self.server_identity.banner.decode(),
                f'{major}.{minor if major < 18 else 0}.0.0.0',
                role is not None,
                _USER_ROLE_MARK,
                group.removesuffix(_USER_GROUP_SUFFIX),
                group,
            ),
        ).fetchone()
        assert setup is not None
        expected = _installation_stamp(setup[5])
        data_version = _refused_data_version(setup[8], setup[4] is not None)
        if isinstance(data_version, str):
            self._conn.close()
            raise UnsupportedFeature(data_version)
        # A database whose records are due an upgrade goes the installation's
        # way too, which runs it, the dictionary unchanged or not (#1862).
        installed = (
            setup[3] == expected
            and setup[4] == _DICTIONARY_STAMP
            and (data_version is None or data_version >= _DATA_VERSION)
        )
        if role is not None and not (installed and setup[7]):
            self._conn.close()
            raise _RoleUnverified(role)
        # Keyed by the installer's connection string, so each user's role's
        # session finds the one installation too (#1939).
        found = (
            _INSTALLATIONS.get((self._admin_conninfo, setup[6], expected))
            if installed
            else None
        )
        # The parts of the setup that failed, by name; the setup's own DDL is
        # not another session's change (#1887).
        self._install_failures: list[str] = []
        if not installed:
            self._at_once("SET seerdb.installing = 'on'")
            if data_version is not None and data_version < _DATA_VERSION:
                # Before the dictionary is installed again, which may need
                # the records in their new shape (#1862).
                self._upgrade_data(data_version)
        # What a twin of this backend is built from: a sessionless suspend
        # takes a fresh connection, set up as this one was, from it (#1746).
        self._twin: Callable[[], PostgresBackend] = lambda: type(self)(
            conninfo,
            credentials=self._credentials,
            auth_conninfo=self._accounts.auth_conninfo,
            presents=self._presents,
        )
        self._sessionless_id = None
        # The translation report (#1557): whether it is on, the runs it has not
        # written yet, and its own autocommit connection, opened when it first
        # writes -- so writing it never joins, ends or aborts the client's
        # transaction.
        self._conninfo = conninfo
        (self._reporting, self._native_sql) = self._options
        self._report_runs: dict[str, _ReportEntry] = {}
        self._report_conn: psycopg.Connection | None = None
        # psycopg prepares a statement on the server from its fifth run, which
        # saves PostgreSQL planning it again: half the cost of a query on the
        # dictionary views (#1885). Two things kept it off before. The Mirror's
        # own statements around an application's are never prepared
        # (_CONTROL_STATEMENT), and a prepared statement that another session's
        # DDL changed the shape of runs once more (_replanned).
        self._conn.prepare_threshold = 5
        # Whether a routine the running call reached asked for a commit (#1630).
        self._commit_requested = False
        self._conn.add_notice_handler(self._hear_commit_request)
        # The portals the running call returned as implicit results (#1617).
        self._implicit_portals: list[str] = []
        self._conn.add_notice_handler(self._hear_implicit_result)
        if self._per_user and role is None:
            row = self._at_once(
                "SELECT current_setting('server_version_num')::int, "
                'rolsuper OR rolcreaterole FROM pg_roles WHERE rolname = current_user'
            ).fetchone()
            if row is None or row[0] < _PER_USER_FLOOR:
                raise UnsupportedFeature('per-user roles need PostgreSQL 16 or later')
            if not row[1]:
                raise UnsupportedFeature(
                    'per-user roles need a connection role with CREATEROLE'
                )
        # Index-organized tables this session created, with their primary-key
        # columns, for the logical-rowid rendering.
        self._iot_pk: dict[str, list[str]] = {}
        # Whether the client has taken a SAVEPOINT in the open transaction, which
        # a transaction that has written nothing must keep for it (#1190).
        self._user_savepoint = False
        # The session's transaction priority (#1779). PostgreSQL has no priority
        # transactions, so it is session state only: set, kept and reported back
        # as 23ai reports it, HIGH by default, with nothing behind it.
        self._txn_priority = 'HIGH'
        # The SQL dialect a statement with no PG hint is in (#1556): 'oracle',
        # translated, or 'postgres', run as written.
        self._sql_dialect = 'oracle'
        # The Oracle object type each PostgreSQL composite oid stands for, with
        # its registered psycopg CompositeInfo -- or None for an oid that is not
        # an object type, so a column of it is looked up once (#1127).
        self._object_types: dict[int, tuple[DbObjectType, CompositeInfo] | None] = {}
        # REFs (#1127): each `<type>$ref` composite's target type (None for any
        # other composite), and the registered companion per target type.
        self._ref_targets: dict[int, int | None] = {}
        self._ref_composites: dict[int, CompositeInfo] = {}
        # Collections (#1206): the collection type each array-domain oid stands
        # for (None for any other type), and whether a result oid is an array at
        # all; an array column's declared type is the schema model's.
        self._collection_types: dict[int, DbObjectType | None] = {}
        # The attribute types being described, so a type that reached itself
        # would be refused rather than recursed into (#1265).
        self._describing: set[int] = set()
        self._array_oids: dict[int, bool] = {}
        # Pipeline mode ships a statement's SAVEPOINT / statement / RELEASE in one
        # network round-trip instead of three (a 3x per-statement latency cut
        # against a remote database). It needs libpq >= 14; older builds fall back
        # to the sequential path.
        try:
            self._use_pipeline = psycopg.pq.version() >= 140000
        except Exception:
            self._use_pipeline = False
        self._conn.adapters.register_dumper(_PortalName, _PortalNameDumper)
        self._conn.adapters.register_dumper(JSON, _JsonDumper)
        self._conn.adapters.register_dumper(_TypedNull, _TypedNullDumper)
        self._conn.adapters.register_dumper(_OraNumber, _IntNumericDumper)
        # The portals opened for cursors bound IN, numbered (#1609).
        self._portals_opened = 0
        # Lean on the `orafce` extension for Oracle-compatible SQL functions —
        # nvl, decode, to_char / to_date, add_months, instr, and much more —
        # rather than hand-rolling each rewrite. It installs those into the
        # `oracle` schema, so put it on the search_path; then only the idioms
        # orafce does NOT cover are translated in _translate_idioms. orafce is a
        # requirement of this backend (see the module docstring). Best-effort so a
        # PostgreSQL without it still starts — the uncovered idioms just fail as
        # before.
        if not installed:
            self._install_part('orafce', 'CREATE EXTENSION IF NOT EXISTS orafce')
            orafce = self._conn.execute(
                "SELECT extversion FROM pg_extension WHERE extname = 'orafce'"
            ).fetchone()
            refused = _refused_orafce(orafce[0] if orafce else None)
            if refused is not None:
                self._conn.close()
                raise UnsupportedFeature(refused)
        # pgvector, which Oracle's VECTOR types map onto (#1708), where it is
        # installed; without it a VECTOR column is refused, as before.
        # Under a savepoint, so a server without it keeps orafce. Its `vector`
        # type, and the ora_vector composite of a flexible-format column, are
        # what a VECTOR value reads back as (#1708).
        self._has_pgvector = False
        self._vector_oid: int | None = None
        self._vector_composite_oid: int | None = None
        # SQL domains and annotations (#1711).
        self._has_sql_domains_cache: bool | None = None
        self._sql_domain_cache: dict[
            tuple[int, int], tuple[bytes, bytes, tuple[tuple[bytes, bytes], ...]] | None
        ] = {}
        self._sparse_composite_oid: int | None = None
        if not installed:
            try:
                with self._conn.transaction():
                    self._conn.execute('CREATE EXTENSION IF NOT EXISTS vector')
                    # Its helpers live in sys, which a new database does not have
                    # yet at this point of the setup; and are made once, not by
                    # every session -- sessions starting together raced on them.
                    self._conn.execute('CREATE SCHEMA IF NOT EXISTS sys')
                    # Stamped, as the dictionary is, so a changed one is installed
                    # again and an unchanged one is not.
                    stamp = self._conn.execute(
                        'SELECT obj_description(to_regtype(%s), %s)',
                        (_VECTOR_COMPOSITE, 'pg_type'),
                    ).fetchone()
                    if stamp is None or stamp[0] != _VECTOR_STAMP:
                        self._conn.execute(_VECTOR_DDL)
                        self._conn.execute(
                            f"COMMENT ON TYPE {_VECTOR_COMPOSITE} IS '{_VECTOR_STAMP}'"
                        )
            except psycopg.Error:
                self._install_failures.append('vector')
            # plpgsql_check, where it is installed (#2129), which resolves a
            # PL/SQL unit's names when it is created, as Oracle's compiler
            # does. Optional: without it a unit compiles as before.
            try:
                with self._conn.transaction():
                    self._conn.execute('CREATE EXTENSION IF NOT EXISTS plpgsql_check')
            except psycopg.Error:
                pass
        # What this session has, whichever session's setup made it: looked up
        # here, before the search_path below, where the types were made.
        vector = found.vector if found is not None else self._look_up_vector()
        if vector is not None:
            (vector_oid, composite_oid, sparse_oid, composite, sparse) = vector
            register_composite(composite, self._conn)
            register_composite(sparse, self._conn)
            (self._vector_oid, self._vector_composite_oid) = (vector_oid, composite_oid)
            self._sparse_composite_oid = sparse_oid
            self._conn.adapters.register_dumper(
                SparseVector,
                type('_SparseBindDumper', (_SparseVectorDumper,), {'oid': sparse_oid}),
            )
            self._has_pgvector = True
            # A vector bind is the composite: its format travels with it,
            # and an assignment cast makes it any VECTOR column's storage.
            self._conn.adapters.register_dumper(
                array.array,
                type('_VectorBindDumper', (_VectorDumper,), {'oid': composite_oid}),
            )
        # The Oracle data dictionary (#759) lives in a dedicated `sys` schema —
        # like Oracle's SYS — so its views are never reflected as user objects.
        # SYSTEM is a user every Oracle database has, so a client may point its
        # session at it (ALTER SESSION SET CURRENT_SCHEMA = SYSTEM). That
        # becomes a search_path, and PostgreSQL's current_schema() passes over
        # a schema that does not exist -- the session stayed where it was and
        # SYS_CONTEXT went on naming it. An empty one is enough; its comment
        # is the installation's stamp.
        if not installed:
            self._install_part(
                'schemas',
                'CREATE SCHEMA IF NOT EXISTS sys; CREATE SCHEMA IF NOT EXISTS system',
            )
        # `sys` ahead of `oracle`: orafce ships its own `user_tables` and
        # `user_tab_columns` in the `oracle` schema, and they select from
        # information_schema with no owner filter at all -- every base table in
        # the database, PostgreSQL's own catalogs included, reported as though
        # the connected user owned them. Those are the only two names the two
        # schemas share, so this ordering changes nothing else: user objects
        # still resolve first through the schema ahead of both, and the rest of
        # orafce is still reached through `oracle` (#818).
        self._at_once(
            f'SET search_path TO {_SEARCH_PATH_TAIL}; {_ORAFCE_SESSION_SETTINGS}'
        )
        # The composite that backs TIMESTAMP WITH TIME ZONE, registered so its
        # columns come back as a typed tuple the read path can re-tag with the
        # entered offset (#519); the BFILE composite (#1669), read back as a
        # tuple of the two names; and the typed domains, each domain's oid mapped
        # to the Oracle wire type it stands for, so a result column tracing back
        # to one is encoded as that Oracle type -- ora_clob / ora_blob as a LOB
        # (#534), ora_intervalym as INTERVAL YEAR TO MONTH (#504). Best-effort:
        # a backend that can't create them leaves those types unsupported. The
        # ora_intervalym oid is kept on its own for the OUT-bind path, which has
        # no result column to trace and matches on the arg type.
        self._tstz_oid: int | None = None
        self._tstz_info: CompositeInfo | None = None
        self._bfile_oid: int | None = None
        self._intervalym_oid: int | None = None
        self._oson_oid: int | None = None
        self._domain_type_by_oid: dict[int, int] = {}
        if not installed:
            self._install_part('tstz', _TSTZ_TYPE_DDL)
            self._install_part('bfile', _BFILE_TYPE_DDL)
            self._install_part(
                'domains',
                _LOB_TYPE_DDL,
                _INTERVALYM_TYPE_DDL,
                _DATE_TYPE_DDL,
                _DATE_ARITHMETIC_DDL,
                _ROWID_TYPE_DDL,
            )
            # The Oracle scalar helper functions (empty_clob / empty_blob,
            # from_tz), so those call sites need no rewrite (#513);
            # empty_clob / empty_blob return the LOB domains just created, so
            # this runs after them. The helpers that need orafce go apart, so
            # they cannot take the others down without it (#1299). Then UTL_RAW's
            # hex-text overloads (#1496), DBMS_UTILITY (#764), DBMS_LOCK.SLEEP / DBMS_SESSION.SLEEP
            # (#1511), DBMS_APPLICATION_INFO (#1840), DBMS_SQL.RETURN_RESULT
            # (#1617) and DBMS_OUTPUT.GET_LINES's collection type (#1411).
            for part, ddl in (
                ('helpers', _HELPER_FUNCTIONS_DDL),
                ('orafce helpers', _ORAFCE_HELPERS_DDL),
                ('utl_raw', _UTL_RAW_DDL),
                ('dbms_utility', _DBMS_UTILITY_DDL),
                ('dbms_sleep', _DBMS_SLEEP_DDL),
                ('dbms_application_info', _DBMS_APPLICATION_INFO_DDL),
                ('dbms_sql', _DBMS_SQL_RETURN_RESULT_DDL),
                ('dbms_output', _DBMS_OUTPUT_LINES_DDL),
            ):
                self._install_part(part, ddl)
        # Oracle data-dictionary emulation (#759): SYS_CONTEXT + catalog views.
        # Installed only when missing or changed, not on every connect: CREATE
        # OR REPLACE VIEW takes an exclusive lock, so a client reading one of the
        # views inside an open transaction made every new connection wait for
        # it to end -- a login hang one step removed from its cause (#1152).
        # When it does run -- a first install, or a seerdb whose views differ --
        # a held view makes it give up after a short wait rather than hang; the
        # session then works with the views already there, and a later
        # connection installs them. Committed first, so a give-up here cannot
        # take the helpers above down with it.
        self._conn.commit()
        if not installed:
            try:
                self._install_dictionary()
            except psycopg.Error:
                self._conn.rollback()
            self._conn.commit()
        # The DDL log (#1887), whose generation is the session's own.
        self._ddl_generation: str | None = None
        self._install_ddl_log(install=not installed)
        if found is None:
            found = self._look_up_installation(vector)
            if installed or self._stamp_installation():
                stamped = self._conn.execute(
                    "SELECT obj_description(to_regnamespace('system'), 'pg_namespace')"
                ).fetchone()
                if stamped is not None and stamped[0] is not None:
                    _INSTALLATIONS[(self._admin_conninfo, setup[6], stamped[0])] = found
        self._adopt_installation(found)
        # The quoted-name catalog (#1204) comes with the dictionary; a session
        # whose dictionary could not be installed does without it, and so with
        # the other catalogs below.
        (
            self._has_quoted_names,
            self._has_tstz_precision,
            self._has_invisible_catalog,
            self._has_column_catalog,
            self._has_collection_elements,
            self._has_package_catalog,
            self._has_ddl_guard,
            self._has_ddl_log,
        ) = found.catalogs
        # The schema model (#1887): each relation's columns by attnum, as a
        # result column traced to one describes it, read in one query for the
        # relations a result names; any DDL starts it over.
        self._relations: dict[int, dict[int, _TableColumn]] = {}
        # INVISIBLE columns (#1195): whether any table has one (None: not yet
        # read; reset by any DDL), and the visible columns of the tables that
        # do. Declared Oracle column types (#1386) are the schema model's. A
        # package's types (#1607): each PostgreSQL type's -- None for one that
        # is no package's; any DDL starts it over.
        self._plsql_types: dict[int, tuple[str, str, str, dict] | None] = {}
        self._collection_name_cache: frozenset[str] | None = None
        # Each package's functions a call may name without parentheses (#1651).
        self._package_function_cache: dict[str, frozenset[str]] | None = None
        # The names synonyms give for sequences, routines and packages, and
        # what each is rewritten to (#2179); read with the schema facts.
        self._routine_synonym_cache: dict[str, tuple[str, str]] | None = None
        # RAW targets (#1496): whether any column or attribute is a recorded
        # RAW, and each object type's RAW attribute positions, by name; any DDL
        # starts them over. A relation's own columns are the schema model's.
        self._has_raw_targets_cache: bool | None = None
        # Whether any OSON column exists (#1706).
        self._has_oson_cache: bool | None = None
        self._raw_constructor_cache: dict[str, frozenset[int]] | None = None
        # Whether any column is INVISIBLE (#1195).
        self._any_invisible: bool | None = None
        # Each table name a statement names, as its relation's oid -- None for
        # no relation -- for the schema model (#1889); any DDL starts it over.
        self._relids: dict[str, int | None] = {}
        # Whether the database has plpgsql_check (#2129), once asked.
        self._plpgsql_check: bool | None = None
        # Which of the schema model's relations are views (#2202).
        self._view_relids: set[int] = set()
        # The ora_rowid domain's oids, read once a statement asks (#1624).
        self._rowid_type_oids: frozenset[int] | None = None
        if not installed:
            self._conn.execute("SET seerdb.installing = 'off'")
        self._conn.commit()
        if not self._has_ddl_log:
            # The DDL generation this session last saw, from its connect on;
            # None for good where the log could not be installed (#1887).
            self._ddl_generation = None
        self._connected = True

    def _install_part(self, part: str, *ddl: str) -> None:
        # One part of the setup's installation, best effort: one that fails is
        # rolled back and named, and the installation is not stamped (#1871).
        try:
            for statement in ddl:
                self._conn.execute(statement)
        except psycopg.Error:
            self._conn.rollback()
            self._install_failures.append(part)

    def _upgrade_data(self, version: int) -> None:
        # The steps that bring the records from `version` to this release's,
        # in order, each in a transaction of its own that records the version
        # it reached; idempotent, so a step a crash cut short runs again
        # (#1862). One that fails leaves the database where it was, and the
        # session is refused: it would misread the records.
        for target, ddl in sorted(_DATA_UPGRADES):
            if not version < target <= _DATA_VERSION:
                continue
            try:
                with self._conn.transaction():
                    self._conn.execute(ddl)
                    self._conn.execute(
                        f"COMMENT ON TABLE sys.ora_data_version IS '{target}'"
                    )
            except psycopg.Error as exc:
                self._conn.close()
                raise UnsupportedFeature(
                    f'upgrading the database to data version {target} failed: {exc}'
                ) from exc

    def _stamp_installation(self) -> bool:
        # Stamp the installation this setup ran, unless a part of it failed
        # that the database should have taken: whether it is stamped (#1871).
        # The extensions are read again, as the setup may have created them.
        row = self._conn.execute(
            "SELECT (SELECT string_agg(extname, ' ' ORDER BY extname) FROM pg_extension "
            "WHERE extname IN ('orafce', 'vector')), "
            "obj_description(to_regnamespace('sys'), 'pg_namespace')"
        ).fetchone()
        if row is None or row[1] != _DICTIONARY_STAMP:
            return False
        extensions = set((row[0] or '').split())
        for part in self._install_failures:
            if part in _PRIVILEGED_PARTS:
                continue
            if part in _EXTENSION_PARTS and _EXTENSION_PARTS[part] not in extensions:
                continue
            return False
        try:
            stamp = _installation_stamp(row[0])
            self._conn.execute(f"COMMENT ON SCHEMA system IS '{stamp}'")
            # The records' data version (#1862): a fresh database's, or one
            # adopted or upgraded, is this release's.
            self._conn.execute(
                'CREATE TABLE IF NOT EXISTS sys.ora_data_version (); '
                f"COMMENT ON TABLE sys.ora_data_version IS '{_DATA_VERSION}'"
            )
            self._conn.commit()
        except psycopg.Error:
            self._conn.rollback()
            return False
        return True

    def _look_up_vector(
        self,
    ) -> tuple[int, int, int, CompositeInfo, CompositeInfo] | None:
        # pgvector's `vector` and the Mirror's two vector composites (#1708),
        # where the database has them.
        row = self._conn.execute(
            "SELECT to_regtype('vector')::oid, to_regtype(%s)::oid, to_regtype(%s)::oid",
            (_VECTOR_COMPOSITE, _SPARSE_COMPOSITE),
        ).fetchone()
        if row is None or None in row:
            return None
        composite = CompositeInfo.fetch(self._conn, _VECTOR_COMPOSITE)
        sparse = CompositeInfo.fetch(self._conn, _SPARSE_COMPOSITE)
        if composite is None or sparse is None:
            return None
        return (row[0], row[1], row[2], composite, sparse)

    def _look_up_installation(
        self, vector: tuple[int, int, int, CompositeInfo, CompositeInfo] | None
    ) -> _Installation:
        # What a session's setup looks up in the installed database (#1871),
        # the vector types already looked up.
        from psycopg.types import TypeInfo

        def fetched(fetch: Callable[[], Any]) -> Any:
            try:
                return fetch()
            except psycopg.Error:
                self._conn.rollback()
                return None

        tstz = fetched(lambda: CompositeInfo.fetch(self._conn, _TSTZ_TYPE))
        bfile = fetched(lambda: CompositeInfo.fetch(self._conn, _BFILE_TYPE))
        names = [_CLOB_TYPE, _BLOB_TYPE, _INTERVALYM_TYPE, _DATE_TYPE, _OSON_TYPE]
        rows = fetched(
            lambda: self._conn.execute(
                'SELECT typname, oid FROM pg_type WHERE typname = ANY(%s)', (names,)
            ).fetchall()
        )
        domain_oids = {name: oid for (name, oid) in rows or ()}
        clob = fetched(lambda: TypeInfo.fetch(self._conn, _CLOB_TYPE))
        blob = fetched(lambda: TypeInfo.fetch(self._conn, _BLOB_TYPE))
        date = fetched(lambda: TypeInfo.fetch(self._conn, _DATE_TYPE))
        catalogs = fetched(
            lambda: self._conn.execute(
                "SELECT to_regclass('sys.ora_quoted_names') IS NOT NULL, "
                "to_regclass('sys.ora_tstz_precision') IS NOT NULL, "
                "to_regclass('sys.ora_invisible_columns') IS NOT NULL, "
                "to_regclass('sys.ora_columns') IS NOT NULL, "
                "to_regclass('sys.ora_collection_elements') IS NOT NULL, "
                "to_regclass('sys.ora_plsql_types') IS NOT NULL, "
                "to_regprocedure('sys.ora_ddl_unchanged(text)') IS NOT NULL, "
                'EXISTS (SELECT 1 FROM pg_event_trigger '
                "WHERE evtname = 'ora_ddl_log')"
            ).fetchone()
        )
        self._conn.commit()
        return _Installation(
            vector=vector,
            tstz=tstz,
            bfile=bfile,
            domain_oids=domain_oids,
            clob=clob,
            blob=blob,
            date=date,
            catalogs=tuple(bool(flag) for flag in catalogs or (False,) * 8),
        )

    def _adopt_installation(self, found: _Installation) -> None:
        # The adapters and oids of what the setup looked up (#1871): the same
        # for every session of the installation, registered on this one's
        # connection.
        from psycopg.types.array import register_array
        from psycopg.types.datetime import DateLoader, TimestampLoader
        from psycopg.types.string import (
            ByteaBinaryLoader,
            ByteaLoader,
            TextBinaryLoader,
            TextLoader,
        )

        if found.tstz is not None:
            register_composite(found.tstz, self._conn)
            self._tstz_oid = found.tstz.oid
            self._tstz_info = found.tstz
        if found.bfile is not None:
            register_composite(found.bfile, self._conn)
            self._bfile_oid = found.bfile.oid
        for name, tns_type in (
            (_CLOB_TYPE, TNS_TYPE_CLOB),
            (_BLOB_TYPE, TNS_TYPE_BLOB),
            (_INTERVALYM_TYPE, TNS_TYPE_INTERVALYM),
            (_DATE_TYPE, TNS_TYPE_DATE),
            # Traced as JSON, which the describe hands out as an OSON BLOB.
            (_OSON_TYPE, TNS_TYPE_JSON),
        ):
            oid = found.domain_oids.get(name)
            if oid is not None:
                self._domain_type_by_oid[oid] = tns_type
                if name == _INTERVALYM_TYPE:
                    self._intervalym_oid = oid
                elif name == _OSON_TYPE:
                    self._oson_oid = oid
        # A LOB inside a composite or an array is typed by its domain, which
        # psycopg does not know: a BLOB attribute came back as its hex text.
        # Load both domains, and arrays of them, as their base types (#1256).
        for domain, loaders in (
            (found.clob, (TextLoader, TextBinaryLoader)),
            (found.blob, (ByteaLoader, ByteaBinaryLoader)),
        ):
            if domain is not None:
                for loader in loaders:
                    self._conn.adapters.register_loader(domain.oid, loader)
                register_array(domain, self._conn)
        # Preserve an interval's months through psycopg (its default loader
        # flattens them to a timedelta), so a YEAR TO MONTH value survives (#504).
        self._conn.adapters.register_loader('interval', _IntervalMonthsTextLoader)
        # A date before year 1 loads as a BcDate the Mirror can serve (#1063).
        self._conn.adapters.register_loader('date', _bc_date_loader(DateLoader))
        self._conn.adapters.register_loader(
            'timestamp', _bc_date_loader(TimestampLoader)
        )
        # A DATE inside a composite or an array is typed by the ora_date
        # domain, which psycopg does not know: it came back as text. Load it,
        # and arrays of it, as the timestamp it is over (#1548).
        if found.date is not None:
            self._conn.adapters.register_loader(
                found.date.oid, _bc_date_loader(TimestampLoader)
            )
            register_array(found.date, self._conn)
        self._conn.adapters.register_loader('interval', _IntervalMonthsBinaryLoader)

    def _install_ddl_log(self, *, install: bool) -> None:
        # The DDL log and its event trigger (#1887) and the guard of a
        # statement rewritten from the schema (#1889), where the installation
        # is not current; then the log cut back when it has grown, and the
        # generation this session starts from.
        if install:
            for part, ddl in (('ddl log', _DDL_LOG_DDL), ('ddl guard', _DDL_GUARD_DDL)):
                try:
                    with self._conn.transaction():
                        self._conn.execute(ddl)
                except psycopg.Error:
                    self._conn.rollback()
                    self._install_failures.append(part)
        try:
            row = self._at_once(
                'SELECT count(*), max(id), ' + _DDL_GENERATION + ' FROM sys.ora_ddl_log'
            ).fetchone()
            if row is not None and row[0] > _DDL_LOG_KEPT:
                with self._conn.transaction():
                    self._conn.execute(
                        'DELETE FROM sys.ora_ddl_log WHERE id < %s', (row[1],)
                    )
                    row = self._conn.execute(
                        'SELECT 0, 0, ' + _DDL_GENERATION
                    ).fetchone()
            self._ddl_generation = None if row is None else row[2]
        except psycopg.Error:
            self._conn.rollback()

    def _forget_schema(self) -> None:
        # Drop what this session knows of the schema, for another session's DDL
        # (#1887): each of these is read again as it is next needed. Not the
        # index-organized tables, which only this session's own DDL records.
        self._object_types.clear()
        self._collection_types.clear()
        self._array_oids.clear()
        self._relations.clear()
        self._relids.clear()
        self._has_sql_domains_cache = None
        self._sql_domain_cache.clear()
        self._plsql_types.clear()
        self._collection_name_cache = None
        self._routine_synonym_cache = None
        self._package_function_cache = None
        self._forget_raw_targets()
        self._has_oson_cache = None
        self._any_invisible = None

    def _install_dictionary(self) -> None:
        row = self._conn.execute(
            "SELECT obj_description(to_regnamespace('sys'), 'pg_namespace')"
        ).fetchone()
        if row is not None and row[0] == _DICTIONARY_STAMP:
            return
        self._conn.execute("SET LOCAL lock_timeout = '2s'")
        try:
            with self._conn.transaction():
                self._conn.execute(_ORACLE_DICTIONARY_DDL)
        except psycopg.errors.InvalidTableDefinition:
            # A dictionary from another seerdb -- a newer one, rolled back from,
            # or a branch's -- has a view CREATE OR REPLACE VIEW cannot turn into
            # this one: a column this one does not define, or a column's type
            # changed. It failed every connection for good (#1571). The views go
            # and come back, in the same transaction, so a failure here leaves
            # the old ones as they were. A view of the user's own built on one of
            # them goes with it: CASCADE is the only way past the dependency.
            self._conn.execute(
                f'DROP VIEW IF EXISTS {", ".join(_DICTIONARY_VIEWS)} CASCADE'
            )
            self._conn.execute(_ORACLE_DICTIONARY_DDL)
        self._conn.execute(f"COMMENT ON SCHEMA sys IS '{_DICTIONARY_STAMP}'")

    def profile_counters(self) -> tuple[int, float, str | None]:
        # What a migration profile reads around each call (#1881): the
        # statements sent PostgreSQL so far, the seconds spent waiting on it,
        # and the PostgreSQL text of the statement last run since the last
        # read. Read before a call too, so a call that translates nothing
        # reports nothing rather than the call before's text (#1931).
        conn = cast(_CountedConnection, self._conn)
        (translated, self._last_translated) = (self._last_translated, None)
        return (conn.statements, conn.wait_seconds, translated)

    def _at_once(
        self, statement: str | sql.SQL | sql.Composed, params: Sequence | None = None
    ) -> psycopg.Cursor:
        # Run `statement` committed at once, as a login's settings are: a
        # setting made in a transaction that rolls back is undone with it, and
        # Oracle's is not. With no transaction open it runs in autocommit, one
        # round trip with no BEGIN or COMMIT around it (#1914); inside one, it
        # commits that transaction, as before. Several statements, joined by
        # `;` and given no parameters, are one round trip together.
        if self._conn.info.transaction_status != psycopg.pq.TransactionStatus.IDLE:
            cursor = self._conn.execute(statement, params)
            self._conn.commit()
            return cursor
        self._conn.autocommit = True
        try:
            return self._conn.execute(statement, params)
        finally:
            self._conn.autocommit = False

    def _catalog_read(
        self, statement: str | sql.SQL | sql.Composed, params: Sequence | None = None
    ) -> psycopg.Cursor:
        # A read of the catalogs or the Mirror's own records, as a statement is
        # translated or described. With no transaction open it opens none: it
        # runs in autocommit (#1915), where psycopg's BEGIN was a round trip of
        # its own, and the statement after it then opens its transaction in its
        # own round trip. Each read sees the database as it is, as it did.
        # A prelude waiting for the next statement -- a PL/SQL call's
        # savepoint -- waits past it: in autocommit, the savepoint met no
        # transaction, and a SELECT INTO as a session's first statement failed
        # and took the session with it (#2103).
        if self._conn.info.transaction_status != psycopg.pq.TransactionStatus.IDLE:
            return self._conn.execute(statement, params)
        (waiting, self._conn.prelude) = (self._conn.prelude, ())
        self._conn.autocommit = True
        try:
            return self._conn.execute(statement, params)
        finally:
            self._conn.autocommit = False
            self._conn.prelude = waiting + self._conn.prelude

    def set_client_identity(self, identity: dict[str, str]) -> None:
        # program / machine / terminal / osuser, as the client declared them in
        # its first login message; recorded for v$session (#1212).
        self._client_identity = dict(identity)

    def open_session(self, connect_attrs: dict[str, str]) -> None:
        # The driver name arrives only in the second login message (#1212).
        self._client_driver = connect_attrs.get('driver_name')
        target = connect_attrs.get('proxy_client_name')
        login = getattr(self, '_login_user', None)
        self._open_as(target)
        if self._per_user and login is not None and not (self._became and not target):
            # From here on, the session is its user's own role (#1857) --
            # which it already is when it connected as that role at login,
            # but under a proxy login, whose target only now is known (#1939).
            self._become(self._login_user, login if target else '')
        edition = connect_attrs.get('edition')
        if edition:
            # The edition the client connected in (#1662); one that does not
            # exist refuses the login, ORA-38802, as Oracle's does.
            with self._rolled_back_on_error():
                self._conn.execute('SELECT sys.ora_set_edition(%s)', (edition.upper(),))
                self._conn.commit()
        # The service the client connected to, for USERENV SERVICE_NAME (#1409),
        # kept in a session setting as the tracing attributes are.
        service = connect_attrs.get('service_name')
        if service:
            try:
                self._at_once(
                    "SELECT set_config('seerdb.service_name', %s, false)", (service,)
                )
            except psycopg.Error:
                self._conn.rollback()

    def _open_as(self, target: str | None) -> None:
        # The session's user (#1620): the login's, or under a proxy login
        # (`user[target]`) the target's, whose schema it then starts in, with
        # the user who logged in as its PROXY_USER. Oracle admits only a target
        # granted CONNECT THROUGH the user; the Mirror keeps no such grant and
        # admits any. Committed at once, as the search_path at login is.
        login = getattr(self, '_login_user', None)
        if login is None:
            return
        user = target.upper() if target else login
        if target and not self._may_proxy(login, user):
            # Oracle admits a target only where the login was granted CONNECT
            # THROUGH it (#1860), and refuses any other as a logon denied.
            raise BackendError(
                'invalid username/password; logon denied',
                ora_code=ORA_INVALID_USERNAME_PASSWORD,
            )
        statement = sql.SQL(
            "SELECT set_config('seerdb.session_user', {}, false), "
            "set_config('seerdb.proxy_user', {}, false)"
        ).format(sql.Literal(user), sql.Literal(login if target else ''))
        if target:
            statement = sql.SQL('; ').join(
                [
                    statement,
                    sql.SQL('SET search_path TO {}, ' + _SEARCH_PATH_TAIL).format(
                        sql.Identifier(target.lower())
                    ),
                ]
            )
        try:
            self._at_once(statement)
            if target:
                self._login_user = user
        except psycopg.Error:
            self._conn.rollback()

    def _may_proxy(self, proxy: str, client: str) -> bool:
        # Whether `proxy` was granted CONNECT THROUGH to `client` (#1860). A
        # dictionary that keeps no grants admits none.
        if not self._has_proxy_grants():
            return False
        query = (
            'SELECT EXISTS (SELECT 1 FROM sys.ora_proxy_grants '
            'WHERE proxy = %s AND client = %s)'
        )
        if self._became:
            # A DBA's record, which the login user's role does not read: the
            # installer's connection does (#1939).
            with self._administering() as admin:
                row = admin.execute(query, (proxy, client)).fetchone()
        else:
            row = self._catalog_read(query, (proxy, client)).fetchone()
        return bool(row and row[0])

    def _record_session(self) -> None:
        # This session's row in sys.ora_sessions, and none for backends that have
        # ended. Best effort: a login must not fail over its v$session row.
        identity = getattr(self, '_client_identity', {})
        program = identity.get('program')
        statements: list[sql.Composable] = []
        if program:
            statements.append(
                sql.SQL("SELECT set_config('application_name', {}, false)").format(
                    sql.Literal(program[:63])
                )
            )
        statements += [
            sql.SQL(
                'DELETE FROM sys.ora_sessions WHERE pid NOT IN '
                '(SELECT pid FROM pg_stat_activity)'
            ),
            sql.SQL(
                'INSERT INTO sys.ora_sessions VALUES (pg_backend_pid(), {}) '
                'ON CONFLICT (pid) DO UPDATE SET username = excluded.username, '
                'program = excluded.program, machine = excluded.machine, '
                'terminal = excluded.terminal, osuser = excluded.osuser, '
                'driver = excluded.driver'
            ).format(
                sql.SQL(', ').join(
                    sql.Literal(value)
                    for value in (
                        getattr(self, '_login_user', None),
                        program,
                        identity.get('machine'),
                        identity.get('terminal'),
                        identity.get('osuser'),
                        getattr(self, '_client_driver', None),
                    )
                )
            ),
        ]
        try:
            # One round trip (#1914): the statements, run as one.
            self._at_once(sql.SQL('; ').join(statements))
        except psycopg.Error:
            self._conn.rollback()

    def session_info(self) -> SessionInfo:
        """The session's identity, for the Mirror's login reply (#1212).

        A client reads its session id and serial only from that reply, never by
        querying, so without this it reported a placeholder for the life of the
        connection. The SID is the backend's pid, as sys_context('userenv',
        'sid') reports it, so SQL and the reply agree; the names are the ones
        sys_context gives.
        """
        # The last login hook to run, so the session is recorded for v$session
        # here, with everything the client declared by now.
        self._record_session()
        row = self._at_once(
            'SELECT pg_backend_pid(), sys.ora_serial(pg_backend_pid()), '
            'upper(current_database())'
        ).fetchone()
        if row is None:
            return SessionInfo()
        (pid, serial, name) = row
        return SessionInfo(
            session_id=pid, serial_num=serial or 0, instance_name=name, db_name=name
        )

    def authenticate(self, username: str) -> str | None:
        # The login store the Mirror authenticates clients against — separate
        # from the libpq `conninfo` the backend itself connects to PostgreSQL
        # with. A production backend might instead consult a PG table here.
        if not self._connected:
            return self._authenticate_as_role(username)
        secret = self._accounts.secret(username)
        self._login_user = username.upper()
        if secret is not None:
            # Every Oracle user has a schema, the launcher's account too (#1751):
            # without one its objects went to `public` and the dictionary named
            # their owner PUBLIC. A CREATE USER account has one already; another
            # session may be creating this one at the same moment.
            schema = sql.Identifier(username.lower())
            try:
                self._at_once(sql.SQL('CREATE SCHEMA IF NOT EXISTS {}').format(schema))
            except psycopg.Error:
                self._conn.rollback()
            # An Oracle session's current schema starts as the login user's, so
            # an unqualified name resolves there first (#1188) -- the path ALTER
            # SESSION SET CURRENT_SCHEMA builds. PostgreSQL skips a schema that
            # does not exist, so a user without one resolves as before. Committed
            # at once: a SET inside a transaction that rolls back is undone. The
            # session's user from the login on (#1621: what it may see), as a
            # proxy login then changes it (#1620). One round trip (#1914).
            self._at_once(
                sql.SQL('; ').join(
                    [
                        sql.SQL('SET search_path TO {}, ' + _SEARCH_PATH_TAIL).format(
                            schema
                        ),
                        sql.SQL(_ORAFCE_SESSION_SETTINGS),
                        sql.SQL(
                            "SELECT set_config('seerdb.session_user', {}, false)"
                        ).format(sql.Literal(username.upper())),
                    ]
                )
            )
        return secret

    def _authenticate_as_role(self, username: str) -> str | None:
        # A per-user login whose session has no connection yet (#1939): the
        # account's secret and its role's password in one read, and the
        # session connected straight as the role, set up as a login sets it
        # up, in the same round trips. Where the role has no password yet, or
        # its connection or its checks fail, the session connects as the
        # installer and the login goes on as it does in per-user mode
        # otherwise: open_session makes the session the role's (_become).
        (secret, role_password) = self._accounts.secrets(username)
        self._login_user = username.upper()
        if secret is None:
            return None
        if role_password is not None:
            conninfo = make_conninfo(
                self._admin_conninfo, user=username.lower(), password=role_password
            )
            try:
                self._connect(conninfo, role=username)
            except (psycopg.Error, _RoleUnverified):
                # A connection made before the setup failed is not the
                # session's.
                if getattr(self, '_conn', None) is not None:
                    self._conn.close()
            else:
                self._became = True
                self._conninfo = conninfo
                self._at_once(
                    sql.SQL('; ').join(
                        [
                            sql.SQL(
                                'SET search_path TO {}, ' + _SEARCH_PATH_TAIL
                            ).format(sql.Identifier(username.lower())),
                            sql.SQL(_ORAFCE_SESSION_SETTINGS),
                            sql.SQL(
                                "SELECT set_config('seerdb.session_user', {}, false), "
                                "set_config('seerdb.proxy_user', '', false)"
                            ).format(sql.Literal(username.upper())),
                        ]
                    )
                )
                return secret
        self._connect(self._admin_conninfo)
        return self.authenticate(username)

    @property
    def closed(self) -> bool:
        # The PostgreSQL connection is gone: ALTER SYSTEM KILL SESSION ended it, or
        # the server did (#1367). Every call then answers ORA-00028. psycopg only
        # learns of it when it next uses the connection, and a statement answered
        # without the backend never does. An idle connection has nothing to read,
        # though, until the server terminates it -- it sends a FATAL, then closes
        # -- so while the socket is readable its input is fed to libpq: the first
        # read takes the FATAL, the next meets the end of the stream, and libpq
        # marks the connection bad. No round trip.
        if not self._connected:
            return False
        try:
            for _read in range(4):
                if self._conn.closed:
                    return True
                readable, _w, _x = select.select([self._conn.fileno()], [], [], 0)
                if not readable:
                    break
                self._conn.pgconn.consume_input()
        except (OSError, ValueError, psycopg.Error):
            return True
        return bool(self._conn.closed)

    def ping(self) -> None:
        # A health check -- conn.ping(), or a pool checking a connection before
        # handing it out. A killed session answers ORA-00028 (#1367), so the pool
        # drops it; a live one needs no round trip, `closed` having looked.
        if self.closed:
            raise _session_terminated()

    @_while_connected
    @_plainly_quoted
    def open_ref_cursor(self, query: str, skip: int = 0) -> object:
        """A cursor of the client's, bound IN as a REF CURSOR (#1609): its query
        opened as a portal of this session, past the ``skip`` rows the client
        has had already, and named as a SYS_REFCURSOR parameter takes it -- so
        a routine's FETCH goes on where the client stopped, as in Oracle. The
        portal lives as long as the transaction, or until the routine closes it.
        """
        translated = _translate_idioms(
            _translate_plsql_block(
                _translate_routine_ddl(
                    _translate_ddl(_translate_admin(_quote_reserved_names(query)))
                )
            )
        )
        self._portals_opened += 1
        name = f'ora_cursor_{self._portals_opened}'
        with self._rolled_back_on_error(original=query):
            self._conn.execute(
                sql.SQL('DECLARE {} CURSOR FOR ')
                .format(sql.Identifier(name))
                .as_string(self._conn)
                + translated
            )
            if skip:
                self._conn.execute(
                    sql.SQL('MOVE FORWARD {} IN {}').format(
                        sql.Literal(skip), sql.Identifier(name)
                    )
                )
        return _PortalName(name)

    @_plainly_quoted
    def parse(self, sql: str) -> None:
        """Validate a statement without running it -- ``cursor.parse()`` of
        anything that is not a query.

        Without this the Mirror answered its own bare success and every
        parse-time error was lost. Oracle refuses a bind named by a reserved
        word (ORA-01745), a rule PostgreSQL does not have, so it is checked
        here; the rest is PostgreSQL's EXPLAIN of the translated statement,
        which plans without running, inside a savepoint so a refusal leaves the
        session as it was. DDL, PL/SQL and transaction control have no EXPLAIN
        and keep the bare success they had.
        """
        native = self._is_native(sql)
        stripped = _strip_leading_comments(sql)
        with _offset_from_start(len(sql) - len(stripped)):
            self._parse_stripped(stripped, native)

    def _parse_stripped(self, sql: str, native: bool) -> None:
        # The statement past its leading whitespace and comments.
        sql = _ruled('editionable', _without_editionable(sql), sql)
        _refuse_reserved_bind_names(sql)
        if is_plsql(sql) or _NOT_EXPLAINABLE.match(sql):
            return
        translated = (
            sql
            if native
            else _translate_idioms(
                _translate_plsql_block(
                    _translate_routine_ddl(
                        _translate_ddl(
                            _translate_admin(
                                _quote_reserved_names(strip_returning_into(sql))
                            )
                        )
                    )
                )
            )
        )
        placeholders = placeholder_count(sql)
        params: dict | None = None
        if placeholders:
            translated, params = _translate_binds(translated, [None] * placeholders)
        try:
            with self._under_savepoint('_mirror_parse'):
                self._conn.execute(_EXPLAIN_PREFIX + translated, params)
        except psycopg.Error as exc:
            # A bind whose type only its value would settle is not an error in
            # Oracle, whose parse has no value either.
            if getattr(exc, 'sqlstate', None) == '42P18':
                return
            # PostgreSQL counts the position into the EXPLAIN it ran, the
            # prefix included: mapped against that text, then moved back past
            # it (#2074).
            err = _backend_error(
                exc,
                original=_EXPLAIN_PREFIX + sql,
                translated=_EXPLAIN_PREFIX + translated,
            )
            if err.error_offset is not None:
                err.error_offset = max(err.error_offset - len(_EXPLAIN_PREFIX), 0)
            raise err from exc
        self._release_read_locks()

    @contextmanager
    def _under_savepoint(
        self, name: str = '_mirror_stmt', then: str | None = None
    ) -> Iterator[None]:
        # The block runs under a savepoint: one that raises is rolled back to it,
        # leaving the rest of the transaction usable as Oracle's is, and the
        # savepoint goes either way. The caller maps the error, AFTER the
        # rollback here: naming it can read the catalog, which a failed
        # transaction refuses (#1632). With no transaction open, and no
        # prelude to go first, the transaction opens with the savepoint, one
        # round trip, not psycopg's synced BEGIN and then the savepoint (#1915).
        # `then`, a statement with no parameters, goes in that round trip too.
        opening = f'SAVEPOINT {name}' + (f'; {then}' if then is not None else '')
        idle = psycopg.pq.TransactionStatus.IDLE
        if self._conn.info.transaction_status == idle and not self._conn.prelude:
            self._conn.autocommit = True
            psycopg.Cursor.execute(
                self._conn.cursor(), f'BEGIN; {opening}', prepare=False
            )
        else:
            self._conn.execute(opening)
        try:
            yield
        except Exception:
            self._conn.execute(f'ROLLBACK TO SAVEPOINT {name}')
            self._conn.execute(f'RELEASE SAVEPOINT {name}')
            raise
        self._conn.execute(f'RELEASE SAVEPOINT {name}')

    @contextmanager
    def _rolled_back_on_error(self, **context: Any) -> Iterator[None]:
        # A PostgreSQL failure in the block rolls the transaction back and is
        # raised as the ORA error it maps to, `context` passed to the mapping.
        try:
            yield
        except psycopg.Error as exc:
            self._conn.rollback()
            raise _backend_error(exc, **context) from exc

    def _release_read_locks(self) -> None:
        """End the open transaction if it has written nothing (#1190).

        An Oracle query takes no table lock. A PostgreSQL read takes
        AccessShareLock and keeps it until its transaction ends, and a client
        has no reason to commit after a plain query, so the lock outlived the
        query for as long as the session did: another session's TRUNCATE, DROP
        or ALTER then waited on it for ever. A transaction with no transaction
        id has written nothing, not even a row lock (SELECT ... FOR UPDATE
        assigns one), so committing it only lets the read locks go. One the
        client took a SAVEPOINT in is kept, as the commit would destroy it.
        """
        if self._user_savepoint:
            return
        if self._conn.info.transaction_status != psycopg.pq.TransactionStatus.INTRANS:
            return
        # The pipeline that ran the statement read the answer already (#1869);
        # it still holds if no statement has run since, as a REF CURSOR fetch
        # could run a function that writes.
        known = self._conn.unwritten_at
        if known is not None and known[1] == self._conn.statements:
            unwritten = known[0]
        else:
            row = self._conn.execute(_WRITTEN_CHECK).fetchone()
            unwritten = row is not None and bool(row[0])
        if unwritten:
            self._conn.commit()

    @_while_connected
    @_plainly_quoted
    def execute(self, sql: str, binds: Sequence = ()) -> Result:
        (sql, [binds]) = _occurrence_binds(sql, [binds])
        try:
            return self._committing(
                lambda: self._with_implicit_results(
                    lambda: self._reported(
                        sql,
                        lambda: self._replanned(
                            lambda: self._privilege_refined(
                                sql, lambda: self._execute_statement(sql, binds)
                            )
                        ),
                    )
                )
            )
        except BackendError as error:
            if (
                error.ora_code
                in (
                    ORA_VALUE_TOO_LARGE_FOR_COLUMN,
                    ORA_VALUE_LARGER_THAN_PRECISION,
                )
                and (late := _late_constants(sql)) is not None
            ):
                # A constant too long for its column, which PostgreSQL checks
                # as it plans, before it touches a row; Oracle checks each row
                # it changes, and with none it succeeds (#2138). Once more with
                # the constants checked per row: with a row it fails as before.
                try:
                    return self.execute(late, binds)
                except BackendError:
                    pass
            if (converted := self._converted_select(sql, error)) is not None:
                # An INSERT ... SELECT's literal its column's type refuses as
                # PostgreSQL types it, which Oracle converts (#2150). Once more
                # with it converted as Oracle does: TO_NUMBER, TO_DATE.
                return self.execute(converted, binds)
            if (
                isinstance(error, _InvalidNumber)
                and (late := _late_number(sql, binds, error.value)) is not None
            ):
                # A value that is no number, which PostgreSQL converts as it
                # plans; Oracle converts it for each row it compares or
                # changes, and with none it succeeds (#2143). Once more with
                # the value converted per row: with a row it fails as before.
                try:
                    return self.execute(late, binds)
                except BackendError:
                    pass
            if error.ora_code == ORA_VALUE_TOO_LARGE_FOR_COLUMN:
                worded = self._too_large_worded(sql, binds, error)
                if worded is not None:
                    worded.rowcount = error.rowcount
                    worded.row_counts = list(error.row_counts)
                    raise worded from error
            # An error PostgreSQL gave no position for, placed as 23ai places
            # it (#2111). A single statement's only: an array's error offset
            # is the row that failed, and a block's errors are its own.
            if error.error_offset is None and not is_plsql(sql):
                error.error_offset = (
                    self._null_offset(sql, error.column)
                    if isinstance(error, _NullViolation)
                    else _placed_offset(error.ora_code, sql)
                )
            raise

    def _number_worded(self, invalid: _InvalidNumber) -> BackendError:
        # ORA-01722 as 23ai says it (#2136): the first character that cannot
        # be in a number, then the value on an ORA-03302 line -- `'12z'` names
        # 'z', `'1,5'` names ','. Before 23ai, `invalid number`.
        if self._release < (23, 0):
            return invalid
        value = invalid.value
        bad = next((c for c in value if c not in _NUMBER_CHARACTERS), ' ')
        return BackendError(
            f"unable to convert string value containing '{bad}' to a number: \n"
            + f'ORA-03302: (ORA-01722 details) invalid string value: {value}'.rstrip(),
            ora_code=ORA_INVALID_NUMBER,
            error_offset=invalid.error_offset,
        )

    def _unique_worded(self, violation: _UniqueViolation) -> BackendError:
        # ORA-00001 as 23ai says it (#2120): the table and columns, then the
        # row's values on an ORA-03301 line, a character value quoted as
        # Oracle quotes it, its own quotes as they are. Before 23ai, and when
        # the key's columns cannot be read, the older text stands.
        if self._release < (23, 0) or not violation.columns:
            return violation
        columns = ', '.join(c.upper() for c in violation.columns)
        text = (
            f'unique constraint ({violation.schema}.{violation.constraint}) '
            f'violated on table {violation.schema}.{violation.table} '
            f'columns ({columns})'
        )
        if violation.values:
            textual: set[str] = set()
            values = dict(zip(violation.columns, violation.values))
            if (
                self._conn.info.transaction_status
                != psycopg.pq.TransactionStatus.INERROR
            ):
                try:
                    for name, category, type_name, typmod in self._catalog_read(
                        'SELECT a.attname, t.typcategory, t.typname, a.atttypmod '
                        'FROM pg_attribute a '
                        'JOIN pg_type t ON t.oid = a.atttypid '
                        'JOIN pg_class c ON c.oid = a.attrelid '
                        'JOIN pg_namespace n ON n.oid = c.relnamespace '
                        'WHERE lower(n.nspname) = lower(%s) '
                        'AND lower(c.relname) = lower(%s) AND a.attname = ANY(%s)',
                        (violation.schema, violation.table, violation.columns),
                    ).fetchall():
                        if category == 'S':
                            textual.add(name)
                        elif type_name == _DATE_TYPE:
                            # A DATE in the session's NLS_DATE_FORMAT, as
                            # TO_CHAR(d) gives it (#2141).
                            row = self._catalog_read(
                                'SELECT to_char(%s::timestamp)', (values[name],)
                            ).fetchone()
                            if row is not None:
                                values[name] = row[0]
                        elif type_name == 'timestamp':
                            # A TIMESTAMP in the session's NLS_TIMESTAMP_FORMAT,
                            # FF at the column's precision (#2162).
                            row = self._catalog_read(
                                'SELECT sys.ora_datetime_text(%s::timestamp, %s)',
                                (values[name], 6 if typmod < 0 else typmod),
                            ).fetchone()
                            if row is not None:
                                values[name] = row[0]
                except psycopg.Error:
                    textual = set()
                    values = dict(zip(violation.columns, violation.values))
            shown = ', '.join(
                f"{c.upper()}:'{values[c]}'"
                if c in textual
                else f'{c.upper()}:{values[c]}'
                for c in violation.columns
            )
            text += (
                f'\nORA-03301: (ORA-00001 details) row with column values ({shown}) '
                'already exists'
            )
        return BackendError(
            text,
            ora_code=ORA_UNIQUE_CONSTRAINT_VIOLATED,
            error_offset=violation.error_offset,
        )

    def _null_offset(self, sql: str, column: str) -> int | None:
        # Where 23ai points a NOT NULL violation (#2134): an UPDATE at the
        # column in its SET, an INSERT at the VALUES item -- or the query's
        # select item -- that fills the column, by the column list or else the
        # table's column order, and at 0 when the list leaves the column out.
        update = _NULL_UPDATE.match(sql)
        if update is not None:
            end = len(sql)
            for item_start, item_end in _top_level_items(sql, update.end(), end):
                item = sql[item_start:item_end]
                target = re.match(r'\s*"?([\w$#]+)"?\s*=', item)
                if target is not None and target.group(1).lower() == column.lower():
                    return item_start + item.index(target.group(1))
                if re.search(r'(?i)\bWHERE\b', item):
                    break
            return None
        insert = _NULL_INSERT.match(sql)
        if insert is None:
            return None
        if insert.group(2) is not None:
            names = [n.strip().strip('"').lower() for n in insert.group(2).split(',')]
        else:
            names = self._column_order(insert.group(1))
        if column.lower() not in names:
            return 0 if insert.group(2) is not None else None
        index = names.index(column.lower())
        if insert.group(3).upper() == 'VALUES':
            open_at = insert.end() - 1
            close = _matching_paren(sql, open_at)
            items = _top_level_items(sql, open_at + 1, close)
        else:
            start = insert.end()
            words, _rownums = _top_level_words(sql[start:])
            end = next((start + p for p, w in words if w == 'FROM'), len(sql))
            items = _top_level_items(sql, start, end)
        if index >= len(items):
            return None
        (item_start, item_end) = items[index]
        return item_start + (
            len(sql[item_start:item_end]) - len(sql[item_start:item_end].lstrip())
        )

    def _too_large_worded(
        self, sql: str, binds: Sequence, error: BackendError
    ) -> BackendError | None:
        # ORA-12899 as Oracle says it, in every release (#2137): `value too
        # large for column "PYO"."T"."N" (actual: 4, maximum: 3)`, the actual
        # in bytes, at the value. PostgreSQL names only the length, so the
        # value is found: the first literal or bind the statement assigns that
        # is longer than its column, among the columns that long. None when
        # none is, and the error stays as it was.
        too_long = _VALUE_TOO_LONG.search(str(error))
        assigned = _assigned_values(sql)
        if too_long is None or assigned is None:
            return None
        if self._conn.info.transaction_status == psycopg.pq.TransactionStatus.INERROR:
            return None
        (table, items) = assigned
        maximum = int(too_long.group(1))
        try:
            rows = self._catalog_read(
                'SELECT n.nspname, c.relname, a.attname, a.atttypmod - 4 '
                'FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid '
                'JOIN pg_namespace n ON n.oid = c.relnamespace '
                'WHERE a.attrelid = to_regclass(%s) AND a.attnum > 0 '
                'AND NOT a.attisdropped ORDER BY a.attnum',
                (table.lower(),),
            ).fetchall()
        except psycopg.Error:
            return None
        if not rows:
            return None
        (schema, relation) = (rows[0][0], rows[0][1])
        order = [name.lower() for (_s, _r, name, _l) in rows]
        lengths = {name.lower(): length for (_s, _r, name, length) in rows}
        names = _bind_names(sql)
        for index, (named, start, end) in enumerate(items):
            column = (named or (order[index] if index < len(order) else '')).lower()
            if lengths.get(column) != maximum:
                continue
            text = sql[start:end].strip()
            value: object = None
            if text.startswith("'") and text.endswith("'"):
                value = text[1:-1].replace("''", "'")
            elif text.startswith(':') and text[1:] in names:
                at = names.index(text[1:])
                value = binds[at] if at < len(binds) else None
            if not isinstance(value, str) or len(value) <= maximum:
                continue
            lead = len(sql[start:end]) - len(sql[start:end].lstrip())
            if text.startswith(':'):
                lead += 1  # a bind's place is its name's, past the colon
            return BackendError(
                f'value too large for column "{schema.upper()}"."{relation.upper()}".'
                f'"{column.upper()}" (actual: {len(value.encode("utf-8"))}, '
                f'maximum: {maximum})',
                ora_code=ORA_VALUE_TOO_LARGE_FOR_COLUMN,
                error_offset=start + lead,
            )
        return None

    def _converted_select(self, sql: str, error: BackendError) -> str | None:
        # `sql` with the INSERT ... SELECT literal in the column PostgreSQL
        # refused it for passed through TO_NUMBER or TO_DATE (#2150), or None
        # when the error is not that one or the literal cannot be found.
        refused = _REFUSED_ASSIGNMENT.search(str(error))
        assigned = _assigned_values(sql) if refused is not None else None
        if refused is None or assigned is None:
            return None
        insert = _NULL_INSERT.match(sql)
        if insert is None or not insert.group(3).upper().startswith('SELECT'):
            return None
        (table, items) = assigned
        (column, target) = (refused.group(1).lower(), refused.group(2))
        call = 'TO_DATE' if target in _DATE_TARGETS else 'TO_NUMBER'
        order = self._column_order(table) if items and items[0][0] is None else []
        for index, (named, start, end) in enumerate(items):
            name = (named or (order[index] if index < len(order) else '')).lower()
            if name != column:
                continue
            value = sql[start:end]
            if not re.fullmatch(r"\s*'(?:[^']|'')*'\s*", value):
                return None
            lead = len(value) - len(value.lstrip())
            return (
                sql[: start + lead]
                + f'{call}({value.strip()})'
                + sql[start + lead + len(value.strip()) :]
            )
        return None

    def _operand_types(self, sql: str) -> dict[str, tuple[str, int]]:
        # The Oracle type and length of each column of a query's FROM tables,
        # keyed by its name and by its table's name or alias and its name,
        # lower-cased; empty when it cannot be read (#2147, #2152).
        tables = _from_tables(sql)
        if not tables or (
            self._conn.info.transaction_status == psycopg.pq.TransactionStatus.INERROR
        ):
            return {}
        types: dict[str, tuple[str, int]] = {}
        for schema, table, alias in tables:
            try:
                rows = self._catalog_read(
                    'SELECT column_name, data_type, data_length FROM all_tab_columns '
                    "WHERE owner = coalesce(upper(%s), sys_context('USERENV', "
                    "'CURRENT_SCHEMA')) AND table_name = upper(%s)",
                    (schema, table),
                ).fetchall()
            except psycopg.Error:
                return {}
            for column, data_type, data_length in rows:
                name = column.lower()
                typed = (data_type, data_length or 0)
                types.setdefault(name, typed)
                types[f'{table}.{name}'] = typed
                if alias:
                    types[f'{alias}.{name}'] = typed
        return types

    def _operand_widths(self, sql: str) -> dict[str, int]:
        # The width each column of a query's FROM tables adds to a
        # concatenation (#2147), keyed as _operand_types keys it.
        widths = {}
        for key, (data_type, data_length) in self._operand_types(sql).items():
            width = _column_text_width(data_type, data_length)
            if width is not None:
                widths[key] = width
        return widths

    def _column_order(self, table: str) -> list[str]:
        # A table's columns in their order, lower-cased, for placing an
        # INSERT's error without a column list (#2134); none when unknown.
        if self._conn.info.transaction_status == psycopg.pq.TransactionStatus.INERROR:
            return []
        try:
            rows = self._catalog_read(
                'SELECT a.attname FROM pg_attribute a WHERE a.attrelid = '
                'to_regclass(%s) AND a.attnum > 0 AND NOT a.attisdropped '
                'ORDER BY a.attnum',
                (table.lower(),),
            ).fetchall()
        except psycopg.Error:
            return []
        return [name.lower() for (name,) in rows]

    def _missing_named(self, missing: _ObjectMissing) -> BackendError:
        # ORA-00942 as the release presented says it (#2110): 23ai names the
        # table or view, schema and all, where the statement may name neither
        # (`table or view "PYO"."T" does not exist`); earlier ones do not. An
        # unquoted name is upper-cased, as Oracle folds one; the schema the
        # statement did not give is the session's current one. A view a DROP
        # left INVALID is ORA-04063, `view "PYO.V" has errors` (#2201), and a
        # synonym whose target is not there ORA-00980 (#2179). One read says
        # all three.
        if self._conn.info.transaction_status == psycopg.pq.TransactionStatus.INERROR:
            return missing
        relation = missing.relation
        try:
            row = self._catalog_read(
                'SELECT current_schema(), EXISTS (SELECT 1 FROM sys.ora_synonyms '
                'WHERE (owner = upper(coalesce(%s, current_schema())) '
                "OR %s::text IS NULL AND owner = 'PUBLIC') "
                'AND name = %s), EXISTS (SELECT 1 FROM sys.ora_invalid_views '
                'WHERE schema_name = coalesce(%s, current_schema()) '
                'AND view_name = %s)',
                (
                    missing.schema,
                    missing.schema,
                    relation.upper() if relation == relation.lower() else relation,
                    missing.schema,
                    relation,
                ),
            ).fetchone()
        except psycopg.Error:
            return missing
        if row is None or row[0] is None:
            return missing
        (current, synonym, invalid) = row
        schema = missing.schema or current

        def oracle(name: str) -> str:
            return name.upper() if name == name.lower() else name

        if synonym:
            return BackendError(
                'synonym translation is no longer valid',
                ora_code=_ORA_SYNONYM_TRANSLATION,
                error_offset=missing.error_offset,
            )
        if invalid:
            return BackendError(
                f'view "{oracle(schema)}.{oracle(relation)}" has errors',
                ora_code=_ORA_VIEW_HAS_ERRORS,
                error_offset=missing.error_offset,
            )
        if self._release < (23, 0):
            return missing

        return BackendError(
            f'table or view "{oracle(schema)}"."{oracle(missing.relation)}" '
            'does not exist',
            ora_code=ORA_TABLE_OR_VIEW_DOES_NOT_EXIST,
            error_offset=missing.error_offset,
        )

    def _privilege_refined(self, statement: str, run: Callable[[], Result]) -> Result:
        # A privilege refused on another user's relation in per-user mode
        # (#1858), as Oracle tells it: ORA-00942 when the user holds no
        # privilege on it at all, else 23ai's ORA-41900 naming the privilege
        # the statement needed, or before 23ai ORA-01031.
        try:
            return run()
        except _PrivilegeDenied as error:
            if not self._per_user or (
                self._conn.info.transaction_status
                == psycopg.pq.TransactionStatus.INERROR
            ):
                raise
            refined = self._privilege_error(statement, error.relation)
            raise refined from error.__cause__

    def _privilege_error(self, statement: str, relation: str) -> BackendError:
        held = self._conn.execute(
            'SELECT sys.ora_owner(n.nspname), sys.ora_name(c.relname), '
            "c.relkind = 'S', CASE WHEN c.relkind = 'S' THEN "
            "has_sequence_privilege(c.oid, 'USAGE,SELECT,UPDATE') ELSE "
            f'{_reachable_relation("c.oid")} END, c.oid '
            'FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace '
            "WHERE c.relname = %s AND has_schema_privilege(n.oid, 'USAGE') "
            'ORDER BY 4 DESC LIMIT 1',
            (relation,),
        ).fetchone()
        if held is None or not held[3]:
            return BackendError(
                'table or view does not exist',
                ora_code=ORA_TABLE_OR_VIEW_DOES_NOT_EXIST,
            )
        verb = statement.split(None, 1)[0].upper() if statement.strip() else ''
        # Oracle names a query's privilege READ.
        needed = {
            'SELECT': 'READ',
            'INSERT': 'INSERT',
            'UPDATE': 'UPDATE',
            'DELETE': 'DELETE',
        }
        if self._release < (23, 0) or held[2] or verb not in needed:
            return BackendError(
                'insufficient privileges', ora_code=ORA_INSUFFICIENT_PRIVILEGES
            )
        missing = needed[verb]
        if verb in ('UPDATE', 'DELETE') and self._holds_verb(statement, verb, held[4]):
            # The statement's own privilege is there: what it lacks is
            # SELECT, to read the columns its WHERE names -- which 23ai
            # calls SELECT here, not READ (#1946).
            missing = 'SELECT'
        return BackendError(
            f'missing {missing} privilege on "{held[0]}"."{held[1]}"',
            ora_code=_ORA_MISSING_PRIVILEGE,
        )

    def _holds_verb(self, statement: str, verb: str, relid: int) -> bool:
        # Whether the role holds the privilege an UPDATE or DELETE needs on
        # the relation: on the whole of it, or for an UPDATE on each column
        # its SET names (#1946).
        if verb == 'UPDATE':
            columns = _update_set_columns(statement)
        else:
            columns = []
        row = self._conn.execute(
            'SELECT has_table_privilege(%s, %s), (SELECT count(*) FILTER (WHERE '
            "has_column_privilege(%s, a.attnum, 'UPDATE')) = cardinality(%s::text[]) "
            'AND count(*) = cardinality(%s::text[]) FROM pg_attribute a '
            'WHERE a.attrelid = %s AND a.attname = ANY(%s::text[]) '
            'AND NOT a.attisdropped)',
            (relid, verb, relid, columns, columns, relid, columns),
        ).fetchone()
        return row is not None and (bool(row[0]) or (bool(columns) and bool(row[1])))

    def _replanned(self, run: Callable[[], Result]) -> Result:
        # A prepared statement whose table another session changed fails once:
        # "cached plan must not change result type" (#1885). PostgreSQL plans it
        # afresh on the next run, and the failed run was undone to its savepoint,
        # so it runs again.
        try:
            return run()
        except BackendError as error:
            cause = error.__cause__
            if not (
                isinstance(cause, psycopg.errors.FeatureNotSupported)
                and 'cached plan must not change result type' in str(cause)
            ):
                raise
        return run()

    def _hear_implicit_result(self, diagnostic: psycopg.errors.Diagnostic) -> None:
        message = diagnostic.message_primary or ''
        if message.startswith(_IMPLICIT_RESULT):
            self._implicit_portals.append(message[len(_IMPLICIT_RESULT) :])

    def _with_implicit_results(self, call: Callable[[], Result]) -> Result:
        # A call whose block returned cursors through DBMS_SQL.RETURN_RESULT
        # (#1617) answers with their rows as implicit results, in the order it
        # returned them, each portal fetched and closed -- before a COMMIT the
        # block asked for, which would close them.
        self._implicit_portals = []
        result = call()
        portals, self._implicit_portals = self._implicit_portals, []
        if not portals:
            return result
        implicit = []
        for portal in portals:
            name = sql.Identifier(portal)
            fetch = sql.SQL('FETCH ALL FROM {}').format(name)
            with self._conn.cursor() as cursor:
                cursor.execute(fetch)
                fetched = self._build_result(cursor)
                cursor.execute(sql.SQL('CLOSE {}').format(name))
            implicit.append((fetched.columns, fetched.rows))
        return replace(result, implicit_results=implicit)

    def _hear_commit_request(self, diagnostic: psycopg.errors.Diagnostic) -> None:
        if diagnostic.message_primary == _COMMIT_REQUEST:
            self._commit_requested = True

    def _committing(self, call: Callable[[], _Ran]) -> _Ran:
        # A client's call, committed after it succeeds when a routine it reached
        # ran a COMMIT (#1630). One that fails commits nothing: its savepoint
        # undoes the work, Oracle's after the COMMIT and this one's before it too.
        self._commit_requested = False
        try:
            result = call()
        except BaseException:
            self._commit_requested = False
            raise
        if self._commit_requested:
            self._commit_requested = False
            self.commit()
        return result

    def _reported(self, sql: str, run: Callable[[], _Ran]) -> _Ran:
        # Run a statement, and while the translation report is on, note what
        # translating it took and how it ended (#1557).
        if not self._reporting:
            return run()
        rules: list[str] = []
        token = _TRANSLATION_RULES.set(rules)
        try:
            result = run()
        except Exception as error:
            self._record_run(sql, rules, error)
            raise
        finally:
            _TRANSLATION_RULES.reset(token)
        self._record_run(sql, rules, None)
        return result

    def _record_run(self, sql: str, rules: list[str], error: Exception | None) -> None:
        # The report keeps the statement but for its passwords
        # (GHSA-27rj-h7p6-pmqf).
        sql = redact_passwords(sql)
        if _ALTER_SESSION_REPORT.match(sql) or _ALTER_SESSION_DIALECT.match(sql):
            return
        entry = self._report_runs.setdefault(_normalise_statement(sql), _ReportEntry())
        entry.rules.update(rules)
        entry.runs += 1
        entry.native = entry.native or self._is_native(sql)
        if error is not None:
            entry.failures += 1
            entry.last_error = str(error).splitlines()[0][:500] if str(error) else ''
        if sum(e.runs for e in self._report_runs.values()) >= _REPORT_FLUSH_EVERY:
            self._flush_report()

    def _flush_report(self) -> None:
        # Write the buffered runs out, on the report's own connection. A failure
        # loses them rather than the client's statement.
        if not self._report_runs:
            return
        rows = [
            (
                hashlib.sha256(statement.encode()).hexdigest(),
                statement,
                sorted(entry.rules),
                entry.runs,
                entry.failures,
                entry.last_error,
                entry.native,
            )
            for statement, entry in self._report_runs.items()
        ]
        self._report_runs = {}
        try:
            if self._report_conn is None:
                # The installer's role, whose record the report is (#1857).
                self._report_conn = psycopg.connect(
                    self._admin_conninfo, autocommit=True
                )
            with self._report_conn.cursor() as cursor:
                cursor.executemany(_REPORT_UPSERT, rows)
        except psycopg.Error:
            pass

    def _execute_statement(self, sql: str, binds: Sequence) -> Result:
        # A PL/SQL block from callproc / callfunc arrives with BindVar binds (the
        # Mirror's OUT-bind flow); run it via CALL / SELECT and return the OUT
        # values (#503). An ordinary statement's BindVar is a typed NULL, which
        # _translate_binds casts (#699).
        switch = _ALTER_SESSION_DIALECT.match(sql)
        if switch is not None:
            if not self._native_sql:
                # An ALTER SESSION parameter Oracle does not have (#1859).
                raise BackendError('invalid option for ALTER SESSION', ora_code=2248)
            self._sql_dialect = switch.group(1).lower()
            return Result()
        priority = _txn_priority_setting(sql)
        if priority is not None:
            self._txn_priority, rest = priority
            if rest is None:
                return Result()
            sql = rest
        report = _ALTER_SESSION_REPORT.match(sql)
        if report is not None:
            self._reporting = report.group(1).upper() == 'TRUE'
            if not self._reporting:
                self._flush_report()
            return Result()
        native = self._is_native(sql)
        stripped = _strip_leading_comments(sql)
        with _offset_from_start(len(sql) - len(stripped)):
            return self._execute_stripped(stripped, binds, native)

    def _execute_stripped(self, sql: str, binds: Sequence, native: bool) -> Result:
        # The statement past its leading whitespace and comments.
        sql = _ruled('editionable', _without_editionable(sql), sql)
        _refuse_reserved_bind_names(sql)
        _refuse_dml_on_dual(sql)
        transaction_control = self._execute_transaction_control(sql)
        if transaction_control is not None:
            return transaction_control
        kill = _KILL_SESSION.match(sql)
        if kill is not None:
            return self._kill_session(kill.group(1))
        dba = self._dba_statement(sql)
        if dba is not None:
            return dba
        if (gone := self._dropped_invalid_view(sql)) is not None:
            return gone
        users = self._user_statement(sql)
        if users is not None:
            return users
        synonym = self._synonym_statement(sql)
        if synonym is not None:
            return synonym
        system = self._system_grant_statement(sql)
        if system is not None:
            return system
        granted = self._object_grant_statement(sql)
        if granted is not None:
            return granted
        if native:
            return self._execute_native(sql, binds)
        synonyms = self._routine_synonyms()
        if synonyms:
            sql = _ruled('synonym-names', _through_synonyms(sql, synonyms), sql)
        refused = self._rowid_number_error(sql, binds)
        if refused is not None:
            raise refused
        binds = self._boolean_binds(
            sql, self._vector_text_binds(sql, self._oson_binds(sql, binds))
        )
        sql = _ruled('vector-literals', self._vector_text_literals(sql), sql)
        sql = _ruled('boolean-literals', self._boolean_literals(sql), sql)
        if self._release >= (23, 0):
            sql = _ruled('number-conditions', _number_conditions(sql), sql)
        sql = _ruled('json-dot-notation', self._json_dot_notation(sql), sql)
        sql = _ruled('raw-concatenation', self._hex_raw_operands(sql), sql)
        sql = _ruled('timestamp-fraction', self._formatted_fractions(sql), sql)
        sql = _ruled('datetime-text', self._datetime_text_operands(sql), sql)
        sql = _ruled('datetime-assignment', self._datetime_assignments(sql), sql)
        sql = _ruled('package-function-call', self._call_package_functions(sql), sql)
        bare = _BARE_CALL.match(sql)
        if bare is not None and bare.group(1).upper() not in _PLSQL_WORD_STATEMENTS:
            _note_rule('bare-call')
            # No binds, so the block would otherwise go to PostgreSQL as it
            # stands; the call path runs it as any other call (#1404).
            return self._execute_plsql(f'BEGIN {bare.group(1)}(); END;', binds)
        single = None if binds else _single_call_block(sql)
        if single is not None and self._routine_exists(single):
            _note_rule('plsql-call')
            # A call with literal arguments and no binds -- sqlplus's
            # `DBMS_OUTPUT.ENABLE(NULL)`, a script's put_line('...'). As a DO block
            # PostgreSQL refuses a bare function call; the call path runs it,
            # its arguments as written (#1531). Only a routine PostgreSQL has:
            # RAISE_APPLICATION_ERROR and the like are the block path's to
            # translate.
            return self._execute_plsql(sql, binds)
        if binds and is_plsql(sql):
            _note_rule('plsql-call')
            return self._collection_outs(self._execute_plsql(sql, binds), binds)
        # A `SELECT REF(alias)` object-REF fetch: PostgreSQL has no REF, so stand in
        # the row's ctid as the locator and report the referenced object type from
        # the typed table's catalog entry, so the client decodes a REF whose
        # type_name matches (#139). The 12c+ REF *bind* the test does next is skipped
        # by its own version guard on the 11g Mirror.
        ref_select = _REF_SELECT.match(sql)
        if ref_select and ref_select.group(1).lower() == ref_select.group(3).lower():
            _note_rule('ref-select')
            return self._execute_ref_select(ref_select)
        # Reject the column types that are Oracle-only for the version the Mirror
        # advertises (JSON/VECTOR/BOOLEAN), so the suite's version guards skip
        # rather than the backend mis-representing them (#504).
        _reject_unsupported_ddl_types(sql, self._release)
        if (
            not self._has_pgvector
            and _IS_CREATE_TABLE.match(sql)
            and _VECTOR_COLUMN.search(sql)
        ):
            raise BackendError(
                'invalid datatype: VECTOR needs the pgvector extension',
                ora_code=ORA_INVALID_DATATYPE,
            )
        # Register / forget an index-organized table, and render ROWID on one from
        # its primary key before the generic rewrite turns ROWID into ctid.
        iot = _iot_primary_key(sql)
        if iot is not None:
            self._iot_pk[iot[0]] = iot[1]
        dropped = _DROP_TABLE_NAME.match(sql)
        if dropped is not None:
            self._iot_pk.pop(_bare_table(dropped.group(1)), None)
        sql = _ruled('iot-rowid', self._rewrite_iot_rowid(sql), sql)
        # INVISIBLE / VISIBLE columns (#1195): the attribute comes out of the DDL
        # and goes to the catalog; a MODIFY that only changes it has nothing left
        # to run. An INSERT with no column list and a `SELECT *` name only the
        # visible columns.
        (sql, visibility) = _column_visibility(sql)
        if visibility is not None:
            _note_rule('invisible-columns')
        # SQL domains and annotations (#1711): a column's DOMAIN is its type,
        # its annotations go to the catalog.
        (stripped, annotated) = _column_annotations(sql)
        sql = _ruled('domain-annotations', stripped, sql)
        if visibility is not None and visibility[3]:
            self._record_visibility(visibility)
            return Result()
        sql = _ruled('invisible-columns', self._expand_visible_columns(sql), sql)
        sql = _ruled('hex-to-raw', self._to_raw_targets(sql), sql)
        # Oracle auto-commits DDL — decide from the original statement, before the
        # dialect rewrite reshapes it (#532).
        is_ddl = _IS_DDL.match(sql) is not None
        original = sql
        self._require_package_owner(sql)
        # Translate Oracle SQL to PostgreSQL's dialect (#500/#502/#503) — DDL
        # column types, CREATE PROCEDURE/FUNCTION → PL/pgSQL, then the function /
        # literal idioms. This is where dialect knowledge belongs, not in the
        # generic compat shim.
        sql = _ruled('reserved-name', _quote_reserved_names(sql), sql)
        sql = _ruled(
            'package-ddl',
            _translate_package_ddl(
                sql,
                self._package_index_types,
                self._user_routine_names,
                self._routine_kind,
            ),
            sql,
        )
        sql = _ruled('admin', _translate_admin(sql), sql)
        sql = _ruled('instant-index', self._instant_index_keys(sql), sql)
        sql = _ruled('constraint-names', self._named_constraints(sql), sql)
        checks = _check_conditions(sql)
        sql = _ruled('ddl', _translate_ddl(sql), sql)
        sql = _ruled('trigger-ddl', self._created_trigger(sql), sql)
        sql = _ruled('drop-trigger', self._dropped_trigger(sql), sql)
        sql = _ruled('alter-trigger', self._altered_trigger(sql), sql)
        sql = _ruled(
            'routine-ddl',
            _translate_routine_ddl(
                sql,
                self._user_routine_names() if _ROUTINE_HEAD.match(sql) else None,
                routine_kind=self._routine_kind,
            ),
            sql,
        )
        sql = _ruled(
            'plsql-block', _translate_plsql_block(sql, self._routine_kind), sql
        )
        sql = _translate_idioms(sql)
        sql = _ruled(
            'one-element-constructor',
            _spell_one_element_constructors(sql, self._collection_names()),
            sql,
        )
        with_rowid = self._returning_rowid(original, sql)
        if with_rowid is not None:
            sql = with_rowid
        params: dict | None = None
        if binds:
            binds = self._resolve_object_binds(binds)
            sql, params = _translate_binds(sql, binds)
        # Each statement runs inside a SAVEPOINT so a failure rolls back just it
        # (clearing PostgreSQL's aborted-transaction state) and leaves the rest of
        # the transaction intact — Oracle's statement-level error model. The
        # pipelined path ships the SAVEPOINT, the statement and the RELEASE in one
        # network round-trip instead of three; the sequential path is the fallback
        # when libpq is too old for pipeline mode. DDL stays sequential: pipeline
        # mode forces the extended query protocol, which rejects the multi-command
        # `DROP …; CREATE …` a routine DDL rewrites to (#526) — the simple protocol
        # the sequential path uses accepts it. DDL is infrequent and auto-commits,
        # so the hot SELECT/DML path (single-command) is where the round-trips count.
        # A block with local functions is several commands too (#1322).
        hoisted = sql.startswith(_HOISTED_FUNCTION)
        # A NOT NULL column's NVL cut to the column (#1889), behind a guard that
        # the schema it was read from is still the database's.
        fallback = None
        if (
            self._use_pipeline
            and not is_ddl
            and not hoisted
            and self._has_ddl_log
            and self._has_ddl_guard
            and self._ddl_generation is not None
        ):
            rewritten = _ruled('not-null-nvl', self._without_dead_nvl(sql), sql)
            if rewritten != sql:
                (fallback, sql) = (sql, rewritten)
        self._last_translated = sql
        if self._use_pipeline and not is_ddl and not hoisted:
            result = self._execute_pipelined(sql, params, original, fallback)
        elif is_ddl:
            prelude = _DDL_LOCK_TIMEOUT
            dropping = _DROP_RELATION.match(sql)
            if dropping is not None:
                # The views over it stay, INVALID (#2201).
                prelude += (
                    '; SELECT sys.ora_invalidate_dependents('
                    f'sys.ora_regclass({_sql_text(dropping.group(1))}))'
                )
            try:
                result = self._execute_sequential(
                    sql, params, original, prelude=prelude
                )
            except BackendError as error:
                invalid = self._create_invalid(original, error)
                if invalid is None:
                    raise
                result = invalid
            else:
                checked = self._compile_checked(original)
                if checked is not None:
                    result = checked
        else:
            result = self._execute_sequential(sql, params, original)
        # DDL auto-commits (Oracle semantics): persist it — and any pending DML —
        # so a later rollback discards only DML, not the table (#532).
        if is_ddl:
            if (
                self._has_ddl_log
                and self._conn.info.transaction_status
                != psycopg.pq.TransactionStatus.INERROR
            ):
                # The generation this DDL made, read before its commit, which
                # its own log row is in: the next statement's guard does not
                # take it for another session's DDL (#1889).
                row = self._conn.execute('SELECT ' + _DDL_GENERATION).fetchone()
                self._ddl_generation = None if row is None else row[0]
            self._conn.commit()
            self._user_savepoint = False
            self._prune_records()
            self._follow_grants(original)
            self._record_source(original)
            self._record_quoted_names(original)
            self._record_tstz_precisions(original)
            self._record_visibility(visibility)
            self._record_column_types(original)
            self._record_annotations(annotated)
            self._record_check_conditions(checks)
            self._record_trigger(original)
            self._revalidate_views()
            self._relations.clear()
            self._relids.clear()
            self._collection_name_cache = None  # a type may have come or gone
            self._routine_synonym_cache = None  # and a synonym
            self._package_function_cache = None  # and a package
            self._plsql_types.clear()
            self._forget_raw_targets()
        if with_rowid is not None:
            # The rows are the rowids of the rows touched, not a result set: a
            # DML still answers with a count, and the last one is its rowid.
            rows = result.rows
            return Result(
                rowcount=len(rows), last_rowid=_dml_rowid(*rows[-1]) if rows else None
            )
        if result.columns and not is_ddl:
            self._release_read_locks()
        return result

    def _is_native(self, sql: str) -> bool:
        # Whether a statement is PostgreSQL's own, to run untranslated (#1556),
        # where the operator allows that at all (#1859).
        if not self._native_sql:
            return False
        return self._sql_dialect == 'postgres' or _PG_HINT.match(sql) is not None

    def _execute_native(self, sql: str, binds: Sequence) -> Result:
        # A native PostgreSQL statement (#1556): none of the Oracle translation,
        # but the Oracle binds mapped, the statement-level savepoint and DDL's
        # autocommit, which the client on the other end still expects.
        is_ddl = _IS_DDL.match(sql) is not None
        params: dict | None = None
        if binds:
            binds = self._resolve_object_binds(binds)
            (sql, params) = _translate_binds(sql, binds)
        if self._use_pipeline and not is_ddl:
            result = self._execute_pipelined(sql, params, sql)
        else:
            result = self._execute_sequential(sql, params, sql)
        if is_ddl:
            self._conn.commit()
            self._user_savepoint = False
            self._collection_name_cache = None
            self._routine_synonym_cache = None
            self._forget_raw_targets()
        elif result.columns:
            self._release_read_locks()
        return result

    def _record_compile_error(
        self, sql: str, owner: str | None, name: str, kind: str, error: BackendError
    ) -> None:
        # The error ALL_ERRORS lists for the object (#2060), in place of any it
        # had: where it is in the source, from the object's keyword on, as
        # Oracle counts, and its text.
        rows: list[tuple[int, int, str, int]]
        if isinstance(error, _CheckedErrors):
            rows = list(error.rows)
        else:
            (line, position, text, number) = _compile_error_place(sql, kind, error)
            rows = [(line, position, text, number)]
            if number == 201:
                # Oracle lists the statement it then ignored, at its start, which
                # is where the undeclared name stands in the statements read so
                # far (#2121).
                rows.append((line, position, 'PL/SQL: Statement ignored', 0))
        owner_sql = '%s' if owner else 'sys.ora_owner(current_schema())'
        params: list = [owner.upper()] if owner else []
        self._conn.execute(
            f'DELETE FROM sys.ora_errors WHERE owner = {owner_sql} AND name = %s '
            'AND type = %s',
            (*params, name, kind),
        )
        # Rows of objects no longer INVALID, dropped or recompiled, go too.
        self._conn.execute(
            'DELETE FROM sys.ora_errors e WHERE NOT EXISTS (SELECT 1 FROM '
            'all_objects o WHERE o.owner = e.owner AND o.object_name = e.name '
            "AND o.object_type = e.type AND o.status = 'INVALID')"
        )
        for sequence, (line, position, row_text, row_number) in enumerate(rows, 1):
            self._conn.execute(
                'INSERT INTO sys.ora_errors (owner, name, type, sequence, line, '
                f'position, text, message_number) VALUES ({owner_sql}, %s, %s, '
                '%s, %s, %s, %s, %s)',
                (*params, name, kind, sequence, line, position, row_text, row_number),
            )

    def _compile_checked(self, sql: str) -> Result | None:
        """A standalone procedure or function PostgreSQL created whose body
        names what does not resolve, made INVALID as Oracle's compiler makes
        it (#2129): plpgsql_check, where it is installed, resolves the names
        PL/pgSQL leaves to the first call. Each error ALL_ERRORS lists as
        23ai does -- an undeclared name PLS-00201, a call no routine takes
        PLS-00306, a column or table an SQL statement names ORA-00904 or
        ORA-00942 -- at the name, then the statement it ignored, at its
        start. An error it cannot place is left: the routine stays VALID, as
        before. None where nothing is wrong, or nothing checks."""
        routine = _ROUTINE_HEAD.match(sql)
        package = None if routine else _PACKAGE_HEAD.match(sql)
        trigger = None if routine or package else _CREATE_TRIGGER.match(sql)
        if routine is None and package is None and trigger is None:
            return None
        if package is not None and not package.group(1):
            return None  # a spec has no code to check
        if not self._has_plpgsql_check():
            return None
        source = None
        if routine is not None:
            (schema, name) = _pg_routine_name(routine.group(2))
            query = (
                'SELECT c.statement, c.sqlstate, c.message FROM pg_proc p '
                'CROSS JOIN LATERAL plpgsql_check_function_tb(p.oid, '
                'fatal_errors => false) c WHERE p.proname = %s '
                "AND p.pronamespace = coalesce(to_regnamespace(nullif(%s, '')), "
                "current_schema()::regnamespace) AND c.level = 'error'"
            )
            params: tuple = (name, schema)
        elif package is not None:
            # A package body's members, each its schema's function (#2212).
            query = (
                'SELECT c.statement, c.sqlstate, c.message FROM pg_proc p '
                'JOIN pg_language l ON l.oid = p.prolang '
                'CROSS JOIN LATERAL plpgsql_check_function_tb(p.oid, '
                'fatal_errors => false) c WHERE p.pronamespace = to_regnamespace(%s) '
                "AND l.lanname = 'plpgsql' AND p.prorettype <> 'trigger'::regtype "
                "AND c.level = 'error'"
            )
            params = (package.group(3).lower(),)
        else:
            # A trigger's function, checked against its table; Oracle counts
            # its errors' places from its block (#2212).
            assert trigger is not None
            table = self._trigger_table(trigger.group(2))
            if table is None:
                return None
            query = (
                'SELECT c.statement, c.sqlstate, c.message FROM '
                'plpgsql_check_function_tb(to_regprocedure(%s), to_regclass(%s), '
                "fatal_errors => false) c WHERE c.level = 'error'"
            )
            params = (f'{_trigger_function_name(trigger.group(2))}()', table)
            source = sql[trigger.start(9) :]
        try:
            with self._conn.transaction():
                found = self._conn.execute(query, params).fetchall()
        except psycopg.Error:
            return None
        rows = _checked_error_rows(sql, found, self._routine_names_known(), source)
        if not rows:
            return None
        if trigger is not None:
            return self._invalid_trigger(trigger, sql, _CheckedErrors(rows))
        return self._create_invalid(sql, _CheckedErrors(rows))

    def _invalid_trigger(
        self, trigger: re.Match, sql: str, error: BackendError
    ) -> Result | None:
        # A trigger that does not compile (#2212): it stays, ENABLED, and
        # INVALID -- its function raises ORA-04098 as the trigger fires, as
        # Oracle's does -- with its errors in ALL_ERRORS.
        name = trigger.group(2)
        (schema, _dot, bare) = name.rpartition('.')
        table = self._trigger_table(name)
        if table is None:
            return None
        try:
            row = self._conn.execute(
                'SELECT upper(coalesce(%s, current_schema()))',
                (_pg_identifier(schema) if schema else None,),
            ).fetchone()
            owner = row[0] if row else ''
            message = (
                f"ORA-04098: trigger '{owner}.{_oracle_name(bare)}' is invalid and "
                'failed re-validation'
            ).replace("'", "''")
            self._conn.execute(
                f'CREATE OR REPLACE FUNCTION {_trigger_function_name(name)}() '
                'RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION USING '
                f"ERRCODE = 'P0001', MESSAGE = '{message}'; END $$; "
                f'COMMENT ON TRIGGER {bare} ON {table} IS '
                f"'{_TRIGGER_MARK}INVALID'"
            )
            self._record_compile_error(
                sql,
                _oracle_name(schema) if schema else None,
                _oracle_name(bare),
                'TRIGGER',
                error,
            )
        except psycopg.Error:
            self._conn.rollback()
            return None
        return Result(compilation_warning=True)

    def _has_plpgsql_check(self) -> bool:
        # Whether the database has plpgsql_check (#2129), looked up once.
        if self._plpgsql_check is None:
            row = self._conn.execute(
                "SELECT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'plpgsql_check')"
            ).fetchone()
            self._plpgsql_check = bool(row and row[0])
        return self._plpgsql_check

    def _routine_names_known(self) -> frozenset[str]:
        # The names of the functions a session's statements can call, lower
        # case: a call one of them refuses is PLS-00306, not PLS-00201 (#2129).
        rows = self._conn.execute(
            'SELECT DISTINCT p.proname FROM pg_proc p WHERE p.pronamespace = ANY('
            'current_schemas(true)::regnamespace[])'
        ).fetchall()
        return frozenset(name for (name,) in rows)

    def _create_invalid(self, sql: str, error: BackendError) -> Result | None:
        # A CREATE PROCEDURE / FUNCTION / TYPE that does not compile SUCCEEDS in
        # Oracle: the object exists, INVALID, and the reply says so with the
        # compilation warning the client reads as DPY-7000 (#1499). PostgreSQL
        # refuses it outright, so a stand-in of that name takes its place -- a
        # routine that fails when called, as an invalid one does (ORA-06550 in a
        # block, #1497), or a shell type -- and a later CREATE replaces it as it
        # would the invalid object. None for any other failure.
        if error.ora_code not in _COMPILE_ERROR_CODES:
            return None
        package = _PACKAGE_HEAD.match(sql)
        if package is not None:
            return self._create_invalid_package(package, sql, error)
        routine = _ROUTINE_HEAD.match(sql)
        type_ = _INVALID_TYPE_DDL.match(sql) if routine is None else None
        if routine is not None:
            kind, name = routine.group(1).upper(), routine.group(2)
            returns = ' RETURNS integer' if kind == 'FUNCTION' else ''
            stub = (
                f'DROP {kind} IF EXISTS {name}; CREATE {kind} {name}(){returns} '
                'LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION USING ERRCODE = '
                f"'42883', MESSAGE = 'function {name}() does not exist'; END $$; "
                + _routine_mark(name, 'INVALID')
            )
        elif type_ is not None:
            # An object type with no attributes, as Oracle's ALL_TYPES lists an
            # invalid one; not a shell type, which only a superuser may make
            # (#1937). Marked, so ALL_OBJECTS lists it INVALID (#1940).
            name = type_.group(1)
            stub = (
                f'DROP TYPE IF EXISTS {name}; CREATE TYPE {name} AS (); '
                f"COMMENT ON TYPE {name} IS '{_TYPE_MARK}INVALID'"
            )
        else:
            return None
        try:
            self._conn.execute(stub)
            (schema, _dot, bare) = (
                (routine.group(2) if routine is not None else name)
                .upper()
                .rpartition('.')
            )
            self._record_compile_error(
                sql,
                schema or None,
                bare,
                routine.group(1).upper() if routine is not None else 'TYPE',
                error,
            )
        except psycopg.Error:
            self._conn.rollback()
            return None
        return Result(compilation_warning=True)

    def _create_invalid_package(
        self, head: re.Match, sql: str, error: BackendError
    ) -> Result | None:
        # A package spec or body that does not compile (#1605). A body that does
        # not leaves the spec's stand-ins, which now raise ORA-04063; a spec
        # leaves its schema empty, the package INVALID, so a call finds nothing.
        # A body with no spec at all leaves nothing.
        body, owner, name, _authid = head.groups()
        package = name.lower()
        if body:
            known = self._conn.execute(
                'SELECT owner FROM sys.ora_packages WHERE name = %s', (package,)
            ).fetchone()
            if known is None:
                return Result(compilation_warning=True)
            # The owner its spec recorded: a body PostgreSQL created leaves the
            # package's schema first on the transaction's path (#2212).
            owner = owner or known[0]
            stub = _restore_package_stubs(package, 'INVALID')
        else:
            owner_sql = (
                f"'{owner.upper()}'" if owner else 'sys.ora_owner(current_schema())'
            )
            stub = (
                f'DROP SCHEMA IF EXISTS {package} CASCADE; CREATE SCHEMA {package}; '
                'INSERT INTO sys.ora_packages (name, owner, stubs, spec, body) '
                f"VALUES ('{package}', {owner_sql}, '', 'INVALID', NULL) "
                'ON CONFLICT (name) DO UPDATE SET owner = EXCLUDED.owner, '
                "stubs = '', spec = 'INVALID', body = NULL"
            )
        try:
            self._conn.execute(stub)
            self._record_compile_error(
                sql,
                owner,
                name.upper(),
                'PACKAGE BODY' if body else 'PACKAGE',
                error,
            )
        except psycopg.Error:
            self._conn.rollback()
            return None
        return Result(compilation_warning=True)

    def _kill_session(self, session: str) -> Result:
        # ALTER SYSTEM KILL SESSION (#1212): end the backend whose pid is the SID,
        # but only while its serial is the one named, so a pid reused by a later
        # session is not killed in its place. The victim learns of it on its next
        # call, its connection gone, as a killed Oracle session's is. Like any
        # ALTER SYSTEM it leaves the caller's transaction alone.
        self._require_administrator('ALTER SYSTEM')
        ids = _KILL_SESSION_ID.match(session)
        if ids is None:
            raise BackendError(
                'missing or invalid session ID', ora_code=ORA_INVALID_SESSION_ID
            )
        (sid, serial) = (int(ids.group(1)), int(ids.group(2)))
        row = self._conn.execute(
            'SELECT pg_backend_pid() FROM pg_stat_activity '
            'WHERE pid = %s AND sys.ora_serial(pid) = %s',
            (sid, serial),
        ).fetchone()
        if row is None:
            raise BackendError(
                'User session ID does not exist.',
                ora_code=ORA_SESSION_ID_DOES_NOT_EXIST,
            )
        if row[0] == sid:
            raise BackendError(
                'cannot kill current session', ora_code=ORA_CANNOT_KILL_CURRENT_SESSION
            )
        # Wait for the victim's backend to exit before answering, as Oracle's kill
        # does, or the victim's next call could still run on it (#1367).
        # In per-user mode the victim may be another user's role, which only
        # the installer's may end (#1857).
        with self._administering() as conn:
            conn.execute(
                'SELECT pg_terminate_backend(%s, %s)', (sid, _KILL_SESSION_WAIT_MS)
            )
        return Result()

    def _execute_transaction_control(self, sql: str) -> Result | None:
        # COMMIT / ROLLBACK / SAVEPOINT / ROLLBACK TO as SQL text, outside the
        # per-statement savepoint (#1181); None for any other statement.
        end = _TRANSACTION_END.match(sql)
        if end is not None:
            if end.group(1).upper() == 'COMMIT':
                self.commit()
            else:
                self.rollback()
            return Result()
        savepoint = _SAVEPOINT.match(sql)
        if savepoint is not None:
            self._conn.execute(f'SAVEPOINT {savepoint.group(1)}')
            self._user_savepoint = True
            return Result()
        rollback_to = _ROLLBACK_TO.match(sql)
        if rollback_to is None:
            return None
        # Still under `_mirror_stmt`, so an unknown name fails as ORA-01086 and
        # leaves the transaction usable, as Oracle's does; PostgreSQL alone would
        # abort it. On success there is nothing to release: rolling back to the
        # older savepoint has destroyed `_mirror_stmt` already.
        self._conn.execute('SAVEPOINT _mirror_stmt')
        try:
            self._conn.execute(f'ROLLBACK TO SAVEPOINT {rollback_to.group(1)}')
        except psycopg.Error as exc:
            self._conn.execute('ROLLBACK TO SAVEPOINT _mirror_stmt')
            self._conn.execute('RELEASE SAVEPOINT _mirror_stmt')
            raise _backend_error(
                exc, original=sql, arities=self._routine_arities
            ) from exc
        return Result()

    @_while_connected
    @_plainly_quoted
    def execute_returning(self, sql: str, rows: Sequence[Sequence]) -> Result:
        # DML ... RETURNING col INTO :b (#689). PostgreSQL has the feature but
        # spells it without the INTO part, handing the columns back as rows
        # rather than assigning them to binds, so the clause is trimmed to the
        # form it knows and the rows are read.
        #
        # Each iteration goes through `execute` so the whole dialect rewrite,
        # bind translation and per-statement savepoint apply exactly as they do
        # to any other statement. The binds the clause fills carry no value and
        # are dropped: their placeholders are gone from the trimmed text.
        #
        # Each value is converted to the type its receiving bind declared, as
        # Oracle converts it, inside a savepoint of the iteration's own: a value
        # that cannot be converted fails the iteration and undoes it, and only
        # it (#1370).
        statement = strip_returning_into(sql)
        returned: list[list[tuple]] = []
        affected = 0
        # The iteration's savepoint has to outlive `execute`, which ends a
        # transaction that wrote nothing to let its read locks go -- an UPDATE
        # that matched no row, say -- and would take the savepoint with it. It
        # spares one the client took; this one is spared the same way, and the
        # locks are let go once the loop is done.
        client_savepoint = self._user_savepoint
        self._user_savepoint = True
        try:
            for row in rows:
                values = [v for v in row if not isinstance(v, BindVar)]
                declared = [v.tns_type for v in row if isinstance(v, BindVar)]
                self._conn.execute('SAVEPOINT _mirror_returning')
                try:
                    result = self.execute(statement, values)
                    iteration = [
                        tuple(
                            as_declared_type(value, declared[i])
                            if i < len(declared)
                            else value
                            for i, value in enumerate(r)
                        )
                        for r in result.rows
                    ]
                except BackendError as err:
                    self._conn.execute('ROLLBACK TO SAVEPOINT _mirror_returning')
                    self._conn.execute('RELEASE SAVEPOINT _mirror_returning')
                    err.rowcount = affected
                    raise
                self._conn.execute('RELEASE SAVEPOINT _mirror_returning')
                returned.append(iteration)
                # A RETURNING statement gives back one row per row it changed,
                # so the count is the rows read rather than a separate report.
                affected += len(iteration)
        finally:
            self._user_savepoint = client_savepoint
        self._release_read_locks()
        return Result(rowcount=affected, returned_rows=returned)

    def _returning_rowid(self, original: str, translated: str) -> str | None:
        # The translated DML with the rowid RETURNING added, or None where it
        # does not apply: not an INSERT / UPDATE / DELETE, one that returns
        # something already, one on an index-organized table, whose ROWID is
        # its primary key rather than a heap address, or one through a view,
        # which has no heap address of its own to return (#2202).
        if not _DML_HEAD.match(translated) or _HAS_RETURNING.search(translated):
            return None
        table = _STATEMENT_TABLE.search(original)
        if table is not None and _bare_table(table.group(1)) in self._iot_pk:
            return None
        if table is not None and self._relation_columns(table.group(1)) is not None:
            if self._relids.get(table.group(1)) in self._view_relids:
                return None
        if self._per_user and table is not None and '.' in table.group(1):
            # Another user's table, which one may be granted INSERT, UPDATE
            # or DELETE on and not SELECT, which PostgreSQL's RETURNING needs
            # (#1858): the statement runs, its ROWID unknown.
            row = self._conn.execute(
                "SELECT has_table_privilege(sys.ora_regclass(%s), 'SELECT')",
                (table.group(1),),
            ).fetchone()
            if row is not None and row[0] is False:
                return None
        return translated.rstrip().rstrip(';') + _ROWID_RETURNING

    def _rewrite_iot_rowid(self, sql: str) -> str:
        # ROWID on a registered index-organized table → its logical-rowid
        # expression. The statement's table is its first FROM / UPDATE / INTO
        # target; anything else is left for the generic ctid rewrite.
        if not self._iot_pk or _ROWID_WORD.search(sql) is None:
            return sql
        table = _STATEMENT_TABLE.search(sql)
        if table is None:
            return sql
        pk = self._iot_pk.get(_bare_table(table.group(1)))
        if pk is None:
            return sql
        return _ROWID_WORD.sub(_urowid_expression(pk), sql)

    def _forget_raw_targets(self) -> None:
        self._has_raw_targets_cache = None
        self._raw_constructor_cache = None

    def _has_raw_targets(self) -> bool:
        if self._has_raw_targets_cache is None:
            self._read_schema_facts()
        return bool(self._has_raw_targets_cache)

    def _read_schema_facts(self) -> None:
        # The facts about the whole schema that nearly every statement asks
        # after, read together in one query (#1918), each until a DDL: the
        # collection types' names, whether any column is a recorded RAW
        # (#1496), and whether any column could owe a describe a SQL domain or
        # annotations (#1711); and the object types with a RAW attribute, each
        # with the positions of its RAW attributes (#1496, #1331). A database
        # with no column catalog has no RAW or annotation to find.
        recorded = (
            "EXISTS (SELECT 1 FROM sys.ora_columns WHERE data_type = 'RAW'), "
            'EXISTS (SELECT 1 FROM sys.ora_annotations) OR EXISTS '
            "(SELECT 1 FROM pg_type WHERE typtype = 'd' AND "
            "obj_description(oid, 'pg_type') = %s), "
            '(SELECT json_agg(json_build_array(typname, schema, positions)) FROM '
            '(SELECT lower(c.relname) AS typname, lower(n.nspname) AS schema, '
            'array_agg(x.pos - 1) AS positions '
            'FROM (SELECT attrelid, attnum, row_number() OVER '
            '(PARTITION BY attrelid ORDER BY attnum) AS pos FROM pg_attribute '
            'WHERE attnum > 0 AND NOT attisdropped) x '
            'JOIN sys.ora_columns o ON o.relid = x.attrelid '
            "AND o.attnum = x.attnum AND o.data_type = 'RAW' "
            "JOIN pg_class c ON c.oid = x.attrelid AND c.relkind = 'c' "
            'JOIN pg_namespace n ON n.oid = c.relnamespace GROUP BY 1, 2) r)'
            if self._has_column_catalog
            else 'false, false, NULL'
        )
        row = self._catalog_read(
            'SELECT (SELECT array_agg(ARRAY[lower(t.typname), lower(n.nspname)]) '
            'FROM pg_type t '
            'JOIN pg_namespace n ON n.oid = t.typnamespace '
            "JOIN pg_type b ON b.oid = t.typbasetype AND b.typcategory = 'A' "
            "WHERE t.typtype = 'd' "
            "AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'oracle')), "
            f'{recorded}',
            (_SQL_DOMAIN_MARK,) if self._has_column_catalog else (),
        ).fetchone()
        assert row is not None
        collections = row[0] or ()
        self._collection_name_cache = frozenset(
            name
            for typname, schema in collections
            for name in (typname, f'{schema}.{typname}')
        )
        self._has_raw_targets_cache = bool(row[1])
        self._has_sql_domains_cache = bool(row[2])
        self._raw_constructor_cache = {
            key: frozenset(positions)
            for typname, schema, positions in row[3] or ()
            for key in (typname, f'{schema}.{typname}')
        }

    def _json_dot_notation(self, sql: str) -> str:
        """Oracle's simple dot notation into a JSON column, `alias.column.key
        [.key ...]`, as PostgreSQL's `(alias.column -> 'key' ...)` (#1707). The
        same spelling is object attribute access (#1434), so only a path whose
        alias names a table whose column is JSON is rewritten here; the rest is
        left to that rewrite. A key is matched as written."""
        if '.' not in sql:
            return sql
        (masked, contents) = _mask_quoted(sql)
        tables = {
            m.group(2).upper(): _unmask_quoted(m.group(1), contents)
            for m in _CORRELATION_NAME.finditer(masked)
        }
        if not tables:
            return sql
        out: list[str] = []
        pos = 0
        for match in _ATTRIBUTE_PATH.finditer(masked):
            table = tables.get(match.group(1).upper())
            column = _unmask_quoted(match.group(2), contents)
            if table is None or not self._is_json_column(table, column):
                continue
            keys = _ATTRIBUTE_DOT.split(_unmask_quoted(match.group(3), contents))[1:]
            path = ''
            for key in keys:
                name = key[1:-1] if key.startswith('"') else key
                path += f' -> {_sql_text(name)}'
            out.append(_unmask_quoted(masked[pos : match.start()], contents))
            out.append(f'({match.group(1)}.{column}{path})')
            pos = match.end()
        if not out:
            return sql
        out.append(_unmask_quoted(masked[pos:], contents))
        return ''.join(out)

    def _is_json_column(self, table: str, column: str) -> bool:
        # Whether a table's column is JSON (jsonb), from the schema model
        # (#1707, #1887).
        name = _pg_identifier(column)
        return any(
            found.name == name and found.type_oid in (_JSONB_OID, self._oson_oid)
            for found in (self._relation_columns(table) or {}).values()
        )

    def _hex_raw_operands(self, sql: str) -> str:
        """`sql` with each RAW column it concatenates as its hex text,
        RAWTOHEX(col) (#2158). Oracle converts a RAW operand of || or CONCAT
        to its hex, `0A1Bx`; PostgreSQL's || joined the bytes, and its untyped
        literal took the RAW's type. A name that is no column of the query's
        FROM tables, or is one of more than one, is left as it is."""
        if '||' not in sql and 'concat' not in sql.lower():
            return sql
        operands = _concatenated_columns(sql)
        tables = _from_tables(sql) if operands else []
        if not tables:
            return sql
        out = [span[1] for span in _bind_spans(sql)]
        changed = False
        for first, last, parts in operands:
            if self._concatenated_type(tables, parts) in _RAW_OIDS:
                out[first] = 'rawtohex(' + out[first]
                out[last] += ')'
                changed = True
        return ''.join(out) if changed else sql

    def _datetime_text_operands(self, sql: str) -> str:
        """`sql` with each DATE or TIMESTAMP column it converts to text
        without a format -- an operand of || or CONCAT, the argument of
        TO_CHAR(c), the value of a CAST to a character type -- as Oracle's
        text of it, sys.ora_datetime_text(col, p) (#2162), and each value
        whose type its text says. PostgreSQL's text was its own,
        `2024-01-02 13:14:15`, and orafce's TO_CHAR(ts) printed a TIMESTAMP as
        a DATE. A function over the value sees neither the DATE domain nor the
        precision, so the column's type comes from the schema model. A name
        that is no column of the query's FROM tables, or is one of more than
        one, is left."""
        lowered = sql.lower()
        if '||' not in sql and not any(
            word in lowered for word in ('concat', 'to_char', 'cast')
        ):
            return sql
        # A literal, SYSDATE, TO_DATE or CAST says its own type.
        wraps = list(_typed_datetime_operands(sql))
        operands = _converted_columns(sql)
        tables = _from_tables(sql) if operands else []
        for first, last, parts in operands if tables else []:
            converted = self._datetime_text_call(
                self._concatenated_column(tables, parts)
            )
            if converted is not None:
                wraps.append((first, last, *converted))
        spans = _bind_spans(sql)
        for first, last in _computed_operands(sql):
            precision = self._computed_precision(
                ''.join(span[1] for span in spans[first : last + 1]),
                tables or _from_tables(sql),
            )
            if precision is not None:
                wraps.append((first, last, 'sys.ora_computed_text', precision))
        if not wraps:
            return sql
        out = [span[1] for span in spans]
        for first, last, call, precision in wraps:
            out[first] = f'{call}({out[first]}'
            out[last] += f', {precision})'
        return ''.join(out)

    def _computed_precision(
        self, expression: str, tables: list[tuple[str | None, str, str | None]]
    ) -> int | None:
        """The precision Oracle gives a computed DATE or TIMESTAMP, a group or
        a call, by its operands (#2162), -1 for a DATE; None where none of
        its operands is one, or one is zoned. Measured on 23ai: a TIMESTAMP
        with an interval is a TIMESTAMP(9); with a number, or under TRUNC,
        ROUND, ADD_MONTHS, LAST_DAY or NEXT_DAY, a DATE; under NVL, GREATEST,
        MAX and the like, its own precision. With only DATE operands, a DATE."""
        spans = _bind_spans(expression)
        sig = [span[1] for span in spans if span[0] not in ('space', 'comment')]

        def text(k: int) -> str:
            return sig[k] if 0 <= k < len(sig) else ''

        (dates, stamps, interval) = (False, [], False)
        for k in range(len(sig)):
            word = text(k).upper()
            if (word == 'INTERVAL' and text(k + 1).startswith("'")) or (
                word in _INTERVAL_CALLS and text(k + 1) == '('
            ):
                interval = True
            typed = _typed_datetime_at(text, k) if text(k - 1) != '.' else None
            if typed is not None:
                if typed[1] != _DATETIME_TEXT:
                    return None
                if typed[2] < 0:
                    dates = True
                else:
                    stamps.append(typed[2])
        for name in _column_operands(expression):
            column = (
                self._concatenated_column(tables, name.split('.')) if tables else None
            )
            if column is None:
                continue
            if column.type_oid == _INTERVAL_OID or (
                self._intervalym_oid is not None
                and column.type_oid == self._intervalym_oid
            ):
                interval = True
                continue
            converted = self._datetime_text_call(column)
            if converted is None:
                continue
            if converted[0] != _DATETIME_TEXT:
                return None
            if converted[1] < 0:
                dates = True
            else:
                stamps.append(converted[1])
        if not dates and not stamps:
            return None
        if text(0).upper() in _DATE_RESULT_CALLS:
            return -1
        if not stamps:
            return -1
        if interval:
            return 9
        depth = 0
        for word in sig:
            depth += (word == '(') - (word == ')')
            if depth <= 1 and word in ('+', '-'):
                return -1
        return max(stamps)

    def _datetime_text_call(
        self, column: _TableColumn | None
    ) -> tuple[str, int] | None:
        # The call that makes a datetime column's value Oracle's text, and the
        # column's precision, -1 for a DATE; None for any other column (#2162).
        if column is None:
            return None
        default = 6 if column.typmod < 0 else column.typmod
        if self._domain_type_by_oid.get(column.type_oid) == TNS_TYPE_DATE:
            return (_DATETIME_TEXT, -1)
        if column.type_oid == _TIMESTAMP_OID:
            return (_DATETIME_TEXT, default)
        if column.type_oid == _TIMESTAMPTZ_OID:
            return (_LTZ_TEXT, default)
        if self._tstz_oid is not None and column.type_oid == self._tstz_oid:
            precision = column.tstz_precision
            return (_TSTZ_TEXT, 6 if precision is None else precision)
        return None

    def _formatted_fractions(self, sql: str) -> str:
        """`sql` with each TO_CHAR(x, fmt) whose format has FF or X, where x
        is a TIMESTAMP, as sys.ora_to_char(x, fmt, p): FF prints p digits,
        the value's precision -- a column's own, 9 for a TIMESTAMP literal or
        a TIMESTAMP with an interval, n for CAST(... AS TIMESTAMP(n)) -- where
        to_char(timestamp, text) prints 6 (#2167). Measured on 23ai."""
        if 'to_char' not in sql.lower():
            return sql
        found = _formatted_datetimes(sql)
        if not found:
            return sql
        tables = _from_tables(sql)
        spans = _bind_spans(sql)
        out = [span[1] for span in spans]
        changed = False
        for name, close, value in found:
            converted = _typed_datetime_value(value)
            if converted is None and re.fullmatch(
                r'(?:"[^"]+"|[\w$#]+)(?:\s*\.\s*(?:"[^"]+"|[\w$#]+)){0,2}', value
            ):
                converted = self._datetime_text_call(
                    self._concatenated_column(
                        tables, [p.strip() for p in value.split('.')]
                    )
                    if tables
                    else None
                )
            if converted is None:
                computed = self._computed_precision(value, tables)
                if computed is not None:
                    converted = (_DATETIME_TEXT, computed)
            if converted is None or converted[0] != _DATETIME_TEXT or converted[1] < 0:
                continue
            out[name] = 'sys.ora_to_char'
            out[close] = f', {converted[1]})'
            changed = True
        return ''.join(out) if changed else sql

    def _datetime_assignments(self, sql: str) -> str:
        """`sql`, an UPDATE or INSERT, with each DATE or TIMESTAMP it assigns
        to a character column as Oracle's text of it, the session's NLS
        format: sys.ora_datetime_text(value, p), as in a concatenation
        (#2162). PostgreSQL's assignment stored its own text,
        `2024-01-02 13:14:15`. The value is a column -- the UPDATE's table's,
        or one of an INSERT's query's FROM tables -- or one whose text says
        its type; anything else is left."""
        if not re.match(r'\s*(?:UPDATE|INSERT)\b', sql, re.IGNORECASE):
            return sql
        assigned = _assigned_values(sql)
        if assigned is None or not assigned[1]:
            return sql
        (table, items) = assigned
        targets = self._relation_columns(table) if table else None
        if not targets:
            return sql
        by_name = {column.name: column for column in targets.values()}
        # Without a column list, the visible columns in their order.
        order = [
            targets[attnum].name
            for attnum in sorted(targets)
            if not targets[attnum].invisible
        ]
        sources: list[tuple[str | None, str, str | None]]
        if _NULL_UPDATE.match(sql):
            qualified = [part.strip('"').lower() for part in table.split('.')]
            sources = [
                (qualified[0] if len(qualified) == 2 else None, qualified[-1], None)
            ]
        else:
            sources = _from_tables(sql)
        out = sql
        for index, (named, start, end) in reversed(list(enumerate(items))):
            if named is not None:
                target = by_name.get(_pg_identifier(named))
            else:
                target = by_name.get(order[index]) if index < len(order) else None
            if target is None or target.type_oid not in _TEXT_OIDS:
                continue
            value = sql[start:end].strip()
            converted = _typed_datetime_value(value)
            if (
                converted is None
                and sources
                and re.fullmatch(
                    r'(?:"[^"]+"|[\w$#]+)(?:\s*\.\s*(?:"[^"]+"|[\w$#]+)){0,2}', value
                )
            ):
                parts = [part.strip() for part in value.split('.')]
                converted = self._datetime_text_call(
                    self._concatenated_column(sources, parts)
                )
            if converted is None:
                # A computed one, the whole value made text (#2162).
                computed = self._computed_precision(value, sources)
                if computed is not None:
                    converted = ('sys.ora_computed_text', computed)
            if converted is None:
                continue
            at = start + sql[start:end].index(value)
            out = (
                out[:at]
                + f'{converted[0]}({value}, {converted[1]})'
                + out[at + len(value) :]
            )
        return out

    def _concatenated_type(
        self, tables: list[tuple[str | None, str, str | None]], parts: list[str]
    ) -> int | None:
        # The declared type of the one FROM table column `parts` names (#2158).
        column = self._concatenated_column(tables, parts)
        return None if column is None else column.type_oid

    def _concatenated_column(
        self, tables: list[tuple[str | None, str, str | None]], parts: list[str]
    ) -> _TableColumn | None:
        # The one FROM table column `parts` names -- `c`, `t.c`, `s.t.c` --
        # from the schema model; None for none, or for a name more than one
        # table has (#2158).
        name = _pg_identifier(parts[-1])
        qualifier = [part.strip('"').lower() for part in parts[:-1]]
        found: list[_TableColumn] = []
        for schema, table, alias in tables:
            if len(qualifier) == 1 and qualifier[0] not in (alias, table):
                continue
            if len(qualifier) == 2 and qualifier != [schema, table]:
                continue
            if len(qualifier) > 2:
                continue
            columns = self._relation_columns(f'{schema}.{table}' if schema else table)
            found.extend(c for c in (columns or {}).values() if c.name == name)
        return found[0] if len(found) == 1 else None

    def _oson_layout(self, name: str) -> tuple[list[str], frozenset[int]] | None:
        # A relation's columns, in order, and which of them are OSON (#1706),
        # from the schema model (#1887).
        columns = self._ordered_columns(name)
        if columns is None:
            return None
        return (
            [c.name for c in columns],
            frozenset(
                i
                for i, c in enumerate(columns)
                if self._oson_oid is not None and c.type_oid == self._oson_oid
            ),
        )

    def _vector_column(
        self, pgresult, index: int, oid: int
    ) -> tuple[int | None, int | None, bool] | None:
        # A result column's VECTOR (dimensions, format, sparse), the first two
        # None where flexible, else None (#1708): a table column recorded as
        # VECTOR, else a pgvector value -- FLOAT32, its dimensions its typmod's
        # -- or a flexible-format one, dense or sparse (#1709).
        if not self._has_pgvector:
            return None
        if (
            oid
            in (
                self._vector_oid,
                self._vector_composite_oid,
                self._sparse_composite_oid,
            )
            or oid in _VECTOR_ARRAY_OIDS
            or oid == _VARBIT_OID
        ):
            declared = self._declared_column_types(pgresult, [index]).get(index)
            if declared is not None and declared[0] == 'VECTOR':
                return (declared[1], declared[2], bool(declared[3]))
        if oid == self._vector_oid:
            typmod = pgresult.fmod(index)
            return (typmod if typmod > 0 else None, 2, False)
        if oid == self._vector_composite_oid:
            return (None, None, False)
        if oid == self._sparse_composite_oid:
            return (None, None, True)
        return None

    def _aimed_binds(
        self,
        sql: str,
        layout: Callable[[str], tuple[list[str], Collection[int]] | None],
    ) -> dict[str, int]:
        """The binds an INSERT's VALUES or an UPDATE's SET puts straight into a
        column `layout` picks out: each bind's name to its column's position in
        the table, `layout(table)` naming the table's columns in order and the
        positions it cares about (#1706, #1708). Empty for any other statement."""
        (masked, _contents, targets) = self._aimed_items(sql, layout)
        return {
            _bind_name(match): column
            for (start, stop), column in targets
            if (match := _BIND_REF.fullmatch(masked[start:stop].strip())) is not None
        }

    def _aimed_items(
        self,
        sql: str,
        layout: Callable[[str], tuple[list[str], Collection[int]] | None],
    ) -> tuple[str, list[str], list[tuple[tuple[int, int], int]]]:
        # `sql` masked, the masked contents, and the span in it of each item an
        # INSERT's VALUES or an UPDATE's SET puts into a column `layout` picks
        # out, with that column's position (#1706, #1708).
        (masked, contents) = _mask_quoted(sql)
        targets: list[tuple[tuple[int, int], int]] = []
        insert = _INSERT_VALUES_HEAD.match(masked)
        update = _UPDATE_SET_HEAD.match(masked)
        if insert is not None:
            found = layout(_unmask_quoted(insert.group(1), contents))
            if found is None or not found[1]:
                return (masked, contents, [])
            (names, picked) = found
            columns = list(range(len(names)))
            if insert.group(2) is not None:
                listed = [
                    _pg_identifier(_unmask_quoted(c, contents))
                    for c in insert.group(2).split(',')
                ]
                columns = [names.index(c) if c in names else -1 for c in listed]
            open_at = insert.end() - 1
            items = _top_level_items(
                masked, open_at + 1, _matching_paren(masked, open_at)
            )
            targets = [
                (items[i], column)
                for i, column in enumerate(columns)
                if column in picked and i < len(items)
            ]
        elif update is not None:
            found = layout(_unmask_quoted(update.group(1), contents))
            if found is None or not found[1]:
                return (masked, contents, [])
            (names, picked) = found
            words, _rownums = _top_level_words(masked)
            end = next(
                (
                    pos
                    for pos, word in words
                    if pos > update.end() and word in ('WHERE', 'RETURNING')
                ),
                len(masked.rstrip().rstrip(';')),
            )
            for start, stop in _top_level_items(masked, update.end(), end):
                equals = masked.find('=', start, stop)
                column = _pg_identifier(_unmask_quoted(masked[start:equals], contents))
                if equals >= 0 and column in names and names.index(column) in picked:
                    targets.append(((equals + 1, stop), names.index(column)))
        return (masked, contents, targets)

    def _vector_text_literals(self, sql: str) -> str:
        """`sql` with each string literal an INSERT's VALUES or an UPDATE's SET
        puts into a VECTOR column made the vector it spells (#1709, #1710,
        #1742): untyped, PostgreSQL reads it in the storage's own syntax --
        a record, a bit string, a float8[] / int2[] array. A sparse or BINARY
        column's literal is typed as text, which casts to its storage; a dense
        one's is TO_VECTOR's, whose composite casts to every dense storage, a
        FLOAT64 or INT8 column's array among them."""
        if not self._has_pgvector or not self._has_column_catalog or "'" not in sql:
            return sql
        kinds: dict[int, tuple[int | None, bool]] = {}

        def layout(table: str) -> tuple[list[str], Collection[int]] | None:
            found = self._vector_formats(table)
            if found is None:
                return None
            kinds.update(found[1])
            return (found[0], frozenset(found[1]))

        (masked, contents, targets) = self._aimed_items(sql, layout)
        spans = [
            (
                start + len(masked[start:stop]) - len(masked[start:stop].lstrip()),
                start + len(masked[start:stop].rstrip()),
                kinds.get(column, (None, False)),
            )
            for (start, stop), column in targets
            if _MASKED_LITERAL.fullmatch(masked[start:stop].strip())
        ]
        if not spans:
            return sql
        names = {code: name for name, code in _VECTOR_FORMATS.items()}
        for begin, end, (code, sparse) in sorted(spans, reverse=True):
            literal = masked[begin:end]
            if sparse or code == 5:
                typed = f'{literal}::text'
            else:
                # In the column's own format: FLOAT64 read exactly (#1742).
                fmt = f"'{names[code]}'" if code in names else 'NULL'
                typed = f'sys.ora_to_vector({literal}, NULL, {fmt})'
            masked = masked[:begin] + typed + masked[end:]
        return _unmask_quoted(masked, contents)

    def _oson_binds(self, sql: str, binds: Sequence) -> Sequence:
        """`binds` with each one an INSERT's VALUES or an UPDATE's SET aims at an
        OSON column decoded from the OSON image a client sends -- plain bytes or
        a BLOB -- into the document the column holds (#1706). JSON text, and a
        JSON bind, go in as they are. Any other statement's binds are unchanged.
        """
        if not binds or not self._has_oson_columns():
            return binds
        aimed = self._aimed_binds(sql, self._oson_layout)
        if not aimed:
            return binds
        out = list(binds)
        for index, name in enumerate(_bind_names(sql)):
            if name not in aimed or index >= len(out):
                continue
            value = out[index].value if isinstance(out[index], BindVar) else out[index]
            if isinstance(value, (bytes, bytearray)) and not isinstance(value, JSON):
                out[index] = JSON(decode_oson(bytes(value)))
        return out

    def _boolean_columns(self, name: str) -> tuple[list[str], frozenset[int]] | None:
        # A relation's columns, in order, and which are BOOLEAN (#1743), from
        # the schema model (#1887).
        columns = self._ordered_columns(name)
        if columns is None:
            return None
        return (
            [c.name for c in columns],
            frozenset(i for i, c in enumerate(columns) if c.type_oid == _BOOLEAN_OID),
        )

    def _boolean_binds(self, sql: str, binds: Sequence) -> Sequence:
        """`binds` with each one an INSERT's VALUES or an UPDATE's SET puts
        into a BOOLEAN column, given as a number, made the boolean 23ai makes
        of it -- zero FALSE, any other TRUE -- and a NULL declared NUMBER an
        untyped one (#1743): PostgreSQL has no assignment from a number to a
        boolean, and a cast between built-in types needs a superuser."""
        if (
            not binds
            or self._release < (23, 0)
            or not any(_number_like(b) for b in binds)
        ):
            return binds
        aimed = self._aimed_binds(sql, self._boolean_columns)
        if not aimed:
            return binds
        out = list(binds)
        for index, name in enumerate(_bind_names(sql)):
            if name in aimed and index < len(out) and _number_like(out[index]):
                value = out[index]
                if isinstance(value, BindVar):
                    value = value.value
                out[index] = None if value is None else value != 0
        return out

    def _boolean_literals(self, sql: str) -> str:
        # `sql` with each number literal an INSERT's VALUES or an UPDATE's SET
        # puts into a BOOLEAN column made TRUE or FALSE, as 23ai reads it (#1743).
        if self._release < (23, 0) or not any(c.isdigit() for c in sql):
            return sql
        (masked, contents, targets) = self._aimed_items(sql, self._boolean_columns)
        spans = []
        for (start, stop), _column in targets:
            item = masked[start:stop]
            if _BOOLEAN_TARGET_LITERAL.fullmatch(item.strip()):
                begin = start + len(item) - len(item.lstrip())
                spans.append((begin, begin + len(item.strip()), item.strip()))
        if not spans:
            return sql
        for begin, end, literal in sorted(spans, reverse=True):
            truth = 'FALSE' if decimal.Decimal(literal) == 0 else 'TRUE'
            masked = f'{masked[:begin]}{truth}{masked[end:]}'
        return _unmask_quoted(masked, contents)

    def _vector_formats(
        self, name: str
    ) -> tuple[list[str], dict[int, tuple[int | None, bool]]] | None:
        # A relation's columns, in order, and each declared VECTOR's format
        # code, None where flexible (#1708), and whether it is sparse (#1709),
        # from the schema model (#1887).
        columns = self._ordered_columns(name)
        if columns is None:
            return None
        return (
            [c.name for c in columns],
            {
                i: (c.declared[2], c.declared[3] is not None)
                for i, c in enumerate(columns)
                if c.declared is not None and c.declared[0] == 'VECTOR'
            },
        )

    def _vector_text_binds(self, sql: str, binds: Sequence) -> Sequence:
        """`binds` with each string an INSERT's VALUES or an UPDATE's SET aims
        at a VECTOR column -- '[1, 2, 3]', as a client may write one -- as the
        vector it spells, in the column's format, FLOAT32 where the column's
        is flexible (#1708), sparse where the column is (#1709). A string goes
        to PostgreSQL untyped, so no cast reaches it there. A vector holding
        inf or NaN is refused here, as 23ai refuses one."""
        if not binds:
            return binds
        _reject_nonfinite_vectors(binds)
        if not self._has_pgvector or not self._has_column_catalog:
            return binds
        if not any(isinstance(b, str) for b in binds):
            return binds
        formats: dict[int, tuple[int | None, bool]] = {}

        def layout(table: str) -> tuple[list[str], Collection[int]] | None:
            found = self._vector_formats(table)
            if found is None:
                return None
            formats.update(found[1])
            return (found[0], frozenset(found[1]))

        aimed = self._aimed_binds(sql, layout)
        if not aimed:
            return binds
        out = list(binds)
        for index, name in enumerate(_bind_names(sql)):
            if (
                name not in aimed
                or index >= len(out)
                or not isinstance(out[index], str)
            ):
                continue
            (code, sparse) = formats.get(aimed[name], (None, False))
            if sparse:
                vector = _sparse_from_text(out[index], code)
                if vector is not None:
                    out[index] = vector
                continue
            try:
                elements = json.loads(out[index])
            except ValueError:
                continue  # left for PostgreSQL to refuse as it is
            if isinstance(elements, list):
                code = code or 2
                typecode = _VECTOR_TYPECODES.get(code, 'f')
                cast = int if typecode in ('b', 'B') else float
                out[index] = array.array(typecode, (cast(v) for v in elements))
        return out

    def _has_oson_columns(self) -> bool:
        if self._has_oson_cache is None:
            row = self._catalog_read(
                'SELECT EXISTS (SELECT 1 FROM pg_attribute WHERE atttypid = '
                'to_regtype(%s) AND attnum > 0 AND NOT attisdropped)',
                (_OSON_TYPE,),
            ).fetchone()
            self._has_oson_cache = bool(row and row[0])
        return self._has_oson_cache

    def _raw_layout(self, name: str) -> tuple[list[str], frozenset[int]] | None:
        # A relation's columns, in order, and which of them are RAW (#1496),
        # from the schema model (#1887). An object table's object id is no
        # column of the type's.
        columns = [
            c
            for c in self._ordered_columns(name) or ()
            if c.name != _OBJECT_ID_COLUMN.strip('"')
        ]
        if not columns:
            return None
        return (
            [c.name for c in columns],
            frozenset(
                i
                for i, c in enumerate(columns)
                if c.declared is not None and c.declared[0] == 'RAW'
            ),
        )

    def _raw_constructors(self) -> dict[str, frozenset[int]]:
        # The object types with a RAW attribute, by name and qualified name,
        # lower case, to the positions of their RAW attributes (#1496).
        # Read with the other schema facts (#1331).
        if self._raw_constructor_cache is None:
            self._read_schema_facts()
        assert self._raw_constructor_cache is not None
        return self._raw_constructor_cache

    def _to_raw_targets(self, sql: str) -> str:
        """Wrap each string literal or bind headed for a RAW column or attribute
        in sys.ora_to_raw, which takes a character value as hex, as Oracle
        converts one implicitly (#1496): an INSERT's VALUES, an UPDATE's SET, an
        object constructor's arguments. PostgreSQL's bytea would read the text's
        own bytes instead. A bytes value passes through unchanged."""
        if not self._has_column_catalog or not self._has_raw_targets():
            return sql
        (masked, contents) = _mask_quoted(sql)
        spans: list[tuple[int, int]] = []
        insert = _INSERT_VALUES_HEAD.match(masked)
        if insert is not None:
            layout = self._raw_layout(_unmask_quoted(insert.group(1), contents))
            if layout is not None and layout[1]:
                (names, raw) = layout
                positions: set[int] | frozenset[int] = raw
                if insert.group(2) is not None:
                    listed = [
                        _pg_identifier(_unmask_quoted(c, contents))
                        for c in insert.group(2).split(',')
                    ]
                    positions = {
                        i
                        for i, column in enumerate(listed)
                        if column in names and names.index(column) in raw
                    }
                open_at = insert.end() - 1
                items = _top_level_items(
                    masked, open_at + 1, _matching_paren(masked, open_at)
                )
                spans += [items[i] for i in positions if i < len(items)]
        update = _UPDATE_SET_HEAD.match(masked)
        if update is not None:
            layout = self._raw_layout(_unmask_quoted(update.group(1), contents))
            if layout is not None and layout[1]:
                (names, raw) = layout
                words, _rownums = _top_level_words(masked)
                end = next(
                    (
                        pos
                        for pos, word in words
                        if pos > update.end() and word in ('WHERE', 'RETURNING')
                    ),
                    len(masked.rstrip().rstrip(';')),
                )
                for start, stop in _top_level_items(masked, update.end(), end):
                    equals = masked.find('=', start, stop)
                    if equals < 0:
                        continue
                    column = _pg_identifier(
                        _unmask_quoted(masked[start:equals], contents)
                    )
                    if column in names and names.index(column) in raw:
                        spans.append((equals + 1, stop))
        spans += self._raw_comparison_spans(masked, contents)
        constructors = self._raw_constructors()
        if constructors:
            for call in _CALL_HEAD.finditer(masked):
                positions = constructors.get(call.group(1).lower(), frozenset())
                if not positions:
                    continue
                open_at = call.end() - 1
                items = _top_level_items(
                    masked, open_at + 1, _matching_paren(masked, open_at)
                )
                spans += [items[i] for i in positions if i < len(items)]
        spans = [
            (a, b) for (a, b) in set(spans) if _RAW_TARGET_VALUE.fullmatch(masked[a:b])
        ]
        if not spans:
            return sql
        for a, b in sorted(spans, reverse=True):
            masked = f'{masked[:a]} sys.ora_to_raw({masked[a:b].strip()}){masked[b:]}'
        return _unmask_quoted(masked, contents)

    def _raw_comparison_spans(self, masked: str, contents: list[str]) -> list:
        # The values a single-table statement's WHERE compares with a RAW column
        # of its table, which Oracle reads as hex too (#1496): at the clause's
        # top level, either way round, and an IN list's items. A comparison in a
        # subquery or parentheses is left alone -- its column may be another
        # table's.
        words, _rownums = _top_level_words(masked)
        where = next((p for p, w in words if w == 'WHERE'), None)
        if where is None or not words:
            return []
        head = _UPDATE_SET_HEAD.match(masked) or _DELETE_FROM_HEAD.match(masked)
        if head is None and words[0][1] == 'SELECT':
            head = _SINGLE_TABLE_FROM.search(masked, 0, where + 5)
        if head is None:
            return []
        table = _unmask_quoted(head.group(1), contents)
        alias = head.group(2) if head.re.groups >= 2 else None
        layout = self._raw_layout(table)
        if layout is None or not layout[1]:
            return []
        (names, raw) = layout
        qualifiers = {table.split('.')[-1].strip('"').lower()}
        if alias:
            qualifiers.add(alias.lower())
        end = next(
            (
                p
                for p, w in words
                if p > where and w in ('ORDER', 'GROUP', 'HAVING', 'RETURNING', 'FOR')
            ),
            len(masked.rstrip().rstrip(';')),
        )
        depth = [0] * (len(masked) + 1)
        level = 0
        for i, char in enumerate(masked):
            depth[i] = level
            level += {'(': 1, ')': -1}.get(char, 0)

        def is_raw(qualifier: str | None, column: str) -> bool:
            name = _pg_identifier(column)
            return (
                (qualifier is None or qualifier.lower() in qualifiers)
                and name in names
                and names.index(name) in raw
            )

        spans = []
        for m in _RAW_COMPARISON.finditer(masked, where, end):
            if depth[m.start()] == depth[where] and is_raw(m.group(1), m.group(2)):
                spans.append(m.span(3))
        for m in _RAW_COMPARISON_REVERSED.finditer(masked, where, end):
            if depth[m.start()] == depth[where] and is_raw(m.group(2), m.group(3)):
                spans.append(m.span(1))
        for m in _RAW_IN_LIST.finditer(masked, where, end):
            if depth[m.start()] == depth[where] and is_raw(m.group(1), m.group(2)):
                open_at = m.end() - 1
                spans += _top_level_items(
                    masked, open_at + 1, _matching_paren(masked, open_at)
                )
        return spans

    def _routine_synonyms(self) -> dict[str, tuple[str, str]]:
        # The synonyms whose names are rewritten (#2179): the session's own,
        # and PUBLIC ones where the session has no object of the name, read
        # once, then after any DDL. A read of its own, cheap while there are
        # none: the schema facts' costs more than every statement may pay.
        if self._routine_synonym_cache is None:
            if (
                self._conn.info.transaction_status
                == psycopg.pq.TransactionStatus.INERROR
            ):
                return {}
            found = self._catalog_read(_ROUTINE_SYNONYMS).fetchone()
            synonyms: dict[str, tuple[str, str]] = {}
            # The session's own last, so it wins over a PUBLIC one.
            for owner, name, target_owner, target, kind in sorted(
                (found[0] if found else None) or (),
                key=lambda entry: entry[0] != 'PUBLIC',
            ):
                synonyms[name] = (
                    kind,
                    _oracle_reference(
                        None if kind == 'PACKAGE' else target_owner, target
                    ),
                )
            self._routine_synonym_cache = synonyms
        return self._routine_synonym_cache

    def _collection_names(self) -> frozenset[str]:
        # The collection types (array domains) of the user schemas, by name and
        # by schema-qualified name, lower case; read once, then after any DDL.
        if self._collection_name_cache is None:
            self._read_schema_facts()
        assert self._collection_name_cache is not None
        return self._collection_name_cache

    def _prune_records(self) -> None:
        # After a committed DDL: drop the records of the columns and types it
        # took away -- a DROP TABLE or DROP COLUMN leaves its columns' rows
        # behind otherwise -- in one round trip (#1918). On its own, like the
        # records that follow, so a failure here cannot take the DDL with it.
        prunes = []
        if self._has_column_catalog:
            prunes += [
                'DELETE FROM sys.ora_columns o WHERE NOT EXISTS '
                '(SELECT 1 FROM pg_attribute a WHERE a.attrelid = o.relid '
                'AND a.attnum = o.attnum AND NOT a.attisdropped)',
                'DELETE FROM sys.ora_annotations o WHERE NOT EXISTS '
                '(SELECT 1 FROM pg_attribute a WHERE a.attrelid = o.relid '
                'AND a.attnum = o.attnum AND NOT a.attisdropped)',
            ]
        if self._has_collection_elements:
            prunes.append(
                'DELETE FROM sys.ora_collection_elements x WHERE NOT EXISTS '
                '(SELECT 1 FROM pg_type t WHERE t.oid = x.typid)'
            )
        # A CHECK's condition goes with its constraint (#2171), and a trigger's
        # text with its trigger (#2174).
        prunes += [
            'DELETE FROM sys.ora_check_conditions k WHERE NOT EXISTS (SELECT 1 '
            'FROM pg_constraint c WHERE c.conrelid = k.relid AND c.conname = k.conname)',
            'DELETE FROM sys.ora_triggers r WHERE NOT EXISTS (SELECT 1 FROM pg_trigger t '
            'JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace '
            'WHERE upper(n.nspname) = r.owner AND ora_name(t.tgname) = r.name)',
        ]
        # A trigger's function goes with its trigger, which its table takes
        # (#2174): the session's own, as only those it may drop.
        prunes.append(
            'DO $p$ DECLARE f regprocedure; BEGIN FOR f IN SELECT p.oid::regprocedure '
            "FROM pg_proc p WHERE p.proname LIKE 'ora$trg\\_%' "
            "AND pg_has_role(p.proowner, 'USAGE') "
            'AND NOT EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgfoid = p.oid) LOOP '
            "EXECUTE 'DROP FUNCTION ' || f; END LOOP; END $p$"
        )
        # A column grant goes with its column, and its table (#1946).
        prunes.append(
            'DELETE FROM sys.ora_col_grants g WHERE NOT EXISTS (SELECT 1 '
            'FROM pg_attribute a WHERE a.attrelid = g.relid AND a.attname = g.attname '
            'AND NOT a.attisdropped)'
        )
        if not prunes:
            return
        try:
            self._at_once('; '.join(prunes))
        except psycopg.Error:
            self._conn.rollback()

    def _record_column_types(self, statement: str) -> None:
        # After a committed DDL, its prune done (_prune_records): keep
        # sys.ora_columns in step with it (#1386). A CREATE TABLE or ALTER
        # TABLE ... ADD / MODIFY records each column it declares a type for, a
        # MODIFY to a type not recorded taking the old record away. On its own,
        # like the other DDL records, so a failure here cannot take the table
        # with it.
        if not self._has_column_catalog:
            return
        self._relations.clear()
        # The per-relation layouts too: a DDL can drop a table and create
        # another of its name with other columns (#1749).
        self._has_oson_cache = None
        declared = _declared_columns(statement)
        try:
            if declared is not None:
                table, columns = declared
                for name, detail in columns.items():
                    self._conn.execute(
                        'DELETE FROM sys.ora_columns o USING pg_attribute a '
                        'WHERE a.attrelid = o.relid AND a.attnum = o.attnum '
                        'AND a.attrelid = to_regclass(%s) AND a.attname = %s',
                        (table, name),
                    )
                    if detail is not None:
                        self._conn.execute(
                            'INSERT INTO sys.ora_columns SELECT attrelid, attnum, '
                            '%s, %s, %s, %s FROM pg_attribute WHERE attrelid = '
                            'to_regclass(%s) AND attname = %s AND attnum > 0',
                            (*detail, table, name),
                        )
            view = _CREATE_VIEW_NAME.match(statement)
            if view is not None:
                self._record_view_column_types(view.group(1))
            self._record_collection_element(statement)
            self._conn.commit()
        except psycopg.Error:
            self._conn.rollback()

    def _record_collection_element(self, statement: str) -> None:
        # A collection of NVARCHAR2 / NCHAR keeps its element's national type
        # (#1437), one of RAW(n) its n (#1545); _prune_records drops the rows
        # of types that are gone.
        if not self._has_collection_elements:
            return
        recorded = _CREATE_RECORDED_COLLECTION.match(statement)
        if recorded is not None:
            (name, data_type, length) = recorded.groups()
            self._conn.execute(
                'INSERT INTO sys.ora_collection_elements (typid, data_type, data_length) '
                'SELECT to_regtype(%s)::oid, %s, %s WHERE to_regtype(%s) IS NOT NULL '
                'ON CONFLICT (typid) DO UPDATE SET data_type = excluded.data_type, '
                'data_length = excluded.data_length',
                (name, data_type.upper(), int(length) if length else None, name),
            )

    def _recorded_element(self, pg_oid: int) -> tuple[str, int | None] | None:
        # The type a collection's elements were declared as, where it was
        # recorded -- (type, length) -- or None (#1437, #1545).
        if not self._has_collection_elements:
            return None
        row = self._conn.execute(
            'SELECT data_type, data_length FROM sys.ora_collection_elements '
            'WHERE typid = %s',
            (pg_oid,),
        ).fetchone()
        return (row[0], row[1]) if row else None

    def _created_trigger(self, sql: str) -> str:
        # A CREATE TRIGGER translated (_translate_trigger), ORA-04081 for one
        # of a trigger there is when it does not say OR REPLACE (#2174).
        m = _CREATE_TRIGGER.match(sql)
        if m is None:
            return sql
        if not m.group(1) and self._trigger_table(m.group(2)) is not None:
            raise BackendError(
                f"trigger '{_oracle_name(m.group(2).rpartition('.')[2])}' already exists",
                ora_code=_ORA_TRIGGER_EXISTS,
            )
        return _translate_trigger(sql, self._routine_kind)

    def _altered_trigger(self, sql: str) -> str:
        # ALTER TRIGGER ENABLE / DISABLE as PostgreSQL's, which names the
        # trigger's table, and COMPILE as nothing, as a trigger here is never
        # INVALID; ALTER TABLE ... ALL TRIGGERS as its user triggers, a
        # foreign key's own being PostgreSQL's (#2174). ORA-04080 for no such
        # trigger; any other statement unchanged.
        every = _ALTER_ALL_TRIGGERS.match(sql)
        if every is not None:
            # Its PL/SQL triggers by name: PostgreSQL's TRIGGER USER would meet
            # the USER pseudo-column's rewrite.
            names = self._conn.execute(
                'SELECT t.tgname FROM pg_trigger t JOIN pg_proc f ON f.oid = t.tgfoid '
                'WHERE NOT t.tgisinternal AND f.proname LIKE %s '
                'AND t.tgrelid = sys.ora_regclass(%s) ORDER BY t.tgname',
                (f'{_TRIGGER_FUNCTION_PREFIX}%', every.group(1)),
            ).fetchall()
            if not names:
                return _NO_OP
            return '; '.join(
                f'ALTER TABLE {every.group(1)} {every.group(2).upper()} TRIGGER '
                f'{_quoted_identifier(tgname)}'
                for (tgname,) in names
            )
        altered = _ALTER_TRIGGER.match(sql)
        if altered is None:
            return sql
        (name, action) = (altered.group(1), altered.group(2).upper())
        table = self._trigger_table(name)
        if table is None:
            self._conn.rollback()
            raise BackendError(
                f"trigger '{_oracle_name(name.rpartition('.')[2])}' does not exist",
                ora_code=_ORA_NO_SUCH_TRIGGER,
            )
        if action == 'COMPILE':
            return _NO_OP
        return f'ALTER TABLE {table} {action} TRIGGER {name.rpartition(".")[2]}'

    def _record_trigger(self, statement: str) -> None:
        # After a committed CREATE TRIGGER: keep what it was written as for
        # ALL_TRIGGERS (#2174) -- its DESCRIPTION, from its name to its WHEN
        # or block, its REFERENCING names, WHEN condition and block. On its
        # own, like the other records, so a failure here cannot take the
        # trigger with it.
        m = _CREATE_TRIGGER.match(statement)
        if m is None:
            return
        name = m.group(2)
        end = m.start(9)
        if m.group(8) is not None:
            end = statement.lower().rfind('when', m.start(2), m.start(8))
        aliases = dict(
            (kind.upper(), alias.upper())
            for kind, alias in _REFERENCING_NAME.findall(m.group(6) or '')
        )
        referencing = (
            f'REFERENCING NEW AS {aliases.get("NEW", "NEW")} '
            f'OLD AS {aliases.get("OLD", "OLD")}'
        )
        (schema, _dot, trigger) = name.rpartition('.')
        try:
            self._conn.execute(
                'INSERT INTO sys.ora_triggers (owner, name, description, referencing, '
                'when_clause, body) VALUES (coalesce(%s, upper(current_schema())), '
                '%s, %s, %s, %s, %s) ON CONFLICT (owner, name) DO UPDATE SET '
                'description = EXCLUDED.description, referencing = EXCLUDED.referencing, '
                'when_clause = EXCLUDED.when_clause, body = EXCLUDED.body',
                (
                    _oracle_name(schema) if schema else None,
                    _oracle_name(trigger),
                    statement[m.start(2) : end],
                    referencing,
                    m.group(8),
                    statement[m.start(9) :].strip(),
                ),
            )
            self._conn.commit()
        except psycopg.Error:
            self._conn.rollback()

    def _trigger_table(self, name: str) -> str | None:
        # The table a PL/SQL trigger of this name is on, in its schema or the
        # session's (#2174), or None for no such trigger.
        (schema, _dot, trigger) = name.rpartition('.')
        row = self._conn.execute(
            'SELECT t.tgrelid::regclass::text FROM pg_trigger t '
            'JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_proc f ON f.oid = t.tgfoid '
            'WHERE NOT t.tgisinternal AND t.tgname = %s AND f.proname LIKE %s '
            'AND c.relnamespace = coalesce(to_regnamespace(%s), '
            'current_schema()::regnamespace)',
            (
                _pg_identifier(trigger),
                f'{_TRIGGER_FUNCTION_PREFIX}%',
                _pg_identifier(schema) if schema else None,
            ),
        ).fetchone()
        return None if row is None else row[0]

    def _dropped_trigger(self, sql: str) -> str:
        # DROP TRIGGER name as PostgreSQL's, which names the trigger's table, and
        # its trigger function with it (#2174); ORA-04080 for no such trigger.
        # Any other statement unchanged.
        dropped = _DROP_TRIGGER.match(sql)
        if dropped is None:
            return sql
        name = dropped.group(1)
        trigger = name.rpartition('.')[2]
        table = self._trigger_table(name)
        if table is None:
            self._conn.rollback()
            raise BackendError(
                f"trigger '{_oracle_name(trigger)}' does not exist",
                ora_code=_ORA_NO_SUCH_TRIGGER,
            )
        return (
            f'DROP TRIGGER {trigger} ON {table}; '
            f'DROP FUNCTION IF EXISTS {_trigger_function_name(name)}()'
        )

    def _dropped_invalid_view(self, statement: str) -> Result | None:
        # DROP VIEW of a view a DROP left INVALID (#2201): there is no view to
        # drop, only its record, which goes as Oracle drops an invalid view.
        # None for any other statement, or a view that is there.
        dropped = _DROP_VIEW.match(statement)
        if dropped is None:
            return None
        row = self._conn.execute(
            'SELECT sys.ora_regclass(%s) IS NULL', (dropped.group(1),)
        ).fetchone()
        if row is None or not row[0]:
            return None
        parts = dropped.group(1).lower().split('.')
        deleted = self._conn.execute(
            'DELETE FROM sys.ora_invalid_views WHERE schema_name = '
            'coalesce(%s, current_schema()) AND view_name = %s',
            (parts[0] if len(parts) == 2 else None, parts[-1]),
        ).rowcount
        if not deleted:
            self._conn.rollback()
            return None
        self.commit()
        return Result()

    def _revalidate_views(self) -> None:
        """After a committed DDL, in one round trip while nothing needs doing:
        each synonym's view as its target now is (#2179), and each view a DROP
        left INVALID made again where it compiles (#2201). On its own, like the
        other records, so a failure here cannot take the DDL with it.

        A synonym's view is made from its record where its target is back or
        came to be, and made again where the target's columns are no longer
        the view's, as a column ALTER TABLE adds shows through a synonym; it is
        never one of the INVALID views. An INVALID view that compiles is VALID
        again, its record gone, and one a CREATE took the name of goes too --
        again until none more compiles, for a view over another."""
        try:
            found = self._conn.execute(_PENDING_VIEWS).fetchall()
            self._conn.commit()
        except psycopg.Error:
            self._conn.rollback()
            return
        for kind, owner, name, target_owner, target, exists in found:
            if kind != 'synonym':
                continue
            view = f'{_quoted_identifier(owner)}.{_quoted_identifier(name)}'
            source = f'{_quoted_identifier(target_owner)}.{_quoted_identifier(target)}'
            try:
                if exists:
                    self._conn.execute(f'DROP VIEW {view}')
                self._conn.execute(f'CREATE VIEW {view} AS SELECT * FROM {source}')
                self._record_view_column_types(view)
                self._conn.commit()
            except psycopg.Error:
                self._conn.rollback()
        pending = [
            (schema, name, definition, taken)
            for kind, schema, name, definition, _target, taken in found
            if kind == 'view'
        ]
        made = True
        while pending and made:
            made = False
            for entry in list(pending):
                (schema, name, definition, taken) = entry
                qualified = f'{_quoted_identifier(schema)}.{_quoted_identifier(name)}'
                try:
                    if not taken:
                        self._conn.execute(
                            f'CREATE VIEW {qualified} AS {definition.strip().rstrip(";")}'
                        )
                    self._conn.execute(
                        'DELETE FROM sys.ora_invalid_views '
                        'WHERE schema_name = %s AND view_name = %s',
                        (schema, name),
                    )
                    if not taken:
                        self._record_view_column_types(qualified)
                    self._conn.commit()
                except psycopg.Error:
                    self._conn.rollback()
                    continue
                pending.remove(entry)
                made = True

    def _record_view_column_types(self, name: str) -> None:
        # A view's columns take the records of the columns they come from
        # (#1425). A column read through a view traces to the view, not to its
        # table, so the view's own definition is run instead, empty, and each of
        # its columns traced through libpq ftable / ftablecol. A view over a
        # view copies from the inner view's rows.
        row = self._conn.execute(
            'SELECT c.oid, pg_get_viewdef(c.oid) FROM pg_class c '
            "WHERE c.oid = to_regclass(%s) AND c.relkind = 'v'",
            (name,),
        ).fetchone()
        if row is None:
            return
        relid, definition = row
        self._conn.execute('DELETE FROM sys.ora_columns WHERE relid = %s', (relid,))
        pgresult = self._conn.execute(
            f'SELECT * FROM ({definition.strip().rstrip(";")}) q LIMIT 0'
        ).pgresult
        if pgresult is None:
            return
        for index in range(pgresult.nfields):
            source = pgresult.ftable(index)
            if source:
                self._conn.execute(
                    'INSERT INTO sys.ora_columns SELECT %s, %s, data_type, '
                    'data_length, data_precision, data_scale FROM sys.ora_columns '
                    'WHERE relid = %s AND attnum = %s',
                    (relid, index + 1, source, pgresult.ftablecol(index)),
                )

    def _declared_column_types(self, pgresult, indexes: list[int]) -> dict[int, tuple]:
        # The declared type recorded for each result column at `indexes` that
        # comes straight from a table column (#1386).
        return {
            index: column.declared
            for index, column in self._table_columns(pgresult, indexes).items()
            if column.declared is not None
        }

    def _record_annotations(
        self, annotated: tuple[str, dict[str, list[tuple[str, str]]]] | None
    ) -> None:
        # After a committed DDL: a column's annotations (#1711). A column that
        # declares annotations has them replaced; _prune_records drops the
        # rows of columns that are gone.
        if not self._has_column_catalog:
            return
        self._sql_domain_cache.clear()
        self._has_sql_domains_cache = None
        try:
            if annotated is not None:
                (table, columns) = annotated
                for column, notes in columns.items():
                    self._conn.execute(
                        'DELETE FROM sys.ora_annotations o USING pg_attribute a '
                        'WHERE a.attrelid = o.relid AND a.attnum = o.attnum '
                        'AND a.attrelid = to_regclass(%s) AND a.attname = %s',
                        (table, column),
                    )
                    for position, (label, value) in enumerate(notes):
                        self._conn.execute(
                            'INSERT INTO sys.ora_annotations SELECT attrelid, attnum, '
                            '%s, %s, %s FROM pg_attribute WHERE attrelid = '
                            'to_regclass(%s) AND attname = %s AND attnum > 0',
                            (position, label, value, table, column),
                        )
            self._conn.commit()
        except psycopg.Error:
            self._conn.rollback()

    def _has_sql_domains(self) -> bool:
        # Whether any column could owe a describe a domain or annotations
        # (#1711): a user's SQL domain, or an annotation, exists. Kept until a
        # DDL, so a database with neither pays one query a session.
        if self._has_sql_domains_cache is None:
            self._read_schema_facts()
        return bool(self._has_sql_domains_cache)

    def _sql_domain_columns(
        self, pgresult, count: int
    ) -> dict[int, tuple[bytes, bytes, tuple[tuple[bytes, bytes], ...]]]:
        # Each result column that comes straight from a table column with a
        # SQL domain or annotations (#1711): the domain's owner and name, as
        # the dictionary views spell them -- one in the session's own schema
        # owned by the user logged in, as Oracle names it (#1744) -- and the
        # annotations, traced through libpq ftable / ftablecol, as a domain
        # column describes as its base type.
        keys = {}
        for index in range(count):
            relid = pgresult.ftable(index)
            if relid:
                keys[index] = (relid, pgresult.ftablecol(index))
        unknown = [k for k in set(keys.values()) if k not in self._sql_domain_cache]
        login = getattr(self, '_login_user', None)
        for relid, attnum in unknown:
            row = self._catalog_read(
                'SELECT CASE WHEN obj_description(t.oid, %s) = %s THEN '
                'sys.ora_owner(n.nspname) END, CASE WHEN obj_description(t.oid, %s) = %s '
                'THEN sys.ora_name(t.typname) END, ARRAY(SELECT ARRAY[o.name, o.value] '
                'FROM sys.ora_annotations o WHERE o.relid = a.attrelid AND '
                'o.attnum = a.attnum ORDER BY o.position), '
                'n.nspname = current_schema() FROM pg_attribute a '
                'JOIN pg_type t ON t.oid = a.atttypid JOIN pg_namespace n ON '
                'n.oid = t.typnamespace WHERE a.attrelid = %s AND a.attnum = %s',
                (
                    'pg_type',
                    _SQL_DOMAIN_MARK,
                    'pg_type',
                    _SQL_DOMAIN_MARK,
                    relid,
                    attnum,
                ),
            ).fetchone()
            self._sql_domain_cache[(relid, attnum)] = (
                None
                if row is None or (row[1] is None and not row[2])
                else (
                    ((login if row[3] and login else row[0]) or '').encode(),
                    (row[1] or '').encode(),
                    tuple((k.encode(), v.encode()) for k, v in row[2]),
                )
            )
        return {
            index: found
            for index, key in keys.items()
            if (found := self._sql_domain_cache.get(key)) is not None
        }

    def _record_visibility(self, visibility: tuple | None) -> None:
        # Keep what a DDL said about its columns' visibility (#1195): add the
        # invisible ones, drop the ones made visible, and prune the rows of
        # dropped tables. Any DDL may change which columns a table has, so the
        # cache of visible columns starts over either way.
        self._any_invisible = None
        self._relations.clear()
        if visibility is None or not self._has_invisible_catalog:
            return
        (table, hidden, shown, _only) = visibility
        try:
            self._conn.execute(
                'DELETE FROM sys.ora_invisible_columns i WHERE NOT EXISTS '
                '(SELECT 1 FROM pg_attribute a WHERE a.attrelid = i.relid '
                'AND a.attnum = i.attnum AND NOT a.attisdropped)'
            )
            if hidden:
                self._conn.execute(
                    'INSERT INTO sys.ora_invisible_columns SELECT attrelid, attnum '
                    'FROM pg_attribute WHERE attrelid = to_regclass(%s) '
                    'AND attname = ANY(%s) AND attnum > 0 ON CONFLICT DO NOTHING',
                    (table, hidden),
                )
            if shown:
                self._conn.execute(
                    'DELETE FROM sys.ora_invisible_columns i USING pg_attribute a '
                    'WHERE a.attrelid = i.relid AND a.attnum = i.attnum '
                    'AND a.attrelid = to_regclass(%s) AND a.attname = ANY(%s)',
                    (table, shown),
                )
            self._conn.commit()
        except psycopg.Error:
            self._conn.rollback()

    def _visible_columns(self, table: str) -> list[str] | None:
        # The visible columns of `table`, quoted, in order -- or None when it has
        # no INVISIBLE column, or is not a table (#1195) -- from the schema
        # model (#1887).
        if not self._has_invisible_catalog:
            return None
        if self._any_invisible is None:
            row = self._catalog_read(
                'SELECT EXISTS (SELECT 1 FROM sys.ora_invisible_columns)'
            ).fetchone()
            self._any_invisible = bool(row and row[0])
        if not self._any_invisible:
            return None
        columns = self._ordered_columns(table)
        if columns is None or not any(c.invisible for c in columns):
            return None
        return [
            '"' + c.name.replace('"', '""') + '"' for c in columns if not c.invisible
        ]

    def _expand_visible_columns(self, sql: str) -> str:
        # Name the visible columns where a statement means "all of them": an
        # INSERT with no column list, and a select list that is only `*` or
        # `alias.*` over one table. A join, a subquery or a view over a table
        # with an INVISIBLE column is not expanded (#1195).
        insert = _INSERT_NO_COLUMNS.match(sql)
        if insert is not None:
            columns = self._visible_columns(insert.group(2))
            if columns:
                at = insert.end()
                return f'{sql[:at].rstrip()} ({", ".join(columns)}) {sql[at:]}'
            return sql
        star = _SELECT_STAR.match(sql)
        if star is not None and '*' in star.group(2):
            select_list = star.group(2)
            if _NESTED_QUERY.search(select_list):
                return sql
            (table, alias) = (star.group(4), star.group(5))
            columns = self._visible_columns(table)
            if not columns:
                return sql
            names = {
                table.lower(),
                (alias or '').lower(),
                table.rsplit('.', 1)[-1].lower(),
            }
            items = []
            for start, end in _top_level_items(select_list, 0, len(select_list)):
                item = select_list[start:end].strip()
                if item == '*':
                    items.append(', '.join(columns))
                elif item.endswith('.*') and item[:-2].lower() in names:
                    items.append(', '.join(f'{item[:-2]}.{c}' for c in columns))
                else:
                    items.append(item)
            return (
                f'{star.group(1)}{", ".join(items)}{star.group(3)}'
                + sql[star.start(4) :]
            )
        return sql

    def _named_constraints(self, sql: str) -> str:
        # `sql` with each constraint it declares without a name named as
        # Oracle names it, SYS_C and seven digits from one counter (#2141), so
        # PostgreSQL's constraint and index carry it: the dictionary lists it,
        # ORA-00001 names it.
        starts = _unnamed_constraints(sql)
        if not starts:
            return sql
        numbers = self._conn.execute(
            "SELECT nextval('sys.ora_constraint_names') FROM generate_series(1, %s)",
            (len(starts),),
        ).fetchall()
        for at, (number,) in zip(reversed(starts), reversed(numbers)):
            sql = f'{sql[:at]}CONSTRAINT SYS_C{number:07d} {sql[at:]}'
        return sql

    def _record_check_conditions(
        self, checks: tuple[str, list[tuple[str, str]]] | None
    ) -> None:
        # After a committed CREATE TABLE or ALTER TABLE: keep each CHECK's
        # condition as written (#2171), in place of what a constraint of its
        # name had. On its own, so a failure here cannot take the table with it.
        if checks is None:
            return
        (table, found) = checks
        try:
            for name, condition in found:
                self._conn.execute(
                    'INSERT INTO sys.ora_check_conditions (relid, conname, condition) '
                    'SELECT c.conrelid, c.conname, %s FROM pg_constraint c '
                    'WHERE c.conrelid = to_regclass(%s) AND c.conname = %s '
                    'ON CONFLICT (relid, conname) DO UPDATE '
                    'SET condition = EXCLUDED.condition',
                    (condition, table, name),
                )
            self._conn.commit()
        except psycopg.Error:
            self._conn.rollback()

    def _record_source(self, statement: str) -> None:
        # After a committed CREATE of a stored unit, valid or created with
        # compilation errors: keep its source for ALL_SOURCE (#2172), in place
        # of what it had. Done after the commit and on its own, so a failure
        # here cannot take the unit with it; a dropped unit's rows go too.
        unit = _stored_unit(statement)
        if unit is None:
            return
        (owner, name, kind, source) = unit
        owner_sql = '%s' if owner else 'sys.ora_owner(current_schema())'
        params: list = [owner] if owner else []
        try:
            self._conn.execute(
                'DELETE FROM sys.ora_source s WHERE NOT EXISTS (SELECT 1 FROM '
                'all_objects o WHERE o.owner = s.owner AND o.object_name = s.name '
                'AND o.object_type = s.type)'
            )
            self._conn.execute(
                'INSERT INTO sys.ora_source (owner, name, type, text) '
                f'VALUES ({owner_sql}, %s, %s, %s) ON CONFLICT (owner, name, type) '
                'DO UPDATE SET text = EXCLUDED.text',
                (*params, name, kind, source),
            )
            self._conn.commit()
        except psycopg.Error:
            self._conn.rollback()

    def _record_quoted_names(self, statement: str) -> None:
        # After a committed CREATE TABLE: note which of its columns were created
        # with a quoted all-lower-case name (#1204). Done after the commit and on
        # its own, so a failure here cannot take the table with it. A statement
        # without such a name costs nothing. A column added later by ALTER TABLE
        # ... ADD is not recorded, and reports its name by the folding rule.
        table = _CREATE_TABLE_NAME.match(statement)
        if table is None or not self._has_quoted_names:
            return
        names = [
            name
            for name in _QUOTED_LOWER_NAME.findall(statement)
            if name.upper() not in _ORACLE_RESERVED_WORDS
        ]
        if not names:
            return
        try:
            self._conn.execute(
                'DELETE FROM sys.ora_quoted_names q WHERE NOT EXISTS '
                '(SELECT 1 FROM pg_class c WHERE c.oid = q.relid)'
            )
            self._conn.execute(
                'INSERT INTO sys.ora_quoted_names SELECT attrelid, attnum '
                'FROM pg_attribute WHERE attrelid = to_regclass(%s) '
                'AND attname = ANY(%s) AND attnum > 0 ON CONFLICT DO NOTHING',
                (table.group(1), names),
            )
            self._conn.commit()
        except psycopg.Error:
            self._conn.rollback()

    def _record_tstz_precisions(self, statement: str) -> None:
        # After a committed CREATE TABLE: note the precision of each column it
        # declares TIMESTAMP(n) WITH TIME ZONE (#1308), and of each attribute a
        # CREATE TYPE ... AS OBJECT does, by the composite's relation (#1550).
        # On its own, like the quoted names, so a failure here cannot take the
        # table with it; a column added later by ALTER TABLE ... ADD keeps the
        # default.
        table = _CREATE_TABLE_NAME.match(statement) or _CREATE_OBJECT_TYPE_NAME.match(
            statement
        )
        if table is None or not self._has_tstz_precision:
            return
        declared = {
            (name[1:-1] if name.startswith('"') else name.lower()): int(prec)
            for name, prec in _TSTZ_PRECISION_COLUMN.findall(statement)
        }
        if not declared:
            return
        try:
            self._conn.execute(
                'DELETE FROM sys.ora_tstz_precision p WHERE NOT EXISTS '
                '(SELECT 1 FROM pg_class c WHERE c.oid = p.relid)'
            )
            for name, prec in declared.items():
                self._conn.execute(
                    'INSERT INTO sys.ora_tstz_precision SELECT attrelid, attnum, %s '
                    'FROM pg_attribute WHERE attrelid = to_regclass(%s) '
                    'AND attname = %s AND attnum > 0 '
                    'ON CONFLICT (relid, attnum) DO UPDATE SET prec = EXCLUDED.prec',
                    (prec, table.group(1), name),
                )
            self._conn.commit()
        except psycopg.Error:
            self._conn.rollback()

    def _tstz_precisions(self, pgresult, indexes: list[int]) -> dict[int, int]:
        # The recorded precision of each WITH TIME ZONE result column at
        # `indexes` that comes straight from a table column (#1308).
        return {
            index: column.tstz_precision
            for index, column in self._table_columns(pgresult, indexes).items()
            if column.tstz_precision is not None
        }

    def _quoted_lower_columns(self, pgresult, indexes: list[int]) -> set[int]:
        # Which of the result columns at `indexes` -- each one whose name the
        # folding rule would upper-case -- were created with a quoted
        # all-lower-case name, so Oracle reports them as written (#1204); a
        # computed column has no table and keeps the rule.
        columns = self._table_columns(pgresult, indexes)
        return {index for index, column in columns.items() if column.quoted}

    def _not_null_columns(self, pgresult, count: int) -> set[int]:
        # Which result columns come straight from a NOT NULL table column, which
        # Oracle describes as not nullable (#1307); a computed column has no
        # table and stays nullable, as in Oracle.
        columns = self._table_columns(pgresult, range(count))
        return {index for index, column in columns.items() if column.not_null}

    def _json_columns(self, pgresult, count: int) -> set[int]:
        # Which result columns come straight from a table column with an IS
        # JSON check constraint (#1626), which Oracle describes as JSON, so a
        # client hands back the parsed value.
        columns = self._table_columns(pgresult, range(count))
        return {index for index, column in columns.items() if column.json}

    def _table_columns(
        self, pgresult, indexes: Iterable[int]
    ) -> dict[int, _TableColumn]:
        # The table column each result column at `indexes` comes straight from,
        # traced through libpq ftable / ftablecol, from the schema model
        # (#1887). The relations not yet read are read together, in one query;
        # a computed column, or one of a relation gone since, has none.
        keys = {}
        for index in indexes:
            relid = pgresult.ftable(index)
            if relid:
                keys[index] = (relid, pgresult.ftablecol(index))
        unknown = {relid for relid, _attnum in keys.values()} - self._relations.keys()
        if unknown:
            self._read_relations(unknown)
        return {
            index: column
            for index, (relid, attnum) in keys.items()
            if (column := self._relations[relid].get(attnum)) is not None
        }

    def _read_relations(self, relids: set[int]) -> None:
        # Read these relations' columns into the schema model (#1887): each
        # column's type, whether it is NOT NULL (#1307), created with a quoted
        # all-lower-case name (#1204) or checked IS JSON (#1626) -- stored as
        # sys.ora_is_json(column) (#1614), one with NOT before it being no such
        # column -- its declared Oracle type (#1386) and its WITH TIME ZONE
        # precision (#1308), and whether it is INVISIBLE (#1195). A catalog
        # this session's dictionary lacks leaves its part empty.
        quoted, declared, precision, invisible, joins = (
            'false',
            'NULL, NULL, NULL, NULL',
            'NULL',
            'false',
            '',
        )
        if self._has_quoted_names:
            quoted = (
                'EXISTS (SELECT 1 FROM sys.ora_quoted_names q '
                'WHERE q.relid = a.attrelid AND q.attnum = a.attnum)'
            )
        if self._has_column_catalog:
            declared = 'o.data_type, o.data_length, o.data_precision, o.data_scale'
            joins += (
                ' LEFT JOIN sys.ora_columns o '
                'ON o.relid = a.attrelid AND o.attnum = a.attnum'
            )
        if self._has_tstz_precision:
            precision = 'p.prec'
            joins += (
                ' LEFT JOIN sys.ora_tstz_precision p '
                'ON p.relid = a.attrelid AND p.attnum = a.attnum'
            )
        if self._has_invisible_catalog:
            invisible = (
                'EXISTS (SELECT 1 FROM sys.ora_invisible_columns h '
                'WHERE h.relid = a.attrelid AND h.attnum = a.attnum)'
            )
        found = self._catalog_read(
            'SELECT a.attrelid, a.attnum, a.attname, a.atttypid, a.attnotnull, '
            f'{quoted}, EXISTS (SELECT 1 FROM pg_constraint c '
            "WHERE c.contype = 'c' AND c.conrelid = a.attrelid "
            'AND c.conkey = ARRAY[a.attnum] '
            "AND pg_get_constraintdef(c.oid) ~ '^CHECK \\(+(sys\\.)?ora_is_json\\('), "
            f'{declared}, {precision}, {invisible}, a.atttypmod, '
            "(SELECT r.relkind = 'v' FROM pg_class r WHERE r.oid = a.attrelid) "
            f'FROM pg_attribute a{joins} '
            'WHERE a.attrelid = ANY(%s) AND a.attnum > 0 AND NOT a.attisdropped',
            (list(relids),),
        ).fetchall()
        for relid in relids:
            self._relations[relid] = {}
        self._view_relids -= relids
        for row in found:
            if row[14]:
                self._view_relids.add(row[0])
            declared_type = None if row[7] is None else tuple(row[7:11])
            self._relations[row[0]][row[1]] = _TableColumn(
                name=row[2],
                type_oid=row[3],
                not_null=row[4],
                quoted=row[5],
                json=row[6],
                declared=declared_type,
                tstz_precision=row[11],
                invisible=row[12],
                typmod=row[13],
            )

    def _relation_columns(self, name: str) -> dict[int, _TableColumn] | None:
        # The schema model's columns of the relation a statement names, as
        # PostgreSQL resolves `name` (#1889); None for no relation.
        if name not in self._relids:
            row = self._catalog_read('SELECT sys.ora_regclass(%s)', (name,)).fetchone()
            self._relids[name] = None if row is None or row[0] is None else row[0]
        relid = self._relids[name]
        if relid is None:
            return None
        if relid not in self._relations:
            self._read_relations({relid})
        return self._relations[relid]

    def _ordered_columns(self, name: str) -> list[_TableColumn] | None:
        # The schema model's columns of the relation `name`, in order (#1887);
        # None for no relation.
        columns = self._relation_columns(name)
        if not columns:
            return None
        return [columns[attnum] for attnum in sorted(columns)]

    def _instant_index_keys(self, sql: str) -> str:
        # `sql`, a CREATE INDEX, with each key that is a WITH TIME ZONE column
        # made its instant, `((col).utc)` (#1897). The Mirror compares such a
        # column by its instant, and PostgreSQL inlines that comparison to
        # `(col).utc`, which an index on the composite can't serve. Oracle
        # builds the index on SYS_EXTRACT_UTC(col) as well, and a UNIQUE one
        # refuses two values at one instant.
        if self._tstz_oid is None:
            return sql
        found = _index_key_spans(sql)
        if found is None or not found[3]:
            return sql
        (masked, contents, table, keys) = found
        columns = self._relation_columns(table)
        if not columns:
            return sql
        instants = {
            column.name
            for column in columns.values()
            if column.type_oid == self._tstz_oid
        }
        for start, stop, name in reversed(keys):
            if name in instants:
                masked = f'{masked[:start]}(({masked[start:stop]}).utc){masked[stop:]}'
        return _unmask_quoted(masked, list(contents))

    def _without_dead_nvl(self, sql: str) -> str:
        # `sql` with each NVL / COALESCE in its WHERE clause whose first
        # argument is a NOT NULL column of its one table cut to the column
        # (#1889): the call always answers the column there, and PostgreSQL
        # can use the column's index for the bare column only. Oracle's own
        # optimizer drops these calls too. Only a single-table statement, where
        # every column is that table's and no outer join can make one NULL.
        found = _dead_nvl_candidates(sql)
        if found is None:
            return sql
        (masked, contents, table, qualifiers, calls) = found
        columns = self._relation_columns(table)
        if not columns:
            return sql
        not_null = {
            column.name
            for column in columns.values()
            if column.not_null and column.type_oid in _NVL_DROPPABLE_OIDS
        }
        out = masked
        for start, end, column, qualifier, name in reversed(calls):
            if name in not_null and (qualifier is None or qualifier in qualifiers):
                out = out[:start] + column + out[end:]
        return sql if out == masked else _unmask_quoted(out, list(contents))

    def _build_result(
        self, cursor, sql: str = '', original: str = '', params: dict | None = None
    ) -> Result:
        # Turn an executed statement's cursor into a Result: a row count for a
        # no-row statement, else the fetched rows plus a ColumnMeta per column.
        # `sql` is the statement as run, read for the select-list items whose
        # type only the item says (a LOB call, an IntervalYM bind); `params`
        # its binds, whose declared sizes an expression over them describes by.
        if cursor.description is None:
            return Result(rowcount=max(cursor.rowcount, 0))
        computed = _computed_column_types(sql) if sql else {}
        constructors = _constructor_items(sql) if sql else {}
        rows = [list(r) for r in cursor.fetchall()]
        # Re-tag the zoned cells before they reach the wire encoder (_wire_cell).
        for i, desc in enumerate(cursor.description):
            if desc.type_code in (self._tstz_oid, _TIMESTAMPTZ_OID):
                for row in rows:
                    row[i] = _wire_cell(row[i], desc.type_code, self._tstz_oid)
        self._learn_types({desc.type_code for desc in cursor.description})
        typed: tuple[dict[str, tuple[str, int]], list[str]] | None = None

        def item_text(i: int) -> str:
            nonlocal typed
            if typed is None:
                typed = (self._operand_types(original), _select_list_items(original))
            return typed[1][i] if i < len(typed[1]) else ''

        def operand_types(i: int) -> list[str]:
            # The Oracle types of select-list item i's column operands, read
            # once per result and only when an item needs them (#2152, #2160).
            text = item_text(i)
            assert typed is not None
            types = typed[0]
            return [
                types[name][0] if name in types else _PSEUDO_COLUMN_TYPE[name]
                for name in _column_operands(text)
                if name in types or name in _PSEUDO_COLUMN_TYPE
            ]

        timestamp_scales: dict[int, int] = {}
        columns = []
        for i, desc in enumerate(cursor.description):
            # A column tracing back to a typed domain is that Oracle type — an
            # ora_clob / ora_blob LOB (so an empty value stays '' / b'' rather than
            # collapsing to NULL, #534), or an ora_intervalym INTERVAL YEAR TO MONTH
            # (so its months survive, #504), or an ora_date DATE (#1316). Only a
            # text / bytea / interval / timestamp column can be one, so cheaper
            # types skip the catalog lookup.
            domain = (
                self._domain_type(cursor.pgresult, i)
                if desc.type_code in _DOMAIN_BASE_OIDS
                else None
            )
            if domain is None and desc.type_code in (25, 17, _INTERVAL_OID):
                domain = computed.get(i)
            if (
                domain is None
                and desc.type_code == _INTERVAL_OID
                and original
                and not cursor.pgresult.ftable(i)
            ):
                # A computed interval over a YEAR TO MONTH column -- `iym + iym`,
                # SUM(iym) -- reports the domain's base type. Oracle mixes no
                # DAY TO SECOND into one, so a YEAR TO MONTH operand makes the
                # item YEAR TO MONTH (#2152).
                if any(t.startswith('INTERVAL YEAR') for t in operand_types(i)):
                    domain = TNS_TYPE_INTERVALYM
            if (
                domain is None
                and desc.type_code == _TIMESTAMP_OID
                and desc.precision != 0
                and original
                and not cursor.pgresult.ftable(i)
            ):
                # A computed timestamp over a DATE or a TIMESTAMP -- `d + iym`,
                # `ts - ids`, MAX(d) -- reports timestamp, unsized (#2160). On
                # 23ai a DATE operand keeps it a DATE, its fraction dropped; a
                # TIMESTAMP one makes a TIMESTAMP(9), and MAX / MIN keep the
                # column's own precision.
                (domain, scale) = _datetime_result(item_text(i), operand_types(i))
                if scale is not None:
                    timestamp_scales[i] = scale
                if domain == TNS_TYPE_DATE:
                    for row in rows:
                        if row[i] is not None:
                            row[i] = row[i].replace(microsecond=0)
            if (
                domain is None
                and desc.type_code == _TIMESTAMP_OID
                and desc.precision == 0
                and not cursor.pgresult.ftable(i)
            ):
                # A computed timestamp(0) -- SYSDATE, TO_DATE, a DATE literal --
                # reports the domain's base type, not ora_date, and described
                # as a TIMESTAMP (#2058). Oracle's DATE is the only thing the
                # dialect makes a timestamp(0) of; a table's TIMESTAMP(0) column
                # has its table, and stays a TIMESTAMP.
                domain = TNS_TYPE_DATE
            if domain == TNS_TYPE_JSON:
                # An IS JSON FORMAT OSON column (#1706): a BLOB flagged OSON,
                # its value the document's OSON image, which the client decodes.
                for row in rows:
                    if row[i] is not None:
                        row[i] = encode_oson(_from_extended(row[i]))
                columns.append(
                    replace(_lob_column_meta(desc.name, TNS_TYPE_BLOB), is_oson=True)
                )
            elif domain in (TNS_TYPE_CLOB, TNS_TYPE_BLOB):
                columns.append(_lob_column_meta(desc.name, domain))
            elif domain == TNS_TYPE_INTERVALYM:
                for row in rows:
                    row[i] = _to_interval_ym(row[i])
                columns.append(_intervalym_column_meta(desc.name))
            elif domain == TNS_TYPE_DATE:
                columns.append(_date_column_meta(desc.name))
            elif domain == TNS_TYPE_RID:
                columns.append(_rowid_column_meta(desc.name))
            elif (
                vector := self._vector_column(cursor.pgresult, i, desc.type_code)
            ) is not None:
                # A VECTOR (#1708): its declared dimensions and format -- a
                # flexible one 0, any dimensions flagged -- each value an
                # array.array of its format, or a SparseVector (#1709), which
                # the core encodes.
                (count, code, sparse) = vector
                to_value = _sparse_value if sparse else _vector_value
                for row in rows:
                    row[i] = to_value(row[i], code)
                columns.append(
                    ColumnMeta(
                        name=_oracle_column_name(desc.name).encode('utf-8'),
                        data_type=TNS_TYPE_VECTOR,
                        data_length=0,
                        max_size=0,
                        charset=0,
                        csfrm=0,
                        vector_dimensions=count or 0,
                        vector_format=code or 0,
                        vector_flags=(0 if count else VECTOR_FLAG_FLEXIBLE_DIM)
                        | (VECTOR_FLAG_SPARSE if sparse else 0),
                    )
                )
            elif (
                desc.type_code not in _BUILTIN_OIDS
                and (target := self._ref_target(desc.type_code)) is not None
            ):
                for row in rows:
                    row[i] = self._ref_cell(target, row[i])
                columns.append(self._ref_column_meta(desc.name, target))
            elif (
                coll := self._column_collection_type(
                    cursor.pgresult, i, desc.type_code, constructors.get(i)
                )
            ) is not None:
                for row in rows:
                    row[i] = self._db_collection(coll, row[i], desc.type_code)
                columns.append(_object_column_meta(desc.name, coll))
            elif desc.type_code in _JSON_OIDS and self._release >= (21, 0):
                # A JSON value (#1706), described as 21c's native JSON: binary,
                # its wire length the Mirror's to fill in; each document its
                # extended types given back.
                for row in rows:
                    if row[i] is not None:
                        row[i] = _from_extended(row[i])
                columns.append(
                    ColumnMeta(
                        name=_oracle_column_name(desc.name).encode('utf-8'),
                        data_type=TNS_TYPE_JSON,
                        data_length=0,
                        max_size=0,
                        charset=0,
                        csfrm=0,
                    )
                )
            elif self._bfile_oid is not None and desc.type_code == self._bfile_oid:
                # A BFILE (#1669): the two names, charset and form 0, as the
                # passthrough describes one; its cells the core's BFile.
                for row in rows:
                    if row[i] is not None:
                        row[i] = BFile(row[i][0], row[i][1])
                columns.append(
                    ColumnMeta(
                        name=_oracle_column_name(desc.name).encode('utf-8'),
                        data_type=TNS_TYPE_BFILE,
                        data_length=0,
                        max_size=0,
                        charset=0,
                        csfrm=0,
                    )
                )
            elif (entry := self._column_object_type(desc.type_code)) is not None:
                typ, info = entry
                for row in rows:
                    row[i] = self._db_object(typ, info, row[i])
                columns.append(_object_column_meta(desc.name, typ))
            elif desc.type_code == _REFCURSOR_OID:
                # A CURSOR(...) item (#1461): each row's portal, drained.
                for row in rows:
                    if row[i] is not None:
                        row[i] = self._drain_refcursor(row[i])
                columns.append(_refcursor_column_meta(desc.name))
            else:
                columns.append(
                    _column_meta(
                        desc,
                        [r[i] for r in rows],
                        self._tstz_oid,
                        native_boolean=self._release >= (23, 0),
                    )
                )
        if self._has_quoted_names:
            folded = [
                i
                for i, desc in enumerate(cursor.description)
                if _oracle_column_name(desc.name) != desc.name
            ]
            for i in self._quoted_lower_columns(cursor.pgresult, folded):
                name = cursor.description[i].name.encode('utf-8')
                columns[i] = replace(columns[i], name=name)
        for i in self._not_null_columns(cursor.pgresult, len(columns)):
            columns[i] = replace(columns[i], null_ok=0)
        for i in _nine_digit_items(original) if original else ():
            if (
                i < len(columns)
                and columns[i].data_type in (TNS_TYPE_TIMESTAMP, TNS_TYPE_TIMESTAMPTZ)
                and not cursor.pgresult.ftable(i)
            ):
                columns[i] = replace(columns[i], scale=_NINE_FRACTIONAL_DIGITS)
        for i, scale in timestamp_scales.items():
            if columns[i].data_type == TNS_TYPE_TIMESTAMP:
                columns[i] = replace(columns[i], scale=scale)
        sizes = _bind_sizes(original, params) if original and params else {}
        unsized = [
            i
            for i, col in enumerate(columns)
            if col.data_type == TNS_TYPE_VARCHAR
            and not cursor.description[i].display_size
            and not cursor.pgresult.ftable(i)
        ]
        items = _select_list_items(original) if original and unsized else []
        operands: dict[str, int] | None = None
        for i, item in enumerate(items):
            if i in unsized:
                # An expression over a character bind describes by the bind's
                # declared size, as Oracle's does, not by the values (#2063),
                # and SYS_CONTEXT by its own (#2109).
                if operands is None:
                    operands = self._operand_widths(original)
                described, complete = _concat_width(item, sizes, operands)
                if described:
                    if not complete:
                        described = max(described, columns[i].data_length)
                    columns[i] = replace(
                        columns[i], data_length=described, max_size=described
                    )
        for i in _nchar_items(original) if original else ():
            if (
                i < len(columns)
                and columns[i].data_type == TNS_TYPE_VARCHAR
                and not cursor.pgresult.ftable(i)
            ):
                # National: n characters of AL16UTF16, 2n bytes, as a
                # declared NVARCHAR2 column describes (#1383).
                chars = columns[i].data_length
                columns[i] = replace(
                    columns[i],
                    csfrm=_CSFRM_NATIONAL,
                    charset=AL16UTF16_CHARSET,
                    data_length=2 * chars,
                    max_size=chars,
                )
        for i in _lob_substr_items(original) if original else ():
            width = (
                _LOB_SUBSTR_WIDTH.get(columns[i].data_type)
                if i < len(columns)
                else None
            )
            if width is not None and not cursor.pgresult.ftable(i):
                columns[i] = replace(columns[i], data_length=width, max_size=width)
        for i in self._json_columns(cursor.pgresult, len(columns)):
            columns[i] = replace(columns[i], is_json=True)
        # A RAW(n) column describes as its declared n, which bytea does not keep;
        # the values' widest stood in for it (#1386). A LONG / LONG RAW column,
        # stored as text / bytea, describes as itself, unsized (#1382). An
        # NVARCHAR2 column, a varchar, describes in the national form (#1383).
        plain = [
            i
            for i, col in enumerate(columns)
            if col.data_type in (TNS_TYPE_RAW, TNS_TYPE_VARCHAR, TNS_TYPE_CHAR)
        ]
        if plain:
            for i, (declared, length, _p, _s) in self._declared_column_types(
                cursor.pgresult, plain
            ).items():
                if declared in ('ROWID', 'UROWID'):
                    # A ROWID / UROWID column, a varchar here (#2083).
                    columns[i] = replace(
                        _rowid_column_meta(
                            cursor.description[i].name,
                            TNS_TYPE_RID if declared == 'ROWID' else TNS_TYPE_UROWID,
                        ),
                        name=columns[i].name,
                        null_ok=columns[i].null_ok,
                    )
                elif declared in _LONG_TYPES:
                    columns[i] = replace(
                        columns[i],
                        data_type=_LONG_TYPES[declared],
                        data_length=0,
                        max_size=0,
                    )
                elif declared == 'RAW' and length:
                    columns[i] = replace(
                        columns[i], data_length=length, max_size=length
                    )
                elif declared == _NATIONAL_OF.get(columns[i].data_type) and length:
                    # National: n characters of AL16UTF16, 2n bytes (#1383,
                    # #1416).
                    columns[i] = replace(
                        columns[i],
                        csfrm=_CSFRM_NATIONAL,
                        charset=AL16UTF16_CHARSET,
                        data_length=length,
                        max_size=length // 2,
                    )
        # An unaliased computed item is named by its own Oracle text, as Oracle
        # names it, where PostgreSQL gave `length` or `?column?` (#1449).
        if original:
            named = _expression_names(original)
            if named and len(named) <= len(columns):
                for i, name in named.items():
                    if i < len(columns):
                        columns[i] = replace(columns[i], name=name.encode('utf-8'))
        # A table's unconstrained NUMBER column -- a numeric with no typmod --
        # describes with precision 0 and scale -127, as Oracle's does; a computed
        # number has neither, as on a live server, so only a column that traces
        # to a table counts (#1421). So does a constant item, which Oracle folds
        # -- 1, 1 + 1, abs(-1) -- where one computed from a column does not
        # (#1444). A FLOAT record below overrides it.
        constants = _constant_items(original) if original else set()
        for i, desc in enumerate(cursor.description):
            if columns[i].data_type == TNS_TYPE_NUMBER and (
                (
                    desc.type_code == _NUMERIC_OID
                    and cursor.pgresult.ftable(i)
                    and cursor.pgresult.fmod(i) == -1
                )
                or (i in constants and not columns[i].precision)
            ):
                columns[i] = replace(columns[i], precision=0, scale=-127)
        # An INTERVAL column describes with its declared precisions, which
        # PostgreSQL's interval does not keep (#1381). A FLOAT(b) column, a
        # numeric here, describes as a NUMBER of precision b and scale -127,
        # Oracle's marker for FLOAT (#1384).
        interval = [
            i
            for i, col in enumerate(columns)
            if col.data_type
            in (TNS_TYPE_INTERVALDS, TNS_TYPE_INTERVALYM, TNS_TYPE_NUMBER)
        ]
        if interval:
            for i, (declared, _length, precision, scale) in self._declared_column_types(
                cursor.pgresult, interval
            ).items():
                if declared == 'FLOAT':
                    columns[i] = replace(columns[i], precision=precision, scale=-127)
                elif precision is not None:
                    columns[i] = replace(
                        columns[i], precision=precision, scale=scale or 0
                    )
            # A computed interval, neither a column nor a literal (#2139): a
            # leading precision of 9, as Oracle gives every one, and for a DAY
            # TO SECOND 6 fractional digits for a difference -- of timestamps,
            # the only subtraction that gives one -- and 9 for the rest.
            # Measured on 23ai.
            items = _select_list_items(original) if original else []
            for i, col in enumerate(columns):
                if (
                    col.data_type in (TNS_TYPE_INTERVALDS, TNS_TYPE_INTERVALYM)
                    and not cursor.pgresult.ftable(i)
                    and not col.precision
                ):
                    if col.data_type == TNS_TYPE_INTERVALYM:
                        scale = 0
                    elif i < len(items) and _top_level_subtraction(items[i]):
                        scale = _DEFAULT_FRACTIONAL_PRECISION
                    else:
                        scale = _COMPUTED_INTERVAL_DIGITS
                    columns[i] = replace(
                        col, precision=_COMPUTED_INTERVAL_DIGITS, scale=scale
                    )
            # An INTERVAL literal, by its own qualifiers (#2108).
            literals = _interval_literal_items(original) if original else {}
            for i, (precision, scale) in literals.items():
                if (
                    i < len(columns)
                    and columns[i].data_type
                    in (TNS_TYPE_INTERVALDS, TNS_TYPE_INTERVALYM)
                    and not cursor.pgresult.ftable(i)
                ):
                    columns[i] = replace(columns[i], precision=precision, scale=scale)
        # An NCLOB column, an ora_clob like a CLOB, describes in the national
        # character set form (#1369).
        clob = [i for i, col in enumerate(columns) if col.data_type == TNS_TYPE_CLOB]
        if clob:
            for i, (declared, _length, _p, _s) in self._declared_column_types(
                cursor.pgresult, clob
            ).items():
                if declared == 'NCLOB':
                    columns[i] = replace(
                        columns[i], csfrm=_CSFRM_NATIONAL, charset=AL16UTF16_CHARSET
                    )
        # A column with a SQL domain or annotations describes them (#1711).
        if self._has_column_catalog and self._has_sql_domains():
            for i, (schema, name, notes) in self._sql_domain_columns(
                cursor.pgresult, len(columns)
            ).items():
                columns[i] = replace(
                    columns[i],
                    domain_schema=schema,
                    domain_name=name,
                    annotations=notes,
                )
        # A computed TO_VECTOR(text, n, format [, kind]) item describes as that
        # vector (#1708, #1726), where its composite says only its values' format.
        if original:
            for i, (count, code, kind_named) in _computed_vector_columns(
                original
            ).items():
                if i < len(columns) and columns[i].data_type == TNS_TYPE_VECTOR:
                    # Sparse as the calls say, else as the value's type is.
                    is_sparse = (
                        bool((columns[i].vector_flags or 0) & VECTOR_FLAG_SPARSE)
                        if kind_named is None
                        else kind_named
                    )
                    columns[i] = replace(
                        columns[i],
                        vector_dimensions=count or 0,
                        vector_format=code or 0,
                        vector_flags=(0 if count else VECTOR_FLAG_FLEXIBLE_DIM)
                        | (VECTOR_FLAG_SPARSE if is_sparse else 0),
                    )
        # A CAST to NVARCHAR2(n) / NCHAR(n) in the select list describes national,
        # n characters and 2n bytes, which its varchar(n) / char(n) does not say
        # (#1440).
        if original:
            for i, length in _computed_national_columns(original).items():
                if i < len(columns) and columns[i].data_type in _NATIONAL_OF:
                    columns[i] = replace(
                        columns[i],
                        csfrm=_CSFRM_NATIONAL,
                        charset=AL16UTF16_CHARSET,
                        data_length=2 * length,
                        max_size=length,
                    )
        tstz = [
            i for i, col in enumerate(columns) if col.data_type == TNS_TYPE_TIMESTAMPTZ
        ]
        if tstz:
            for i, prec in self._tstz_precisions(cursor.pgresult, tstz).items():
                columns[i] = replace(columns[i], scale=prec)
        return Result(columns=columns, rows=[tuple(r) for r in rows])

    def _column_object_type(
        self, pg_oid: int
    ) -> tuple[DbObjectType, CompositeInfo] | None:
        # Only an oid no built-in mapping claims can be an object type; the
        # ora_tstz composite is TIMESTAMP WITH TIME ZONE, not an object.
        if pg_oid in _BUILTIN_OIDS or pg_oid == self._tstz_oid:
            return None
        return self._object_type(pg_oid)

    def _column_collection_type(
        self, pgresult, index: int, pg_oid: int, constructor: str | None = None
    ) -> DbObjectType | None:
        # A VARRAY / nested-table column (#1206). PostgreSQL describes a domain
        # column by its base type, an array here, so an array column is traced
        # through libpq ftable / ftablecol to the type its table declares. A
        # computed array has no table column; when its select item is one call
        # to a collection type's constructor, that type is the one (#1473).
        # Any other computed array stays a plain array.
        if pg_oid not in self._array_oids:
            row = self._conn.execute(
                "SELECT typcategory = 'A' FROM pg_type WHERE oid = %s", (pg_oid,)
            ).fetchone()
            self._array_oids[pg_oid] = bool(row and row[0])
        if not self._array_oids[pg_oid]:
            return None
        relid = pgresult.ftable(index)
        if not relid:
            return (
                self._constructed_collection_type(constructor) if constructor else None
            )
        column = self._table_columns(pgresult, [index]).get(index)
        return self._collection_type(column.type_oid) if column else None

    def _constructed_collection_type(self, name: str) -> DbObjectType | None:
        # The collection type a constructor call names, or None when the name
        # is not a type -- an ordinary function returning an array (#1473).
        # Looked up each time: a type dropped and created again under the same
        # name has a new oid.
        row = self._conn.execute('SELECT to_regtype(%s)::oid', (name,)).fetchone()
        return self._collection_type(row[0]) if row and row[0] else None

    def _collection_type(self, pg_oid: int) -> DbObjectType | None:
        """The Oracle collection type an array domain stands for (#1206).

        Built the way ``all_types`` / ``all_coll_types`` build what a client
        reads, so the two agree on the OID, the kind and the element. None when
        the oid is not a collection type.
        """
        if pg_oid in self._collection_types:
            return self._collection_types[pg_oid]
        kind = self._type_kind(pg_oid)
        typ = None
        if kind is not None and kind[0] == 'collection':
            (_kind, owner, name, element, _typmod) = kind
            bound = self._conn.execute(
                "SELECT substring(pg_get_constraintdef(oid) FROM '<=\\s*([0-9]+)')::int "
                'FROM pg_constraint WHERE contypid = %s',
                (pg_oid,),
            ).fetchone()
            upper = bound[0] if bound else None
            typ = DbObjectType(
                owner,
                name,
                _object_type_oid(pg_oid),
                1,
                [],
                is_collection=True,
                collection_type=(
                    COLLECTION_VARRAY if upper else COLLECTION_NESTED_TABLE
                ),
                element=self._collection_element(element),
                max_elements=upper or 0,
            )
            recorded = self._recorded_element(pg_oid)
            if recorded is not None and typ.element is not None:
                # A client sends and expects an NVARCHAR2 / NCHAR element in
                # AL16UTF16 inside the image, as an attribute (#1437); a RAW(n)
                # element as RAW bytes, not the BLOB a bytea reads as (#1545).
                declared = recorded[0]
                typ.element = {
                    **typ.element,
                    'type_name': declared,
                    'data_type': type_name_to_tns(declared),
                    'charset': AL16UTF16_CHARSET if declared != 'RAW' else None,
                }
        self._collection_types[pg_oid] = typ
        return typ

    def _collection_element(self, pg_oid: int) -> dict:
        # The element layout a collection's image is packed against: an object
        # element carries its own type, as a client's describe embeds it.
        if pg_oid == _XML_OID:
            # A collection of XMLType (#1537).
            return {
                'name': 'element',
                'type_name': 'XMLTYPE',
                'data_type': None,
                'charset': None,
                'object_type': _XMLTYPE_DBTYPE,
            }
        entry = self._object_type(pg_oid)
        if entry is not None:
            typ = entry[0]
            return {
                'name': 'element',
                'type_name': typ.name,
                'data_type': type_name_to_tns(typ.name),
                'charset': None,
                'object_type': typ,
            }
        inner = self._collection_type(pg_oid)
        if inner is not None:
            # A collection of collections (#1276): psycopg does not know the inner
            # domain, so a value came back as text; load the domain as its base
            # array, and arrays of it as lists of those.
            self._register_collection_loaders(pg_oid)
            return {
                'name': 'element',
                'type_name': inner.name,
                'data_type': type_name_to_tns(inner.name),
                'charset': None,
                'object_type': inner,
            }
        row = self._conn.execute(
            f"SELECT CASE WHEN typname = '{_CLOB_TYPE}' THEN 'CLOB' "
            f"WHEN typname = '{_BLOB_TYPE}' THEN 'BLOB' "
            'ELSE sys.ora_type_name(format_type(oid, NULL)) END '
            'FROM pg_type WHERE oid = %s',
            (pg_oid,),
        ).fetchone()
        type_name = row[0] if row else None
        return {
            'name': 'element',
            'type_name': type_name,
            'data_type': type_name_to_tns(type_name),
            'charset': None,
        }

    def _register_collection_loaders(self, pg_oid: int) -> None:
        # An array domain inside another array loads as its base array does, and
        # an array of it as a list of those (#1276).
        from psycopg.types import TypeInfo
        from psycopg.types.array import register_array

        row = self._conn.execute(
            'SELECT typbasetype, %s::oid::regtype::text FROM pg_type WHERE oid = %s',
            (pg_oid, pg_oid),
        ).fetchone()
        if row is None:
            return
        (base, regtype) = row
        for fmt in (psycopg.pq.Format.TEXT, psycopg.pq.Format.BINARY):
            loader = self._conn.adapters.get_loader(base, fmt)
            if loader is not None:
                self._conn.adapters.register_loader(pg_oid, loader)
        domain = TypeInfo.fetch(self._conn, regtype)
        if domain is not None:
            register_array(domain, self._conn)

    def _db_collection(
        self, typ: DbObjectType, value: object, array_oid: int
    ) -> object:
        # One array cell as the collection DbObject the Mirror encodes; an
        # object element is built as an object column's value is. A cursor that
        # executed before the element's composite was registered hands the text
        # form `{"(1,a)"}`; the array loader registered with it parses that.
        if value is None:
            return None
        if isinstance(value, str):
            loader = self._conn.adapters.get_loader(array_oid, psycopg.pq.Format.TEXT)
            if loader is None:
                raise UnsupportedFeature(f'collection type {typ.name}: no loader')
            value = loader(array_oid, self._conn).load(value.encode('utf-8'))
        if not isinstance(value, list):
            raise UnsupportedFeature(f'collection type {typ.name}: not an array value')
        nested = (typ.element or {}).get('object_type')
        if nested is not None and nested.is_collection:
            # A collection of collections (#1276): each element its own
            # collection, NULL staying NULL.
            inner_oid = _pg_oid_of(nested.oid) or 0
            base = self._conn.execute(
                'SELECT typbasetype FROM pg_type WHERE oid = %s', (inner_oid,)
            ).fetchone()
            value = [
                self._db_collection(nested, v, base[0] if base else 0) for v in value
            ]
        elif nested is not None and nested is not _XMLTYPE_DBTYPE:
            # (An XMLType element is its document's text, as it comes, #1537.)
            entry = self._object_type(_pg_oid_of(nested.oid) or 0)
            if entry is None:
                raise UnsupportedFeature(f'collection type {typ.name}: no element type')
            value = [self._db_object(entry[0], entry[1], v) for v in value]
        return typ.newobject(value)

    def describe_type(self, name: str) -> TypeDescription | None:
        """The object or collection type ``name`` names, for an OCI client's
        type describe (#1411): looked for in the session's own schemas, then in
        SYS, as a public synonym would find it there. None if there is none."""
        (schema, _dot, bare) = name.rpartition('.')
        row = self._conn.execute(
            'SELECT t.oid FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace '
            'WHERE sys.ora_name(t.typname) = %s '
            'AND (CASE WHEN %s <> %s THEN sys.ora_owner(n.nspname) = %s '
            "ELSE n.nspname = ANY(current_schemas(false)) OR n.nspname = 'sys' END) "
            # One the session may use (#1621).
            'AND sys.ora_type_visible(sys.ora_owner(n.nspname), sys.ora_name(t.typname)) '
            "ORDER BY n.nspname = 'sys' LIMIT 1",
            (bare, schema, '', schema),
        ).fetchone()
        if row is None:
            return None
        kind = self._type_kind(row[0])
        if kind is None:
            return None
        shape = self._type_shape(row[0])
        if isinstance(shape, _TdsCollection):
            description = 'varray' if shape.varray else 'nested_table'
            null_tds = _tds(_TdsObject((_TDS_NULL_LEAF,)))
        else:
            description = 'object'
            null_tds = _tds_null(shape)
        return TypeDescription(
            schema=kind[1],
            name=kind[2],
            oid=_object_type_oid(row[0]),
            kind=description,
            tds=_tds(shape),
            null_tds=null_tds,
        )

    def _type_kind(self, pg_oid: int) -> tuple[str, str, str, int, int] | None:
        # (kind, owner, name, element oid, element typmod) of a named type: kind
        # 'object' for a standalone or table row composite, 'collection' for an
        # array domain (its element and bound), else None.
        row = self._conn.execute(
            'SELECT t.typtype, sys.ora_owner(n.nspname), sys.ora_name(t.typname), '
            'b.typcategory, b.typelem, t.typtypmod, c.relkind '
            'FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace '
            'LEFT JOIN pg_type b ON b.oid = t.typbasetype '
            'LEFT JOIN pg_class c ON c.oid = t.typrelid WHERE t.oid = %s',
            (pg_oid,),
        ).fetchone()
        if row is None:
            return None
        (typtype, owner, name, base_category, element, typmod, relkind) = row
        if typtype == 'c' and relkind in ('c', 'r') and pg_oid != self._tstz_oid:
            return ('object', owner, name, 0, -1)
        if typtype == 'd' and base_category == 'A':
            return ('collection', owner, name, element, typmod)
        return None

    def _pg_type_name(self, pg_oid: int) -> str:
        row = self._conn.execute(
            'SELECT typname FROM pg_type WHERE oid = %s', (pg_oid,)
        ).fetchone()
        if row is None:
            raise UnsupportedFeature(f'type shape: no type has the oid {pg_oid}')
        return row[0]

    def _package_index_types(self, package: str) -> dict[str, str]:
        # The index-by table types a package's spec declared (#1607): name
        # (lower case) -> the PostgreSQL type, for its body's translation.
        if not self._has_package_catalog:
            return {}
        return {
            name.lower(): f'{package}.{name.lower()}'
            for (name,) in self._conn.execute(
                'SELECT name FROM sys.ora_plsql_types WHERE package = %s '
                "AND meta->>'coll_type' = 'PL/SQL INDEX TABLE'",
                (package,),
            ).fetchall()
        }

    def _plsql_type(self, pg_oid: int) -> tuple[str, str, str, dict] | None:
        """A package's type behind a PostgreSQL type (#1607): its owner,
        package, name and what its declaration says; None for any other type."""
        if pg_oid in self._plsql_types:
            return self._plsql_types[pg_oid]
        row = (
            self._conn.execute(
                'SELECT k.owner, upper(p.package), p.name, p.meta '
                'FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace '
                'JOIN sys.ora_plsql_types p ON p.package = n.nspname '
                'AND lower(p.name) = t.typname '
                'JOIN sys.ora_packages k ON k.name = p.package WHERE t.oid = %s',
                (pg_oid,),
            ).fetchone()
            if self._has_package_catalog
            else None
        )
        found = (row[0], row[1], row[2], row[3] or {}) if row is not None else None
        self._plsql_types[pg_oid] = found
        return found

    def _plsql_named_oid(self, owner: str, ref: dict) -> int | None:
        # The PostgreSQL type a package type's named field or element is: a
        # package's type, a schema's, a table's row (#1607).
        name = str(ref['name'])
        if name.endswith('%ROWTYPE'):
            row = self._conn.execute(
                'SELECT t.oid FROM pg_type t JOIN pg_class c ON c.oid = t.typrelid '
                "WHERE c.relkind = 'r' AND sys.ora_name(c.relname) = %s "
                'ORDER BY c.relnamespace = to_regnamespace(current_schema()) DESC '
                'LIMIT 1',
                (name[: -len('%ROWTYPE')],),
            ).fetchone()
        elif ref.get('package'):
            row = self._conn.execute(
                'SELECT to_regtype(%s)::oid',
                (f'{str(ref["package"]).lower()}.{name.lower()}',),
            ).fetchone()
        else:
            row = self._conn.execute(
                'SELECT t.oid FROM pg_type t JOIN pg_namespace n '
                'ON n.oid = t.typnamespace WHERE sys.ora_name(t.typname) = %s '
                'AND sys.ora_owner(n.nspname) = %s LIMIT 1',
                (name, owner),
            ).fetchone()
        return row[0] if row is not None and row[0] is not None else None

    def _plsql_part_shape(self, owner: str, ref: dict):
        # The TDS shape of a package type's field or element (#1607).
        if ref.get('named'):
            pg_oid = self._plsql_named_oid(owner, ref)
            if pg_oid is None:
                raise UnsupportedFeature(f'type shape: no type {ref["name"]}')
            return self._type_shape(pg_oid)
        name = str(ref['name'])
        if name in ('BOOLEAN', 'PL/SQL PLS INTEGER', 'PL/SQL BINARY INTEGER'):
            return _TdsLeaf(b'\x08')  # one code for all three, as 23ai sends them
        if name in ('VARCHAR2', 'CHAR', 'NVARCHAR2', 'NCHAR'):
            national = name.startswith('N')
            length = int(ref.get('length') or 1)
            code = 0x07 if 'VARCHAR' in name else 0x01
            return _tds_chars(code, 2 * length if national else length, national)
        if name == 'RAW':
            return _TdsLeaf(b'\x13' + int(ref.get('length') or 1).to_bytes(2, 'big'))
        if name in ('NUMBER', 'INTEGER', 'SMALLINT'):
            if name != 'NUMBER':
                return _tds_number(0, 0)
            precision = ref.get('precision')
            scale = ref.get('scale')
            return _tds_number(
                precision or 0, scale if scale is not None else 0 if precision else -127
            )
        if name in _FLOAT_ATTRIBUTE_TYPES:
            return _TdsLeaf(bytes([0x05, int(ref.get('precision') or 0)]))
        leaves = {
            'DATE': _TdsLeaf(b'\x02'),
            'CLOB': _TdsLeaf(b'\x1d'),
            'NCLOB': _TdsLeaf(b'\x1d'),
            'BLOB': _TdsLeaf(b'\x1e'),
            'BINARY_FLOAT': _TdsLeaf(b'\x25', newer=True),
            'BINARY_DOUBLE': _TdsLeaf(b'\x2d', newer=True),
        }
        if name in leaves:
            return leaves[name]
        fraction = ref.get('scale')
        digits = int(fraction) if fraction is not None else 6
        timestamp_code = {
            'TIMESTAMP': 0x15,
            'TIMESTAMP WITH TZ': 0x17,
            'TIMESTAMP WITH LOCAL TZ': 0x21,
        }.get(name)
        if timestamp_code is None:
            raise UnsupportedFeature(f'type shape: {name} has no TDS leaf')
        return _tds_timestamp(timestamp_code, digits)

    def _plsql_shape(self, owner: str, meta: dict):
        # A package type's TDS shape (#1607): a record an object of its fields,
        # a collection of its element, an index-by table kind 1.
        if meta.get('typecode') == 'PL/SQL RECORD':
            return _TdsObject(
                tuple(self._plsql_part_shape(owner, f['type']) for f in meta['attrs'])
            )
        coll_type = meta.get('coll_type')
        return _TdsCollection(
            varray=coll_type == 'VARYING ARRAY',
            bound=int(meta.get('upper_bound') or 0),
            element=self._plsql_part_shape(owner, meta['elem']),
            index_table=coll_type == 'PL/SQL INDEX TABLE',
        )

    def _plsql_attribute_rows(self, owner: str, meta: dict) -> list[tuple]:
        # The attribute cursor GET_TYPE_SHAPE returns for a package type, as
        # 23ai sends it (#1607): a record's fields, INSTANTIABLE YES; a
        # collection's element alone, unnamed, INSTANTIABLE NULL.
        def row(name, position, ref, instantiable) -> tuple:
            if ref.get('named'):
                pg_oid = self._plsql_named_oid(owner, ref)
                toid = _object_type_oid(pg_oid) if pg_oid is not None else None
                return (
                    1, name, position, ref['name'], owner, ref.get('package'),
                    toid, instantiable, None, None,
                )  # fmt: skip
            toid = bytes(15) + bytes([_BUILTIN_TYPE_OID_BYTE.get(ref['name'], 0)])
            return (
                1,
                name,
                position,
                ref['name'],
                None,
                None,
                toid,
                instantiable,
                None,
                None,
            )

        if meta.get('typecode') == 'PL/SQL RECORD':
            return [
                row(f['name'], position, f['type'], 'YES')
                for position, f in enumerate(meta['attrs'], 1)
            ]
        return [row(None, 1, meta['elem'], None)]

    def _plsql_type_named(self, full_name: str) -> int | None:
        # The PostgreSQL type of a package type a client names (#1607):
        # "OWNER"."PACKAGE"."TYPE", or "PACKAGE"."TYPE" in the session's schema.
        parts = [p.strip('"').upper() for p in full_name.split('.')]
        if len(parts) == 3:
            (owner, package, name) = parts
        elif len(parts) == 2:
            (package, name) = parts
            owner = None
        else:
            return None
        if not self._has_package_catalog:
            return None
        row = self._conn.execute(
            'SELECT to_regtype(p.package || %s || lower(p.name))::oid '
            'FROM sys.ora_plsql_types p JOIN sys.ora_packages k ON k.name = p.package '
            'WHERE p.package = lower(%s) AND p.name = %s AND p.public '
            "AND p.meta ? 'typecode' "
            'AND k.owner = coalesce(%s, sys.ora_owner(current_schema()))',
            ('.', package, name, owner),
        ).fetchone()
        return row[0] if row is not None else None

    def _type_shape(self, pg_oid: int, typmod: int = -1):
        """The TDS shape of a type (#1134): a _TdsObject of its attributes, a
        _TdsCollection of its element, or a scalar's leaf."""
        plsql = self._plsql_type(pg_oid)
        if plsql is not None:
            return self._plsql_shape(plsql[0], plsql[3])
        kind = self._type_kind(pg_oid)
        if kind is None:
            if pg_oid == _XML_OID:
                return _TDS_XMLTYPE  # an XMLType attribute or element (#1537)
            return _tds_scalar(self._pg_type_name(pg_oid), typmod)[0]
        if kind[0] == 'object':
            declared = self._declared_attribute_types(pg_oid)
            # A WITH TIME ZONE attribute is the ora_tstz composite, which keeps
            # no precision; its leaf takes the recorded one (#1308, #1552).
            zoned = self._attribute_tstz_precisions(pg_oid)
            return _TdsObject(
                tuple(
                    _declared_leaf(declared.get(n), m)
                    or (
                        _tds_timestamp(0x17, zoned[n])
                        if n in zoned
                        else self._type_shape(t, m)
                    )
                    for (n, t, m) in self._attributes(pg_oid)
                )
            )
        (_kind, _owner, _name, element, element_typmod) = kind
        bound = self._conn.execute(
            "SELECT substring(pg_get_constraintdef(oid) FROM '<=\\s*([0-9]+)')::int "
            'FROM pg_constraint WHERE contypid = %s',
            (pg_oid,),
        ).fetchone()
        # A recorded element type -- NVARCHAR2 / NCHAR, RAW(n) -- has its own
        # leaf (#1437, #1545).
        recorded = self._recorded_element(pg_oid)
        return _TdsCollection(
            varray=bound is not None and bound[0] is not None,
            bound=bound[0] if bound and bound[0] is not None else 0,
            element=_declared_leaf(
                (recorded[0], recorded[1], None) if recorded else None, element_typmod
            )
            or self._type_shape(element, element_typmod),
        )

    def _attribute_tstz_precisions(self, pg_oid: int) -> dict[str, int]:
        # The precision recorded for each TIMESTAMP(n) WITH TIME ZONE attribute
        # of a composite -- an object type's or a table's %ROWTYPE -- by name
        # (#1552); one not listed has Oracle's default, 6.
        if not self._has_tstz_precision:
            return {}
        return dict(
            self._conn.execute(
                'SELECT a.attname, p.prec FROM pg_type t '
                'JOIN pg_attribute a ON a.attrelid = t.typrelid '
                'JOIN sys.ora_tstz_precision p '
                'ON p.relid = a.attrelid AND p.attnum = a.attnum '
                'WHERE t.oid = %s',
                (pg_oid,),
            ).fetchall()
        )

    def _declared_attribute_types(
        self, pg_oid: int
    ) -> dict[str, tuple[str, int | None, int | None]]:
        # The type each attribute of a composite was declared as, where
        # sys.ora_columns records one (#1431): attribute name -> (Oracle type,
        # its recorded length, its recorded precision).
        if not self._has_column_catalog:
            return {}
        return {
            name: (data_type, length, precision)
            for name, data_type, length, precision in self._conn.execute(
                'SELECT a.attname, o.data_type, o.data_length, o.data_precision '
                'FROM pg_type t '
                'JOIN pg_attribute a ON a.attrelid = t.typrelid '
                'JOIN sys.ora_columns o ON o.relid = a.attrelid AND o.attnum = a.attnum '
                'WHERE t.oid = %s',
                (pg_oid,),
            ).fetchall()
        }

    def _is_table_rowtype(self, pg_oid: int) -> bool:
        # Whether a composite is a table's row type, a %ROWTYPE (#1781).
        row = self._conn.execute(
            'SELECT c.relkind FROM pg_type t JOIN pg_class c ON c.oid = t.typrelid '
            'WHERE t.oid = %s',
            (pg_oid,),
        ).fetchone()
        return row is not None and row[0] == 'r'

    def _attributes(self, pg_oid: int) -> list[tuple[str, int, int]]:
        # (name, type oid, typmod) of a composite's attributes, in order.
        return self._conn.execute(
            'SELECT a.attname, a.atttypid, a.atttypmod FROM pg_type t '
            'JOIN pg_attribute a ON a.attrelid = t.typrelid '
            'WHERE t.oid = %s AND a.attnum > 0 AND NOT a.attisdropped '
            "AND a.attname <> 'sys_nc_oid$' "
            + (
                # A table's INVISIBLE column is no attribute of its %ROWTYPE (#1195).
                'AND NOT EXISTS (SELECT 1 FROM sys.ora_invisible_columns h '
                'WHERE h.relid = a.attrelid AND h.attnum = a.attnum) '
                if self._has_invisible_catalog
                else ''
            )
            + 'ORDER BY a.attnum',
            (pg_oid,),
        ).fetchall()

    def _attribute_rows(self, pg_oid: int) -> list[tuple]:
        # The attribute cursor GET_TYPE_SHAPE returns for an object: one row per
        # attribute, as 23ai sends it -- a version, the name, the position, the
        # type name, its owner (a named type's only), its package, its OID, and
        # whether it is instantiable -- in the order the client reads them.
        rows = []
        declared = self._declared_attribute_types(pg_oid)
        rowtype = self._is_table_rowtype(pg_oid)
        for position, (attname, atttypid, atttypmod) in enumerate(
            self._attributes(pg_oid), 1
        ):
            kind = self._type_kind(atttypid)
            if (
                rowtype
                and kind is None
                and self._pg_type_name(atttypid) in ('interval', _INTERVALYM_TYPE)
            ):
                # 23ai leaves a table's INTERVAL columns out of its %ROWTYPE's
                # attribute cursor, while its TDS describes them (#1781).
                continue
            if atttypid == _XML_OID:
                # SYS.XMLTYPE, under its own id, as 23ai lists one (#1537).
                (type_name, owner, toid) = ('XMLTYPE', 'SYS', _XMLTYPE_OID)
            elif kind is None:
                type_name = _tds_scalar(self._pg_type_name(atttypid), atttypmod)[1]
                as_declared = declared.get(attname, (None, None, None))[0]
                # An NCLOB is an ora_clob like a CLOB; only its name tells them
                # apart, and the client types the attribute by it (#1431).
                if type_name == 'CLOB' and as_declared == 'NCLOB':
                    type_name = 'NCLOB'
                elif (type_name, as_declared) in (
                    ('VARCHAR2', 'NVARCHAR2'),
                    ('CHAR', 'NCHAR'),
                    ('BLOB', 'RAW'),  # a RAW(n) is a bytea (#1544)
                    # A FLOAT / REAL / DOUBLE PRECISION is a numeric (#1423).
                    *(('NUMBER', name) for name in _FLOAT_ATTRIBUTE_TYPES),
                ):
                    type_name = declared[attname][0]  # (#1383, #1416)
                (owner, toid) = (
                    None,
                    bytes(15) + bytes([_BUILTIN_TYPE_OID_BYTE[type_name]]),
                )
            else:
                (_kind, owner, type_name, _e, _m) = kind
                toid = _object_type_oid(atttypid)
            rows.append(
                (
                    1,
                    _oracle_column_name(attname),
                    position,
                    type_name,
                    owner,
                    None,
                    toid,
                    'YES',
                    None,
                    None,
                )
            )
        return rows

    def _execute_type_shape(self, sql: str, binds: Sequence) -> Result:
        """A block calling DBMS_PICKLER.GET_TYPE_SHAPE (#1134), answered whole:
        the type's return code, OID, version, TDS, attribute cursor, and -- in
        python-oracledb's own block -- its schema and name.

        A bind takes the answer for the argument it is in the call -- the
        full name first, the attribute cursor eighth -- or for the call's return
        value it is assigned; a bind outside the call by its name, as
        python-oracledb's :schema / :name / :package_name are (#1542).
        """
        names = [name.lower() for (name, _q) in bind_placeholders(sql, dedupe=True)]
        values: dict[str, object] = {n: b.value for (n, b) in zip(names, binds)}
        (roles, literal_name) = _type_shape_roles(sql)
        by_role = {roles.get(n, n): v for n, v in values.items()}
        full_name = str(by_role.get('full_name') or literal_name or '')
        attrs_rc = CursorResult(columns=list(_ATTRIBUTE_CURSOR_COLUMNS), rows=[])
        answer: dict[str, object] = {
            'ret_val': _TYPE_SHAPE_NOT_FOUND,
            'oid': None,
            # A type not found reads version 0, as 23ai answers (#1542).
            'version': 0,
            'tds': None,
            'attrs_rc': attrs_rc,
            'package_name': None,
            'schema': None,
            'name': None,
            'instantiable': 'YES',
            'supertype_owner': None,
            'supertype_name': None,
            'subtype_rc': CursorResult(
                columns=list(_ATTRIBUTE_CURSOR_COLUMNS), rows=[]
            ),
        }
        row_type = full_name.upper().endswith('%ROWTYPE')
        (schema, _dot, name) = full_name.rpartition('.')
        if row_type:
            name = name[: -len('%ROWTYPE')]
        if (schema.strip('"').upper(), name.strip('"').upper()) == ('SYS', 'XMLTYPE'):
            # A built-in, opaque type with no PostgreSQL counterpart to look up:
            # answered as Oracle answers it (#1536).
            answer.update(
                ret_val=0,
                oid=_XMLTYPE_OID,
                version=1,
                tds=_XMLTYPE_TDS,
                schema='SYS',
                name='XMLTYPE',
            )
            return Result(out_binds=[answer.get(n, values.get(n)) for n in names])
        found = self._conn.execute(
            'SELECT t.oid FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace '
            'LEFT JOIN pg_class c ON c.oid = t.typrelid '
            'WHERE sys.ora_owner(n.nspname) = coalesce(%s, sys.ora_owner(current_schema())) '
            'AND sys.ora_name(coalesce(c.relname, t.typname)) = %s '
            "AND coalesce(c.relkind = 'r', false) = %s "
            # A type the session may use (#1621): its own, or one granted it.
            # A table's row type is a table's privilege, which is not kept.
            'AND (%s OR sys.ora_type_visible(sys.ora_owner(n.nspname), '
            'sys.ora_name(coalesce(c.relname, t.typname)))) '
            # A package's schema is no owner: its types are the package's (#1607).
            + (
                'AND NOT EXISTS (SELECT 1 FROM sys.ora_packages k '
                'WHERE k.name = n.nspname) '
                if self._has_package_catalog
                else ''
            )
            + 'LIMIT 1',
            (schema.strip('"') or None, name.strip('"'), row_type, row_type),
        ).fetchone()
        # A package's type (#1607): "OWNER"."PACKAGE"."TYPE", or a two-part name
        # no schema has a type by.
        plsql_oid = (
            self._plsql_type_named(full_name)
            if not row_type and (found is None or full_name.count('.') == 2)
            else None
        )
        if plsql_oid is not None:
            plsql = self._plsql_type(plsql_oid)
            if plsql is not None:
                (owner, package, type_name, meta) = plsql
                answer.update(
                    ret_val=0,
                    oid=_object_type_oid(plsql_oid),
                    version=1,
                    tds=_tds(self._plsql_shape(owner, meta)),
                    schema=owner,
                    package_name=package,
                    name=type_name,
                )
                attrs_rc.rows.extend(self._plsql_attribute_rows(owner, meta))
                return Result(
                    out_binds=[
                        answer.get(roles.get(n, n), values.get(n)) for n in names
                    ]
                )
        pg_oid = found[0] if found is not None else None
        kind = self._type_kind(pg_oid) if pg_oid is not None else None
        if pg_oid is not None and kind is not None:
            (_kind, owner, type_name, _e, _m) = kind
            shape = self._type_shape(pg_oid)
            answer.update(
                ret_val=0,
                oid=_object_type_oid(pg_oid),
                version=1,
                tds=_tds(shape),
                schema=owner,
                name=f'{name.strip(chr(34))}%ROWTYPE' if row_type else type_name,
            )
            if row_type:
                # full_name is IN OUT, and the server hands it back qualified by
                # the table's owner -- 'T%ROWTYPE' returns as 'OWNER.T%ROWTYPE'.
                # python-oracledb takes the record's schema from it and reads
                # the attributes from all_tab_cols by that owner; echoed back
                # unqualified, the schema was empty and the query found no
                # columns at all (#1479).
                answer['full_name'] = f'{owner}.{name.strip(chr(34))}%ROWTYPE'
            if isinstance(shape, _TdsObject):
                attrs_rc.rows.extend(self._attribute_rows(pg_oid))
        return Result(
            out_binds=[answer.get(roles.get(n, n), values.get(n)) for n in names]
        )

    def _plsql_member(self, owner: str, name: str | None, ref: dict) -> dict:
        # A package type's field or element as the image walkers lay it out
        # (#1607): a built-in by its wire type, an NVARCHAR2 in AL16UTF16; a
        # named type with its own DbObjectType.
        type_name = str(ref['name'])
        member: dict = {
            'name': name or 'element',
            'type_name': type_name,
            'data_type': None if ref.get('named') else type_name_to_tns(type_name),
            'charset': AL16UTF16_CHARSET if ref.get('charset') == 'NCHAR_CS' else None,
        }
        if ref.get('named'):
            pg_oid = self._plsql_named_oid(owner, ref)
            nested = (
                self._nested_type(
                    pg_oid, f'{owner}.{type_name}', member['name'], type_name
                )
                if pg_oid is not None
                else None
            )
            if nested is None:
                raise UnsupportedFeature(f'package type: no type {type_name}')
            member['object_type'] = nested
        return member

    def _plsql_object_type(
        self, pg_oid: int
    ) -> tuple[DbObjectType, CompositeInfo] | None:
        """A package's record or index-by table as the object or collection type
        a client binds and reads (#1607), its fields and element as declared,
        and the composite it is stored as -- an index-by table's ``(keys,
        vals)`` -- registered with psycopg. None for any other type."""
        plsql = self._plsql_type(pg_oid)
        if plsql is None:
            return None
        (owner, package, name, meta) = plsql
        oid = _object_type_oid(pg_oid)
        if meta.get('typecode') == 'PL/SQL RECORD':
            typ = DbObjectType(
                owner,
                name,
                oid,
                1,
                [
                    self._plsql_member(owner, f['name'], f['type'])
                    for f in meta['attrs']
                ],
                package_name=package,
            )
        elif meta.get('coll_type') == 'PL/SQL INDEX TABLE':
            typ = DbObjectType(
                owner,
                name,
                oid,
                1,
                [],
                is_collection=True,
                collection_type=COLLECTION_PLSQL_INDEX_TABLE,
                element=self._plsql_member(owner, None, meta['elem']),
                max_elements=0,
                package_name=package,
            )
        else:
            return None
        regtype = self._conn.execute(
            'SELECT %s::oid::regtype::text', (pg_oid,)
        ).fetchone()
        info = CompositeInfo.fetch(self._conn, regtype[0]) if regtype else None
        if info is None:
            return None
        register_composite(info, self._conn)
        return (typ, info)

    def _object_type(self, pg_oid: int) -> tuple[DbObjectType, CompositeInfo] | None:
        """The Oracle object type a PostgreSQL composite oid stands for (#1127).

        Built the way ``all_types`` / ``all_type_attrs`` build what a client
        reads, so the backend and the client agree on the OID and the attribute
        order.
        The composite is registered with psycopg on first use, so a value of it
        binds and loads as a tuple rather than its text form. None when the oid
        is not an object type.
        """
        if pg_oid in self._object_types:
            return self._object_types[pg_oid]
        # A package's record or index-by table (#1607).
        plsql = self._plsql_object_type(pg_oid)
        if plsql is not None:
            self._object_types[pg_oid] = plsql
            return plsql
        oid = _object_type_oid(pg_oid)
        # The catalogs rather than the sys views, though the answer is the same:
        # reading a view inside the session's open transaction holds a lock that
        # the next session's CREATE OR REPLACE VIEW at connect waits on, so a
        # new connection hung until this one committed.
        row = self._conn.execute(
            'SELECT sys.ora_owner(n.nspname), sys.ora_name(t.typname), '
            'n.nspname, t.typname '
            'FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace '
            'JOIN pg_class c ON c.oid = t.typrelid '
            "WHERE t.oid = %s AND t.typtype = 'c' AND c.relkind = 'c' "
            "AND t.typname !~ '[$]ref$'",
            (pg_oid,),
        ).fetchone()
        entry = None
        if row is not None:
            owner, name, pg_schema, pg_name = row
            attrs = []
            # information_schema is PostgreSQL's own, never replaced at connect,
            # so reading it holds nothing a new session waits on. The mapping is
            # the one all_type_attrs applies.
            for attr_name, type_name, type_owner, attr_type_oid in self._conn.execute(
                'SELECT sys.ora_name(a.attribute_name), '
                f"CASE WHEN a.attribute_udt_name = '{_TSTZ_TYPE}' "
                "THEN 'TIMESTAMP WITH TZ' "
                # The national types, told apart by their record (#1383).
                f"WHEN a.attribute_udt_name = '{_CLOB_TYPE}' "
                "AND o.data_type = 'NCLOB' THEN 'NCLOB' "
                "WHEN o.data_type IN ('NVARCHAR2', 'NCHAR', 'RAW', 'REAL', "
                "'DOUBLE PRECISION', 'FLOAT') THEN o.data_type "
                f"WHEN a.attribute_udt_name = '{_CLOB_TYPE}' THEN 'CLOB' "
                f"WHEN a.attribute_udt_name = '{_BLOB_TYPE}' THEN 'BLOB' "
                f"WHEN a.attribute_udt_name = '{_DATE_TYPE}' THEN 'DATE' "
                "WHEN a.data_type = 'USER-DEFINED' "
                'THEN sys.ora_name(a.attribute_udt_name) '
                "WHEN a.data_type = 'xml' THEN 'XMLTYPE' "
                "WHEN a.data_type = 'timestamp with time zone' "
                "THEN 'TIMESTAMP WITH LOCAL TZ' "
                'ELSE sys.ora_type_name(a.data_type) END, '
                "CASE WHEN a.data_type = 'xml' THEN 'SYS' "
                "WHEN a.data_type = 'USER-DEFINED' "
                'AND a.attribute_udt_name NOT IN '
                f"('{_TSTZ_TYPE}', '{_CLOB_TYPE}', '{_BLOB_TYPE}', '{_DATE_TYPE}') "
                'THEN sys.ora_owner(a.attribute_udt_schema) END, '
                "format('%%I.%%I', a.attribute_udt_schema, a.attribute_udt_name)"
                '::regtype::oid '
                'FROM information_schema.attributes a '
                + (
                    'LEFT JOIN sys.ora_columns o ON o.relid = '
                    "format('%%I.%%I', a.udt_schema, a.udt_name)::regclass "
                    'AND o.attnum = a.ordinal_position '
                    if self._has_column_catalog
                    else 'CROSS JOIN (SELECT NULL::text AS data_type) o '
                )
                + 'WHERE a.udt_schema = %s AND a.udt_name = %s '
                'ORDER BY a.ordinal_position',
                (pg_schema, pg_name),
            ):
                attr = {
                    'name': attr_name,
                    'type_name': type_name,
                    'data_type': type_name_to_tns(type_name),
                    # A client sends and expects an NVARCHAR2 attribute in
                    # AL16UTF16 inside the object image (#1383).
                    'charset': AL16UTF16_CHARSET
                    if type_name in ('NVARCHAR2', 'NCHAR')
                    else None,
                }
                if type_name == 'XMLTYPE':
                    # An XMLType attribute rides as an XMLType image (#1537).
                    attr['object_type'] = _XMLTYPE_DBTYPE
                elif type_owner is not None:
                    # An object or collection attribute carries its own type, as
                    # a client's describe embeds it, for the image walkers (#1265).
                    attr['object_type'] = self._nested_type(
                        attr_type_oid, f'{owner}.{name}', attr_name, type_name
                    )
                attrs.append(attr)
            regtype = self._conn.execute(
                'SELECT %s::oid::regtype::text', (pg_oid,)
            ).fetchone()
            info = CompositeInfo.fetch(self._conn, regtype[0]) if regtype else None
            if info is not None:
                register_composite(info, self._conn)
                entry = (DbObjectType(owner, name, oid, 1, attrs), info)
        self._object_types[pg_oid] = entry
        return entry

    def _nested_type(
        self, pg_oid: int, outer: str, attr_name: str, type_name: str
    ) -> DbObjectType:
        # The type of an attribute that is itself an object or a collection
        # (#1265). PostgreSQL refuses a composite that contains itself; the
        # guard is there should a domain ever let one through.
        if pg_oid in self._describing:
            raise UnsupportedFeature(
                f'object type {outer}: attribute {attr_name} refers back to it'
            )
        self._describing.add(pg_oid)
        try:
            kind = self._type_kind(pg_oid)
            if kind is not None and kind[0] == 'object':
                entry = self._object_type(pg_oid)
                if entry is not None:
                    return entry[0]
            if kind is not None and kind[0] == 'collection':
                coll = self._collection_type(pg_oid)
                if coll is not None:
                    return coll
        finally:
            self._describing.discard(pg_oid)
        raise UnsupportedFeature(
            f'object type {outer}: attribute {attr_name} is of type {type_name}, '
            'which is neither an object nor a collection type'
        )

    def _nested_value(self, attr: dict, value: object) -> object:
        # A fetched object or collection attribute as its DbObject (#1265); any
        # other attribute passes through.
        nested = attr.get('object_type')
        if nested is None or value is None or nested is _XMLTYPE_DBTYPE:
            # An XMLType attribute's value is its document's text (#1537).
            return value
        pg_oid = _pg_oid_of(nested.oid) or 0
        if nested.is_collection:
            base = self._conn.execute(
                'SELECT typbasetype FROM pg_type WHERE oid = %s', (pg_oid,)
            ).fetchone()
            return self._db_collection(nested, value, base[0] if base else 0)
        entry = self._object_type(pg_oid)
        if entry is None:
            raise UnsupportedFeature(f'object type {nested.name}: not found')
        return self._db_object(entry[0], entry[1], value)

    def _db_object(
        self, typ: DbObjectType, info: CompositeInfo, value: object
    ) -> object:
        # One composite cell as the DbObject the Mirror encodes. A cursor that
        # executed before the composite was registered hands the text form
        # `(7,Alice)`; the registered loader parses that the way psycopg would.
        if value is None:
            return None
        if isinstance(value, str):
            loader = self._conn.adapters.get_loader(info.oid, psycopg.pq.Format.TEXT)
            if loader is None:
                raise UnsupportedFeature(f'object type {typ.name}: no loader')
            value = loader(info.oid, self._conn).load(value.encode('utf-8'))
        if not isinstance(value, tuple):
            raise UnsupportedFeature(f'object type {typ.name}: not a composite value')
        if typ.is_collection:
            # A package's index-by table (#1607): its keys and its values, the
            # values in key order, an element of a named type as its object.
            (keys, vals) = value
            element = typ.element or {}
            vals = [self._nested_value(element, v) for v in (vals or [])]
            return typ.newobject(vals, keys=list(keys or []))
        return typ.newobject(
            {
                a['name']: _reconstruct_tstz(v)
                if a['data_type'] == TNS_TYPE_TIMESTAMPTZ and hasattr(v, 'utc')
                # A LOCAL TIME ZONE attribute goes out as a column of it does:
                # the instant in the database time zone, naive (#1208, #1270).
                else _to_ltz(v)
                if a['data_type'] == TNS_TYPE_TIMESTAMPLTZ
                else self._nested_value(a, v)
                for a, v in zip(typ.attrs, value)
            }
        )

    def _ref_cell(self, type_pg_oid: int, value: object) -> DbRef | None:
        # A `<type>$ref` cell: a tuple once the composite is registered, its text
        # form `(16842,1c4e...)` before -- both carry the table oid and row id.
        if value is None:
            return None
        if isinstance(value, str):
            tab, _, rid = value.strip('()').partition(',')
            value = (int(tab) if tab else None, rid or None)
        if not isinstance(value, tuple):
            raise UnsupportedFeature('REF column: not a composite value')
        return self._db_ref(type_pg_oid, value[0], value[1])

    def _resolve_object_binds(self, binds: Sequence) -> list:
        # An object (ADT) bind arrives as the image the client packed, bare or
        # in a BindVar. Decode it against the type the OID names and bind the
        # composite; a NULL object arrived as None already (#1127).
        out: list = []
        for b in binds:
            value = b.value if isinstance(b, BindVar) else b
            if isinstance(value, ObjectImage):
                out.append(self._object_bind_value(value))
            elif isinstance(value, DbRef):
                out.append(self._ref_bind_value(value))
            elif (
                isinstance(b, BindVar)
                and value is None
                and b.tns_type == TNS_TYPE_ADT
                and (typed := self._null_object_type(b.toid)) is not None
            ):
                out.append(replace(b, value=_TypedNull(typed)))
            else:
                out.append(b)
        return out

    def _null_object_type(self, toid: bytes) -> int | None:
        # The PostgreSQL type of a NULL object bind, from the type OID its OAC
        # carries (#1622): one of our object or collection types, else None.
        oid = toid[4:20] if len(toid) >= 20 else toid
        pg_oid = _pg_oid_of(oid)
        if pg_oid is None:
            return None
        if self._collection_type(pg_oid) is None and self._object_type(pg_oid) is None:
            return None
        return pg_oid

    def _object_bind_value(self, image: ObjectImage) -> object:
        oid = image.type_oid or b''
        # A value's toid is the constructed 36-byte form (00 22 02 08 + OID +
        # extent); the OAC carries the bare 16-byte OID. Accept either.
        if len(oid) >= 20:
            oid = oid[4:20]
        pg_oid = _pg_oid_of(oid)
        coll = self._collection_type(pg_oid) if pg_oid is not None else None
        if coll is not None:
            array = self._collection_bind_value(coll, image)
            row = self._conn.execute(
                'SELECT %s::oid::regtype::text', (pg_oid,)
            ).fetchone()
            return _CollectionBind(array, row[0]) if row else array
        entry = self._object_type(pg_oid) if pg_oid is not None else None
        if entry is None:
            raise UnsupportedFeature(
                f'object bind: no object type has the OID {oid.hex()}'
            )
        typ = entry[0]
        if typ.is_collection:
            # A package's index-by table (#1607): its elements under their keys.
            (elements, keys) = decode_collection_keyed(
                image.image, typ.element or {}, AL32UTF8_CHARSET
            )
            values = _served_lobs(typ.newobject(elements, keys=keys), image).aslist()
            return self._index_table_value(
                entry, values, keys if keys is not None else []
            )
        value = _served_lobs(
            DbObject(typ.name, decode_object_image(image.image, typ.attrs), dbtype=typ),
            image,
        )
        return self._composite_value(entry, value.asdict())

    def _index_table_value(
        self, entry: tuple[DbObjectType, CompositeInfo], values: list, keys: list
    ) -> object:
        # A package's index-by table as the composite it is stored as (#1607):
        # its keys and its values, an element of a named type as its composite.
        (typ, info) = entry
        factory = info.python_type
        if factory is None:
            raise UnsupportedFeature(f'collection type {typ.name}: not registered')
        return factory(list(keys), self._collection_values(typ, values))

    def _collection_bind_value(
        self, typ: DbObjectType, image: ObjectImage
    ) -> list | str:
        # A VARRAY / nested-table bind (#1206): the image's elements, bound as the
        # array the domain is over; an object element as its composite.
        element = typ.element or {}
        values = _served_lobs(
            typ.newobject(decode_collection_image(image.image, element)), image
        ).aslist()
        return self._collection_values(typ, values)

    def _collection_values(self, typ: DbObjectType, values: list) -> list | str:
        # A collection's elements as the array its domain is over: an object
        # element as its composite, a NUMBER list all one Python type.
        element = typ.element or {}
        nested = element.get('object_type')
        if nested is _XMLTYPE_DBTYPE:
            # XMLType elements bind as their documents' text (#1537).
            return values
        if nested is not None and nested.is_collection:
            # A collection of collections (#1276): psycopg would bind a list of
            # lists as a rectangular multi-dimensional array, which the domain
            # refuses, so the value goes as an array literal PostgreSQL casts.
            return _array_literal(
                [None if v is None else _array_literal(v.aslist()) for v in values]
            )
        if nested is None:
            # A NUMBER decodes as an int when it is whole and a Decimal when not,
            # and psycopg binds no list that mixes the two.
            if any(isinstance(v, decimal.Decimal) for v in values):
                values = [
                    decimal.Decimal(v)
                    if isinstance(v, int) and not isinstance(v, bool)
                    else v
                    for v in values
                ]
            return values
        entry = self._object_type(_pg_oid_of(nested.oid) or 0)
        if entry is None:
            raise UnsupportedFeature(f'collection type {typ.name}: no element type')
        return [
            None if v is None else self._composite_value(entry, v.asdict())
            for v in values
        ]

    def _composite_value(
        self, entry: tuple[DbObjectType, CompositeInfo], attrs: dict
    ) -> object:
        # An object's attribute values as the registered composite psycopg binds.
        typ, info = entry
        factory = info.python_type  # set by register_composite
        if factory is None:
            raise UnsupportedFeature(f'object type {typ.name}: not registered')
        return factory(
            *(
                self._tstz_composite(attrs.get(a['name']))
                if a['data_type'] == TNS_TYPE_TIMESTAMPTZ
                else _from_ltz(attrs.get(a['name']))
                if a['data_type'] == TNS_TYPE_TIMESTAMPLTZ
                else self._nested_bind_value(a, attrs.get(a['name']))
                for a in typ.attrs
            )
        )

    def _nested_bind_value(self, attr: dict, value: object) -> object:
        # A bound object or collection attribute (#1265), already decoded into a
        # DbObject, as the composite or array PostgreSQL stores; any other
        # attribute passes through.
        nested = attr.get('object_type')
        if nested is None or not isinstance(value, DbObject):
            return value
        if nested.collection_type == COLLECTION_PLSQL_INDEX_TABLE:
            # A package's index-by table inside a record (#1607).
            entry = self._object_type(_pg_oid_of(nested.oid) or 0)
            if entry is not None:
                return self._index_table_value(
                    entry, value.aslist(), list(value._keys or [])
                )
        if nested.is_collection:
            return self._collection_values(nested, value.aslist())
        entry = self._object_type(_pg_oid_of(nested.oid) or 0)
        if entry is None:
            raise UnsupportedFeature(f'object type {nested.name}: not found')
        return self._composite_value(entry, value.asdict())

    def _tstz_composite(self, value: object) -> object:
        # An aware datetime as the ora_tstz composite a TIMESTAMP WITH TIME ZONE
        # attribute is stored as: the instant and the offset it was entered at
        # (#519). A naive one is taken as UTC.
        if not isinstance(value, datetime.datetime) or self._tstz_info is None:
            return value
        factory = self._tstz_info.python_type
        if factory is None:
            return value
        offset = value.utcoffset() or datetime.timedelta(0)
        instant = (
            value
            if value.tzinfo is not None
            else value.replace(tzinfo=datetime.timezone.utc)
        )
        return factory(
            instant.astimezone(datetime.timezone.utc), int(offset.total_seconds())
        )

    def _execute_sequential(
        self,
        sql: str,
        params: dict | None,
        original: str | None = None,
        *,
        prelude: str | None = None,
    ) -> Result:
        # SAVEPOINT + statement + RELEASE as three round-trips; the fallback path.
        # A `prelude` runs inside the savepoint first, in its round trip (#1915),
        # so a SET LOCAL there is undone with a statement that fails and ends
        # with one that commits.
        # An our-side rejection after the statement ran (UnsupportedFeature on an
        # unmapped column type) is undone too, and left for the session to map.
        cursor = self._conn.cursor()
        try:
            with self._under_savepoint(then=prelude):
                cursor.execute(sql, params)
                result = self._build_result(cursor, sql, original or '', params)
        except psycopg.Error as exc:
            # A PostgreSQL failure surfaces as a clean ORA error — never a desync.
            # Map the SQLSTATE to the matching Oracle code so error-conditional
            # client flows (e.g. a best-effort DROP that swallows ORA-00942) work.
            raise _backend_error(exc, original=original, translated=sql) from exc
        return result

    def _execute_pipelined(
        self,
        sql: str,
        params: dict | None,
        original: str | None = None,
        fallback: str | None = None,
    ) -> Result:
        # SAVEPOINT + statement + RELEASE shipped in ONE round-trip via a psycopg
        # pipeline. Each command uses its own cursor so the statement's cursor keeps
        # its own result (rowcount / description / rows / pgresult) after the sync —
        # a shared cursor would only retain the last command's (RELEASE) result.
        # The transaction id check rides along too, for releasing the read
        # locks of a query (#1190) without a round trip of its own (#1869).
        # A statement rewritten from the schema runs behind a guard that the
        # schema is still the one it was read at; when another session's DDL
        # came first, it runs as `fallback`, its text before the rewrite
        # (#1889).
        if (
            self._conn.info.transaction_status == psycopg.pq.TransactionStatus.IDLE
            and not self._user_savepoint
            and not self._conn.prelude
        ):
            masked = _masked_quoted(sql)[0]
            if _PLAIN_QUERY.match(masked) and not _NOT_A_PLAIN_QUERY.search(masked):
                result = self._query_at_once(sql, params, original, fallback)
                if result is not None:
                    return result
        begin = self._conn.cursor()
        savepoint = self._conn.cursor()
        guard = self._conn.cursor()
        statement = self._conn.cursor()
        release = self._conn.cursor()
        written = self._conn.cursor()
        self._conn.unwritten_at = None
        idle = self._conn.info.transaction_status == psycopg.pq.TransactionStatus.IDLE
        if idle:
            self._conn.autocommit = True
        try:
            with self._conn.pipeline():
                if idle:
                    # The transaction this statement opens, in its round trip
                    # (#1915).
                    self._conn.begin_in_pipeline(begin)
                savepoint.execute('SAVEPOINT _mirror_stmt')
                if fallback is not None:
                    guard.execute(
                        'SELECT sys.ora_ddl_unchanged(%s)', (self._ddl_generation,)
                    )
                statement.execute(sql, params)
                release.execute('RELEASE SAVEPOINT _mirror_stmt')
                written.execute(
                    _WRITTEN_CHECK + ', ' + _DDL_GENERATION
                    if self._has_ddl_log
                    else _WRITTEN_CHECK
                )
        except psycopg.Error as exc:
            # The statement failed inside the pipeline; the RELEASE that followed it
            # was discarded, so the savepoint still stands — roll the statement back
            # to it (preserving the rest of the transaction) and surface a clean ORA
            # error, never a desync.
            self._conn.execute('ROLLBACK TO SAVEPOINT _mirror_stmt')
            self._conn.execute('RELEASE SAVEPOINT _mirror_stmt')
            if fallback is not None and exc.sqlstate == _SCHEMA_CHANGED:
                return self._execute_pipelined(fallback, params, original)
            raise _backend_error(exc, original=original, translated=sql) from exc
        row = written.fetchone()
        self._conn.unwritten_at = (
            row is not None and bool(row[0]),
            self._conn.statements,
        )
        if self._has_ddl_log and row is not None:
            # Another session's DDL committed since the last statement: what
            # this session knows of the schema may be stale (#1887). The first
            # generation seen only sets the mark.
            if self._ddl_generation not in (None, row[1]):
                self._forget_schema()
            self._ddl_generation = row[1]
        # The pipeline succeeded, so the savepoint is already released and the
        # statement had its effect. Building the result can only raise on an
        # unencodable SELECT column — no side effect to undo — so let it propagate
        # for the session to map to an ORA error; the connection stays usable.
        return self._build_result(statement, sql, original or '', params)

    def _query_at_once(
        self,
        sql: str,
        params: dict | None,
        original: str | None,
        fallback: str | None,
    ) -> Result | None:
        # A query with no transaction open, in one round trip (#1916): in
        # autocommit, with no BEGIN, SAVEPOINT or COMMIT around it. The
        # pipeline's own implicit transaction ends at its sync, which lets the
        # query's read locks go (#1190) as the commit after it did; the DDL
        # generation (#1887) rides along. A failure leaves nothing to roll
        # back, the transaction being the statement's alone. None when a
        # result column is a REF CURSOR, whose portal ended with the
        # transaction: the caller runs the query again in one.
        guard = self._conn.cursor()
        statement = self._conn.cursor()
        generation = self._conn.cursor()
        self._conn.autocommit = True
        try:
            with self._conn.pipeline():
                # Not the query first: psycopg keeps the name of a statement
                # that failed as it prepared it first in a pipeline, which the
                # server never kept, and the next run fails on it.
                generation.execute(
                    'SELECT ' + _DDL_GENERATION if self._has_ddl_log else 'SELECT NULL'
                )
                if fallback is not None:
                    guard.execute(
                        'SELECT sys.ora_ddl_unchanged(%s)', (self._ddl_generation,)
                    )
                statement.execute(sql, params)
        except psycopg.Error as exc:
            # The failed pipeline's implicit transaction is still open, aborted:
            # end it, so the session is as it was before the query.
            self._conn.rollback()
            self._conn.autocommit = False
            if fallback is not None and exc.sqlstate == _SCHEMA_CHANGED:
                return self._execute_pipelined(fallback, params, original)
            if isinstance(exc, psycopg.errors.FeatureNotSupported):
                # A prepared plan another session's DDL changed the shape of
                # (#1885): the transactional path recovers from it.
                return None
            raise _backend_error(exc, original=original, translated=sql) from exc
        self._conn.autocommit = False
        if any(
            desc.type_code == _REFCURSOR_OID for desc in statement.description or ()
        ):
            return None
        self._conn.unwritten_at = (True, self._conn.statements)
        if self._has_ddl_log:
            row = generation.fetchone()
            if row is not None and row[0] is not None:
                if self._ddl_generation not in (None, row[0]):
                    self._forget_schema()
                self._ddl_generation = row[0]
        return self._build_result(statement, sql, original or '', params)

    @_while_connected
    @_plainly_quoted
    def execute_many(self, sql: str, rows: Sequence[Sequence]) -> int | Result:
        # One run of the statement in the translation report, however many rows.
        (sql, rows) = _occurrence_binds(sql, rows)
        return self._committing(
            lambda: self._reported(sql, lambda: self._execute_batch(sql, rows))
        )

    def _execute_batch(self, sql: str, rows: Sequence[Sequence]) -> int | Result:
        # Array DML (executemany) in one round-trip: translate the statement once
        # and send every bind row through psycopg's executemany (which pipelines),
        # instead of a round-trip per row — the difference is ~7 s vs a few ms for
        # 500 rows against a remote database. Returns the total affected-row count.
        # The Mirror calls this only for the non-batcherrors path, where a per-row
        # failure aborts the whole batch — exactly Oracle's non-batcherrors DML.
        rows = [
            self._boolean_binds(
                sql, self._vector_text_binds(sql, self._oson_binds(sql, row))
            )
            for row in rows
        ]
        native = self._is_native(sql)
        if not native:
            sql = self._to_raw_targets(
                self._expand_visible_columns(_strip_leading_comments(sql))
            )
        rows = list(rows)
        if not rows:
            return 0
        translated = sql if native else _translated_batch(sql)
        with_rowid = None if native else self._returning_rowid(sql, translated)
        if with_rowid is not None:
            translated = with_rowid
        bound_sql, _ = _translate_binds(translated, rows[0])
        params = [_translate_binds(translated, row)[1] for row in rows]
        self._last_translated = bound_sql
        cursor = self._conn.cursor()
        touched: list = []
        try:
            with self._under_savepoint():
                if with_rowid is None:
                    cursor.executemany(bound_sql, params)
                    affected = cursor.rowcount
                else:
                    # One result per iteration, each the rowids that row touched;
                    # the batch's count is all of them, its rowid the very last.
                    cursor.executemany(bound_sql, params, returning=True)
                    while True:
                        touched.extend(cursor.fetchall())
                        if not cursor.nextset():
                            break
                    affected = len(touched)
        except psycopg.Error as exc:
            # Oracle undoes only the row that failed: the rows before it stay
            # applied, and the error's rowcount says how many there were. The
            # pipelined batch cannot tell which row failed, and its savepoint
            # undid them all, so replay the rows one at a time up to the failure
            # (#1365).
            raise self._replay_until_failure(bound_sql, params) from exc
        if with_rowid is not None:
            return Result(
                rowcount=affected,
                last_rowid=_dml_rowid(*touched[-1]) if touched else None,
            )
        return max(affected, 0)

    def _replay_until_failure(self, bound_sql: str, params: list) -> BackendError:
        # Run the rows of a batch that failed one at a time, each in a savepoint
        # of its own, until one fails; that one is undone and the rest are kept.
        # The failing row's error comes back carrying how many rows were
        # applied before it, which is what Oracle reports for a batch that stops
        # part-way (#998, #1365). Not the per-iteration counts: this path serves
        # a client that did not ask for them (that one is execute_many_rowcounts),
        # and a count block it did not ask for is a reply it cannot read.
        cursor = self._conn.cursor()
        cursor.execute('SAVEPOINT _mirror_replay')
        applied = 0
        for row in params:
            try:
                with self._under_savepoint('_mirror_row'):
                    cursor.execute(bound_sql, row)
            except psycopg.Error as exc:
                self._conn.execute('RELEASE SAVEPOINT _mirror_replay')
                err = _backend_error(exc)
                err.rowcount = applied
                return err
            applied += max(cursor.rowcount, 0)
        # The batch failed and no single row does: a failure only the batch as a
        # whole met. Nothing is left applied.
        self._conn.execute('ROLLBACK TO SAVEPOINT _mirror_replay')
        self._conn.execute('RELEASE SAVEPOINT _mirror_replay')
        return BackendError('the array statement failed', rowcount=0)

    @_while_connected
    @_plainly_quoted
    def execute_many_rowcounts(
        self, sql: str, rows: Sequence[Sequence]
    ) -> tuple[int, list[int]]:
        (sql, rows) = _occurrence_binds(sql, rows)
        return self._reported(sql, lambda: self._execute_batch_rowcounts(sql, rows))

    def _execute_batch_rowcounts(
        self, sql: str, rows: Sequence[Sequence]
    ) -> tuple[int, list[int]]:
        """Array DML reporting the per-iteration affected-row counts (#18).

        The Mirror calls this only when the client asked for
        ``arraydmlrowcounts`` and did not ask for batcherrors, so the cost here
        is opt-in.

        Row by row, rather than through ``executemany`` -- and deliberately,
        because Oracle's semantics for a batch that ABORTS are what decide it.
        The rows before the failing one really applied and their counts are owed
        to the client in the error reply, so the batch cannot sit inside one
        savepoint: rolling that back would undo them. Each iteration gets its own
        savepoint instead, which is the same per-statement model the rest of this
        backend uses, and leaves the earlier rows exactly where Oracle leaves
        them.

        (``executemany(..., returning=True)`` does report per-statement counts
        through ``nextset()`` and keeps the pipeline, which would be faster. It
        cannot serve the abort case: once the batch raises, the counts for the
        rows that did apply are no longer reachable.)
        """
        rows = [
            self._boolean_binds(
                sql, self._vector_text_binds(sql, self._oson_binds(sql, row))
            )
            for row in rows
        ]
        rows = list(rows)
        if not rows:
            return 0, []
        translated = (
            sql
            if self._is_native(sql)
            else _translated_batch(self._to_raw_targets(sql))
        )
        bound_sql, _ = _translate_binds(translated, rows[0])
        cursor = self._conn.cursor()
        counts: list[int] = []
        total = 0
        for row in rows:
            _, params = _translate_binds(translated, row)
            try:
                with self._under_savepoint():
                    cursor.execute(bound_sql, params)
            except psycopg.Error as exc:
                error = _backend_error(exc, original=sql, translated=bound_sql)
                # What applied before the failure, and how much of it per
                # iteration: a client that asked for the counts is owed them in
                # the ERROR reply as much as in a successful one (#1031).
                error.rowcount = total
                error.row_counts = counts
                raise error from exc
            affected = max(cursor.rowcount, 0)
            counts.append(affected)
            total += affected
        return total, counts

    def _object_table_type(self, table: str) -> int | None:
        # The pg_type oid of an Oracle object table's type (CREATE TABLE t OF
        # type), from the registry the CREATE filled; None for any other table.
        row = self._conn.execute(
            'SELECT o.typ FROM sys.ora_object_tables o '
            'WHERE o.relid = sys.ora_regclass(%s)',
            (table,),
        ).fetchone()
        return None if row is None else int(row[0])

    def _ref_identity(self, type_pg_oid: int) -> tuple[str, str]:
        # (schema, name) of the object type a REF points at, as all_types has it.
        row = self._conn.execute(
            'SELECT sys.ora_owner(n.nspname), sys.ora_name(t.typname) '
            'FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace '
            'WHERE t.oid = %s',
            (type_pg_oid,),
        ).fetchone()
        if row is None:
            raise UnsupportedFeature(f'REF: no object type has pg oid {type_pg_oid}')
        return row[0], row[1]

    def _db_ref(
        self, type_pg_oid: int, table_oid: int | None, row_id: object
    ) -> DbRef | None:
        # A REF value for the client: the private locator plus the identity of
        # the type it points at, which the describe and the value both carry.
        if table_oid is None or row_id is None:
            return None
        schema, name = self._ref_identity(type_pg_oid)
        return DbRef(
            _ref_locator(type_pg_oid, table_oid, row_id),
            type_name=name,
            type_schema=schema,
            type_oid=_object_type_oid(type_pg_oid),
        )

    def _execute_ref_select(self, match: 're.Match[str]') -> Result:
        # Serve `SELECT REF(alias) FROM table alias [rest]` (#139/#1127). The
        # table must be an Oracle object table; each row's REF is its table oid
        # and hidden object id, which stay put across UPDATE and VACUUM FULL.
        ref_alias, table, table_alias, rest = match.groups()
        type_pg_oid = self._object_table_type(table)
        if type_pg_oid is None:
            raise UnsupportedFeature(
                f'REF({ref_alias}): {table} is not an object table'
            )
        query = (
            f'SELECT {table_alias}.tableoid, {table_alias}.{_OBJECT_ID_COLUMN} '
            f'FROM {table} {table_alias}{rest}'
        )
        try:
            with self._under_savepoint():
                found = self._conn.execute(query).fetchall()
        except psycopg.Error as exc:
            raise _backend_error(exc) from exc
        rows = [(self._db_ref(type_pg_oid, tab, rid),) for tab, rid in found]
        column = self._ref_column_meta(f'REF({ref_alias})', type_pg_oid)
        return Result(columns=[column], rows=rows)

    def _ref_column_meta(self, name: str, type_pg_oid: int) -> ColumnMeta:
        schema, type_name = self._ref_identity(type_pg_oid)
        return ColumnMeta(
            name=name.upper().encode('utf-8'),
            data_type=TNS_TYPE_REF,
            data_length=4000,
            max_size=0,
            type_name=type_name.encode('ascii'),
            type_schema=schema.encode('ascii'),
            type_oid=_object_type_oid(type_pg_oid),
        )

    def _learn_types(self, oids: set[int]) -> None:
        # Whether each of these result types is an array (#1206) and what a
        # `<type>$ref` companion's target is (#1127), read together in one query
        # for the types not yet known; a builtin scalar is neither.
        unknown = [
            oid
            for oid in oids - _BUILTIN_OIDS
            if oid not in self._array_oids or oid not in self._ref_targets
        ]
        for oid in oids & _BUILTIN_OIDS:
            self._array_oids[oid] = False
        if not unknown:
            return
        found = {
            row[0]: row[1:]
            for row in self._catalog_read(
                "SELECT t.oid, t.typcategory = 'A', target.oid FROM pg_type t "
                "LEFT JOIN pg_type target ON t.typname ~ '[$]ref$' "
                'AND target.typnamespace = t.typnamespace '
                "AND target.typname || '$ref' = t.typname WHERE t.oid = ANY(%s)",
                (unknown,),
            ).fetchall()
        }
        for oid in unknown:
            is_array, target = found.get(oid, (False, None))
            self._array_oids[oid] = bool(is_array)
            self._ref_targets[oid] = None if target is None else int(target)

    def _ref_target(self, pg_oid: int) -> int | None:
        # For a `<type>$ref` companion composite, the pg_type oid of <type>;
        # None for any other type. Cached per session.
        if pg_oid in self._ref_targets:
            return self._ref_targets[pg_oid]
        row = self._conn.execute(
            'SELECT target.oid FROM pg_type ref '
            'JOIN pg_type target ON target.typnamespace = ref.typnamespace '
            "AND target.typname || '$ref' = ref.typname "
            "WHERE ref.oid = %s AND ref.typname ~ '[$]ref$'",
            (pg_oid,),
        ).fetchone()
        target = None if row is None else int(row[0])
        self._ref_targets[pg_oid] = target
        return target

    def _ref_bind_value(self, ref: DbRef) -> object:
        # A REF the client binds is the locator this backend handed it; it
        # becomes the `<type>$ref` composite the column / sys.deref() take.
        parsed = _parse_ref_locator(ref.bytes)
        if parsed is None:
            raise UnsupportedFeature('REF bind: not a locator this backend issued')
        type_pg_oid, table_oid, row_id = parsed
        info = self._ref_composites.get(type_pg_oid)
        if info is None:
            named = self._conn.execute(
                "SELECT format('%%I.%%I', n.nspname, t.typname || '$ref') "
                'FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace '
                'WHERE t.oid = %s',
                (type_pg_oid,),
            ).fetchone()
            if named is None:
                raise UnsupportedFeature(f'REF bind: no type with pg oid {type_pg_oid}')
            ref_name = named[0]
            info = CompositeInfo.fetch(self._conn, ref_name)
            if info is None:
                raise UnsupportedFeature(f'REF bind: no {ref_name} type')
            register_composite(info, self._conn)
            self._ref_composites[type_pg_oid] = info
        factory = info.python_type
        if factory is None:
            raise UnsupportedFeature('REF bind: companion type not registered')
        return factory(table_oid, row_id)

    def _domain_type(self, pgresult, index: int) -> int | None:
        # The Oracle wire type if result column `index` comes from one of the typed
        # domains — TNS_TYPE_CLOB / TNS_TYPE_BLOB (ora_clob / ora_blob, #534) or
        # TNS_TYPE_INTERVALYM (ora_intervalym, #504) — else None. A domain value
        # reports its base type on the wire (text / bytea / interval), so trace the
        # column back to its source table + attribute (libpq ftable / ftablecol) and
        # take the real declared type from the schema model (#1887). A computed
        # column (ftable 0) isn't a domain column.
        if not self._domain_type_by_oid:
            return None
        column = self._table_columns(pgresult, [index]).get(index)
        return self._domain_type_by_oid.get(column.type_oid) if column else None

    def _returns_a_value(self, name: str) -> bool:
        # Whether every function of this name returns a value of its own: not
        # void, and not the record a function with OUT parameters returns.
        rows = self._conn.execute(
            "SELECT prorettype = 'void'::regtype OR proargmodes IS NOT NULL "
            "FROM pg_proc WHERE proname = lower(%s) AND prokind = 'f'",
            (name.rsplit('.', 1)[-1],),
        ).fetchall()
        return bool(rows) and not any(procedure_like for (procedure_like,) in rows)

    def _routine_arities(self, name: str) -> set[int]:
        # How many arguments a routine of this name takes, each overload and
        # each count its defaults allow (#1497).
        rows = self._conn.execute(
            'SELECT pronargs, pronargdefaults FROM pg_proc WHERE proname = lower(%s)',
            (name,),
        ).fetchall()
        return {
            n for nargs, ndefaults in rows for n in range(nargs - ndefaults, nargs + 1)
        }

    def _execute_plsql(self, sql: str, binds: Sequence) -> Result:
        # A call that fails undoes only itself (#1632): the caller's open work
        # survives it, as it survives any other statement that fails, where a
        # rollback of the whole transaction took it too.
        # The savepoint rides with the call's first statement, and its release
        # with the next statement after the call (#1875). A savepoint still
        # waiting when the call ends was never taken.
        self._conn.prelude += (_CALL_SAVEPOINT,)
        try:
            result = self._execute_plsql_call(sql, binds)
        except BaseException:
            # Unless the call ended the transaction itself, and the savepoint
            # with it.
            if self._taken_call_savepoint():
                self._conn.execute('ROLLBACK TO SAVEPOINT _mirror_call')
                self._conn.execute('RELEASE SAVEPOINT _mirror_call')
            raise
        if self._taken_call_savepoint():
            self._conn.prelude += ('RELEASE SAVEPOINT _mirror_call',)
        return result

    def _taken_call_savepoint(self) -> bool:
        # Whether a PL/SQL call's savepoint was taken and still stands, and
        # the prelude that would take it dropped (#1875).
        if _CALL_SAVEPOINT in self._conn.prelude:
            self._conn.prelude = tuple(
                s for s in self._conn.prelude if s != _CALL_SAVEPOINT
            )
            return False
        return self._conn.info.transaction_status in _OPEN_TRANSACTION

    def _execute_plsql_call(self, sql: str, binds: Sequence) -> Result:
        # A callproc / callfunc block. `binds` is one BindVar per positional bind
        # (:1 → index 0), value None for a pure OUT. Run the underlying routine and
        # return every bind's value in order (input for IN, the routine's result
        # for OUT / IN OUT / the function return) — the Mirror marks them all OUT
        # and the client keeps only the positions it bound as a Var (#483/#503).
        if _TYPE_SHAPE_BLOCK.search(sql):
            return self._execute_type_shape(sql, binds)
        # An object or collection bind arrives as the image the client packed:
        # decoded against its type, as a statement's is (#1607). A collection
        # goes as its array: a CALL takes the parameter's type from the routine.
        given = [b.value if isinstance(b, BindVar) else b for b in binds]
        values = [
            v.value if isinstance(v, (BindVar, _CollectionBind)) else v
            for v in self._resolve_object_binds(binds)
        ]
        result = self._execute_plsql_values(sql, binds, values)
        # A bind that comes back as it went in goes back as the client sent it:
        # an object's image as the object it is, not the composite it was
        # decoded into -- every bind of a block goes back (#1607).
        out: list = []
        for at, value in enumerate(result.out_binds):
            sent = given[at] if at < len(values) and value is values[at] else None
            if isinstance(value, _PortalName):
                # The portal a client's cursor bound IN was opened as (#1634):
                # nothing to report, which the Mirror answers as the closed
                # cursor a routine leaves (#1048). As text it garbled the reply.
                out.append(None)
            elif isinstance(sent, ObjectImage):
                out.append(self._image_object(sent))
            elif at < len(values) and value is values[at]:
                out.append(given[at])
            else:
                out.append(value)
        return replace(result, out_binds=out)

    def _image_object(self, image: ObjectImage) -> object:
        # A bound object's or collection's image as its DbObject (#1607).
        oid = image.type_oid or b''
        if len(oid) >= 20:
            oid = oid[4:20]
        pg_oid = _pg_oid_of(oid)
        coll = self._collection_type(pg_oid) if pg_oid is not None else None
        if coll is not None:
            return coll.newobject(
                decode_collection_image(image.image, coll.element or {})
            )
        entry = self._object_type(pg_oid) if pg_oid is not None else None
        if entry is None:
            return None
        typ = entry[0]
        if typ.is_collection:
            (elements, keys) = decode_collection_keyed(
                image.image, typ.element or {}, AL32UTF8_CHARSET
            )
            return typ.newobject(elements, keys=keys)
        return DbObject(
            typ.name, decode_object_image(image.image, typ.attrs), dbtype=typ
        )

    def _execute_plsql_values(self, sql: str, binds: Sequence, values: list) -> Result:
        # _execute_plsql's work, with the binds' values decoded.
        inner = _CALL_BLOCK.match(sql)
        statement = inner.group(1) if inner else ''
        try:
            # A block of several statements is none of the one-statement shapes
            # below, which would each take its first statement for the whole:
            # a block, its binds its locals, so each statement reads and writes
            # them in turn (#1723).
            if inner is not None and _several_statements(statement):
                return self._run_block(sql, binds)
            func = _FUNC_CALL.match(statement)
            # Only a call whose arguments are all binds goes the direct-SELECT
            # route: it threads each bind value onto a %s by position. A literal
            # or expression argument (`:r := RPAD('o', 4000, 'p')`, #2337) has no
            # placeholder, so that route dropped it -- building a zero- or
            # wrong-arity call, which PostgreSQL's overloaded resolution refused
            # and the error mapped to PLS-00306. Such a call falls through to the
            # out-assignment path, which evaluates the whole right-hand side (its
            # literals kept, its Oracle idioms translated) in one SELECT.
            if func is not None and _call_arguments(func.group(3)) is not None:
                return self._call_function(func, values, sql)
            proc = _PROC_CALL.match(statement)
            if proc is not None:
                return self._call_procedure(proc, values, sql, binds)
            # Not a call: a block that opens a REF CURSOR into a bind (#1456),
            # or one with a VECTOR bind, which only a block's local holds (#1737).
            if any(
                isinstance(b, BindVar)
                and b.tns_type in (TNS_TYPE_REFCURSOR, TNS_TYPE_VECTOR)
                for b in binds
            ):
                return self._run_block(sql, binds)
            assignments = _parse_out_assignments(statement)
            if assignments is not None:
                return self._eval_out_assignments(statement, assignments, binds, values)
            select_into = _SELECT_INTO.match(statement)
            if select_into is not None:
                return self._select_into(select_into, values)
            if inner is not None:
                # A block wrapping DML (BEGIN INSERT/UPDATE/DELETE …(:x); END) —
                # unwrap and run the inner statement with the binds.
                return self._run_block_statement(statement, values)
            # Not a shape the call paths model: a block, its binds its locals
            # (#1459).
            if _ANON_BLOCK.match(sql):
                return self._run_block(sql, binds)
            # Anything else runs as it is (best effort) so a side-effecting
            # statement still executes.
            self._conn.cursor().execute(_translate_idioms(sql))
            return Result(out_binds=values)
        except psycopg.Error as exc:
            # Undone first (#1632): naming the error reads the catalog for the
            # routine's arities, which a failed transaction refuses.
            self._conn.execute('ROLLBACK TO SAVEPOINT _mirror_call')
            raise _backend_error(
                exc, original=sql, arities=self._routine_arities
            ) from exc

    def _call_function(self, match: 're.Match', values: list, block: str) -> Result:
        # BEGIN :r := name(:a, :b); END;  →  SELECT name(a, b); the result is the
        # function's return value, written back into the :r bind position.
        ret_ref, name, args = match.groups()
        refused = _call_argument_error(block, name, args, None)
        if refused is not None:
            raise refused
        arguments = _call_arguments(args)
        if arguments is None:
            arguments = [
                (None, _placeholder_ref(m)) for m in _CALL_PLACEHOLDER.finditer(args)
            ]
        slots = _bind_slots(block)
        arg_values = [values[_placeholder_slot(slots, ref)] for _name, ref in arguments]
        arg_values = self._index_table_arguments(name, arg_values)
        cursor = self._conn.cursor()
        cursor.execute(
            f'SELECT {name}({_call_placeholders(arguments)}) FROM {_PLSQL_CALL_MARK}',
            tuple(arg_values) or None,
        )
        row = _decode_row(cursor, cursor.fetchone(), self._tstz_oid)
        out = list(values)
        returned = row[0] if row else None
        if cursor.description and returned is not None:
            # A record or index-by table returned is the object a client reads
            # (#1607).
            returned = self._object_out(cursor.description[0].type_code, returned)
        out[_placeholder_slot(slots, _placeholder_key(ret_ref))] = returned
        return Result(out_binds=out)

    def _index_table_arguments(
        self, name: str, values: list, types: Sequence[int] | None = None
    ) -> list:
        # A classic PL/SQL array bound to an index-by table parameter -- a list,
        # as cursor.arrayvar binds one -- as the table's composite, keyed 1..N
        # as Oracle keys it (#1607). The parameter's type is the routine's: the
        # one routine of that name and arity, or one each overload agrees on.
        if not any(isinstance(v, list) for v in values):
            return values
        if types is None:
            (schema, routine) = _pg_routine_name(name)
            candidates = self._conn.execute(
                'SELECT p.proargtypes::oid[] FROM pg_proc p JOIN pg_namespace n '
                'ON n.oid = p.pronamespace WHERE p.proname = %s '
                "AND (%s = '' OR n.nspname = %s) AND p.pronargs = %s",
                (routine, schema, schema, len(values)),
            ).fetchall()
        else:
            candidates = [(list(types),)]
        out = list(values)
        for at, value in enumerate(values):
            if not isinstance(value, list):
                continue
            kinds = {row[0][at] for row in candidates if row[0] and at < len(row[0])}
            if len(kinds) != 1:
                continue
            entry = self._object_type(next(iter(kinds)))
            if entry is not None and entry[0].collection_type == (
                COLLECTION_PLSQL_INDEX_TABLE
            ):
                out[at] = self._index_table_value(
                    entry, value, list(range(1, len(value) + 1))
                )
        return out

    def _object_out(
        self, type_oid: int, value: object, array: bool = False, toid: bytes = b''
    ) -> object:
        # An OUT or returned value of a record or index-by table type: the
        # object a client reads -- or, for a classic array bind, the table's
        # values in key order (#1607). Any other value as it is.
        if isinstance(value, (str, list)) and toid:
            # A collection the call returns (#1623) is built as the collection
            # the bind names: from its array's text when psycopg met the inner
            # collection's array type before it was registered, from the list
            # when it had been (a NULL bind of the type registers it, #1622).
            coll = self._collection_type(
                _pg_oid_of(toid[4:20] if len(toid) >= 20 else toid) or 0
            )
            if coll is not None:
                return self._db_collection(coll, value, type_oid)
        entry = (
            self._object_type(type_oid)
            if type_oid not in _BUILTIN_OIDS and type_oid != self._tstz_oid
            else None
        )
        if entry is None or not isinstance(value, (tuple, str)):
            return value
        if array and entry[0].is_collection and isinstance(value, tuple):
            return list(value[1] or [])
        return self._db_object(entry[0], entry[1], value)

    def _call_procedure(
        self, match: 're.Match', values: list, block: str, binds: Sequence = ()
    ) -> Result:
        # BEGIN name(:a, :b); END;  →  CALL name(a, b); the OUT / IN OUT arguments
        # come back as a result row, in parameter order, which we place onto their
        # bind positions.
        name, args = match.groups()
        arg_refs = [_placeholder_ref(m) for m in _CALL_PLACEHOLDER.finditer(args)]
        modes, argtypes, parameters, kind = self._proc_signature(name)
        refused = _call_argument_error(block, name, args, parameters or None)
        if refused is not None:
            raise refused
        if kind == 'f' and self._returns_a_value(name):
            # A function called as a procedure does not compile in Oracle:
            # PLS-00221 (#1497). A function that returns nothing -- orafce's
            # DBMS_OUTPUT, say -- is a procedure there, and runs as one below.
            at = max(block.lower().find(name.lower()), 0)
            raise BackendError(
                f'line {block.count(chr(10), 0, at) + 1}, column '
                f'{at - block.rfind(chr(10), 0, at)}:\nPLS-00221: '
                f"'{name.rsplit('.', 1)[-1].upper()}' is not a procedure or is "
                'undefined',
                ora_code=ORA_PLSQL_COMPILATION_ERROR,
                error_offset=at,
            )
        slots = _bind_slots(block)
        # Which parameter each argument binds: by position, or by name (#1377). A
        # named argument the signature cannot place, or an argument that is not a
        # plain bind, leaves the call positional, as it always was.
        # Literals or expressions among the arguments go in as written, where
        # they used to be dropped and the routine called without them (#1531).
        arguments: list[tuple[str | None, int | str | _CallLiteral]]
        arguments = _call_items(args)
        lowered = [p.lower() for p in parameters]
        if any(n is not None and n not in lowered for n, _ref in arguments):
            arguments = [(None, ref) for ref in arg_refs]
        bound = {
            (lowered.index(n) if n is not None else position): ref
            for position, (n, ref) in enumerate(arguments)
        }
        # A pure-OUT argument carries no input — pass an untyped NULL, not the
        # client's placeholder Var value: a REF CURSOR Var marshals to bytea, which
        # makes CALL's overload resolution miss the refcursor parameter (#518). IN
        # and IN OUT arguments pass their value.
        arg_values = [
            None
            if isinstance(ref, _CallLiteral)
            or (modes and param < len(modes) and modes[param] == 'o')
            else values[_placeholder_slot(slots, ref)]
            for param, ref in bound.items()
        ]
        arg_values = self._index_table_arguments(
            name,
            arg_values,
            [argtypes[param] if param < len(argtypes) else 0 for param in bound]
            if argtypes
            else None,
        )
        cursor = self._conn.cursor()
        if kind == 'f':
            # A routine PostgreSQL has as a function -- orafce's DBMS_OUTPUT, say
            # (#1410) -- which CALL refuses. SELECT it instead, with only the
            # arguments that carry an input: a function takes no OUT argument,
            # and returns its OUT values as the row a CALL would.
            given = [
                (argument, value)
                for (param, _ref), argument, value in zip(
                    bound.items(), arguments, arg_values
                )
                if not (modes and param < len(modes) and modes[param] == 'o')
            ]
            cursor.execute(
                f'SELECT * FROM {name}({_call_placeholders([a for a, _v in given])})',
                tuple(v for a, v in given if not isinstance(a[1], _CallLiteral))
                or None,
            )
        else:
            cursor.execute(
                f'CALL {name}({_call_placeholders(arguments)})',
                tuple(
                    v
                    for (_n, ref), v in zip(arguments, arg_values)
                    if not isinstance(ref, _CallLiteral)
                )
                or None,
            )
        # A procedure with no OUT or IN OUT parameter returns no row at all.
        returned = self._decode_out_row(
            cursor, cursor.fetchone() if cursor.description is not None else None
        )
        out = list(values)
        # The result row carries the OUT and IN OUT parameters in declaration
        # order, whatever order the call named them in; each goes to the bind its
        # argument used.
        outs = [param for param, mode in enumerate(modes or ()) if mode in ('o', 'b')]
        for value, param in zip(returned, outs):
            ref = bound.get(param)
            if ref is None or isinstance(ref, _CallLiteral):
                continue
            # An OUT INTERVAL YEAR TO MONTH arrives as an OraInterval (base
            # interval on the wire) — turn it into an IntervalYM by matching the
            # argument's declared ora_intervalym type, since a CALL result has no
            # table column to trace (#504).
            if (
                self._intervalym_oid is not None
                and param < len(argtypes)
                and argtypes[param] == self._intervalym_oid
            ):
                value = _to_interval_ym(value)
            elif param < len(argtypes) and value is not None:
                # A record or index-by table OUT (#1607): an object, or for a
                # classic array bind the table's values.
                slot = _placeholder_slot(slots, ref)
                bind = binds[slot] if slot < len(binds) else None
                value = self._object_out(
                    argtypes[param],
                    value,
                    array=isinstance(bind, BindVar) and bind.array_size > 0,
                )
            out[_placeholder_slot(slots, ref)] = value
        return Result(out_binds=out)

    def _decode_out_row(self, cursor, row) -> list:
        # Decode a routine's OUT-value row: an ora_tstz composite → an aware
        # datetime at its offset (#519); a refcursor portal → its rows drained into
        # a CursorResult for the REF CURSOR OUT bind (#518); anything else verbatim.
        if row is None:
            return []
        decoded: list = []
        for value, desc in zip(row, cursor.description or ()):
            if value is None:
                decoded.append(None)
            elif desc.type_code == _REFCURSOR_OID:
                decoded.append(self._drain_refcursor(value))
            else:
                decoded.append(_wire_cell(value, desc.type_code, self._tstz_oid))
        return decoded

    def _run_block(self, sql: str, binds: Sequence) -> Result:
        # An anonymous block of no shape the call paths model, with its binds: a
        # DECLARE block assigning one, a SELECT ... INTO or RETURNING ... INTO
        # one, a cursor opened into one (#1456, #1459). It runs as a DO block
        # whose locals stand for the binds, each initialised with the bind's
        # value; every bind comes back with the value its local ended with, a
        # REF CURSOR's portal drained into it as a routine's is (#518) -- None
        # for a cursor the block never opened.
        names = _bind_names(sql)
        locals_: dict[str, tuple[int, str, str]] = {}
        for slot, (name, bind) in enumerate(zip(names, binds)):
            pg_type = _block_bind_type(bind)
            value = bind.value if isinstance(bind, BindVar) else bind
            initial = (
                'NULL'
                if pg_type == 'refcursor' or value is None
                else psycopg.sql.Literal(value).as_string(self._conn)
            )
            if '$$' in initial:  # it would end the DO block's quoting
                raise UnsupportedFeature('a bind value holding $$ in a PL/SQL block')
            locals_[name] = (slot, pg_type, initial)
        block = _translate_idioms(_bind_block(sql, locals_, self._routine_kind))
        slots = list(locals_.values())
        # The block and the read-back of every bind's value, in one round trip
        # (#1917).
        kept = self._conn.cursor()
        with self._conn.pipeline():
            self._conn.execute(block)
            if slots:
                kept.execute(
                    'SELECT '
                    + ', '.join('current_setting(%s, true)' for _slot in slots),
                    [_BLOCK_BIND_SETTING.format(slot) for slot, _t, _i in slots],
                )
        row = kept.fetchone() if slots else None
        values = [b.value if isinstance(b, BindVar) else b for b in binds]
        for index, (slot, pg_type, _initial) in enumerate(slots):
            setting = None if row is None else row[index]
            text = setting[1:] if setting else None
            if pg_type != 'refcursor':
                values[slot] = (
                    None if text is None else _block_bind_value(pg_type, text)
                )
            elif (
                text
                and self._conn.execute(
                    'SELECT 1 FROM pg_cursors WHERE name = %s', (text,)
                ).fetchone()
            ):
                values[slot] = self._drain_refcursor(text)
            else:
                values[slot] = None  # the block never opened it
        return Result(out_binds=values)

    def _drain_refcursor(self, portal: str) -> CursorResult:
        # A REF CURSOR OUT bind: the routine OPENed a portal, whose name the CALL
        # returned. Fetch all its rows (still inside this transaction) and hand them
        # back as a CursorResult the Mirror parks and serves as a nested cursor —
        # re-tagging any ora_tstz cells the same way the top-level read path does.
        # Its columns are described as a query's are, from the statement the
        # portal runs: a CLOB, BLOB, DATE or NVARCHAR2 table column, a
        # TO_CLOB(...) item, read through its domain or its call, where the bare
        # PostgreSQL types described a VARCHAR2, a RAW, a TIMESTAMP (#2071). The
        # client's own text is not known here, so what only it says (a
        # TIMESTAMP literal's nine digits, an unaliased item's name) is not.
        opened = self._conn.execute(
            'SELECT statement FROM pg_cursors WHERE name = %s', (portal,)
        ).fetchone()
        fetch = self._conn.cursor()
        fetch.execute(sql.SQL('FETCH ALL FROM {}').format(sql.Identifier(portal)))
        result = self._build_result(fetch, opened[0] if opened else '')
        # Drained, so close it: an open portal holds its tables, and PostgreSQL
        # refuses DDL on them in this session ("being used by active queries").
        self._conn.execute(sql.SQL('CLOSE {}').format(sql.Identifier(portal)))
        return CursorResult(columns=result.columns, rows=result.rows)

    def _eval_out_assignments(
        self, body: str, assignments: list, binds: Sequence, values: list
    ) -> Result:
        # BEGIN :a := <expr>; :b := <expr>; END — evaluate the right-hand sides
        # with one SELECT and place each result onto its bind position (#517).
        refs = _bind_names(body)
        # Bind the SELECT by NAME, against the block's own bind order. The SELECT
        # carries only the right-hand sides, so the OUT targets are gone from it
        # and its placeholders no longer line up with `values`, which is in the
        # BLOCK's order. Passing `values` straight through bound them by position
        # within the SELECT: for `:r := f(:p)` the block's order is [r, p], the
        # SELECT has only :p, and :p took position 0 -- r's value, which for a
        # pure OUT bind is None. So f received NULL whatever the caller passed,
        # and no error was raised (#1137).
        by_name = dict(zip(refs, values))
        # A classic PL/SQL array passed to a routine's index-by table parameter
        # -- python-oracledb's callfunc names its return :retval, so its call
        # comes this way -- goes as the table's composite (#1607).
        for _ref, expr in assignments:
            call = _PROC_CALL.match(expr)
            if call is None:
                continue
            items = [
                call.group(2)[a:b].strip()
                for a, b in _top_level_items(call.group(2), 0, len(call.group(2)))
            ]
            arg_refs = [i[1:].strip('"') for i in items if i.startswith(':')]
            if len(arg_refs) != len(items) or not any(
                isinstance(by_name.get(r), list) for r in arg_refs
            ):
                continue
            converted = self._index_table_arguments(
                call.group(1), [by_name.get(r) for r in arg_refs]
            )
            by_name.update(zip(arg_refs, converted))
        # A DATE or TIMESTAMP assigned to a TIMESTAMP WITH LOCAL TIME ZONE is read
        # in the session's zone, as Oracle converts it; the cast does that, and
        # leaves a value that is already an instant alone (#1240). The declared
        # type is on the bind, not on its value (#1245).
        declared = {
            ref: getattr(bind, 'tns_type', None) for ref, bind in zip(refs, binds)
        }
        exprs = ', '.join(
            f'CAST(({expr}) AS timestamptz)'
            if declared.get(ref) == TNS_TYPE_TIMESTAMPLTZ
            else expr
            for ref, expr in assignments
        )
        # A PL/SQL expression, so a NO_DATA_FOUND out of a function it calls
        # raises rather than turning NULL as in SQL (#1612).
        select = _translate_idioms(f'SELECT {exprs} FROM {_PLSQL_CALL_MARK}')
        sql, params = _translate_binds(
            select, [by_name[ref] for ref in _bind_names(select)]
        )
        cursor = self._conn.cursor()
        cursor.execute(sql, params)
        row = _decode_row(cursor, cursor.fetchone(), self._tstz_oid) or []
        out = list(values)
        for at, ((ref, _expr), result) in enumerate(zip(assignments, row)):
            if ref in refs:
                # An INTERVAL YEAR TO MONTH comes out of the SELECT as a plain
                # interval, which has no YEAR TO MONTH wire form; the bind's
                # declared type says which it is, as a procedure's parameter
                # type does (#504, #1400).
                if declared.get(ref) == TNS_TYPE_INTERVALYM and result is not None:
                    result = _to_interval_ym(result)
                elif result is not None and cursor.description:
                    # A record or index-by table returned is the object a client
                    # reads, or a classic array's values (#1607).
                    bind = (
                        binds[refs.index(ref)] if refs.index(ref) < len(binds) else None
                    )
                    result = self._object_out(
                        cursor.description[at].type_code,
                        result,
                        array=isinstance(bind, BindVar) and bind.array_size > 0,
                        toid=bind.toid if isinstance(bind, BindVar) else b'',
                    )
                out[refs.index(ref)] = result
        return Result(out_binds=out)

    def _select_into(self, match: 're.Match', values: list) -> Result:
        # BEGIN SELECT <cols> INTO :a, :b FROM ...; END (#1396): run the query with
        # its own binds and give its one row to the INTO binds, as PL/SQL does --
        # no row is ORA-01403 and more than one ORA-01422. The query goes through
        # execute(), so it is translated like any other (ROWID included).
        select, targets, rest = match.groups()
        refs = _bind_names(match.string)
        by_name = dict(zip(refs, values))
        query = f'{select} {rest}'
        result = self.execute(query, [by_name[ref] for ref in _bind_names(query)])
        if not result.rows:
            raise BackendError('no data found', ora_code=ORA_NO_DATA_FOUND)
        if len(result.rows) > 1:
            raise BackendError(
                'exact fetch returns more than requested number of rows',
                ora_code=ORA_TOO_MANY_ROWS,
            )
        out = list(values)
        for target, value in zip(_bind_names(targets), result.rows[0]):
            if target in refs:
                out[refs.index(target)] = value
        return Result(out_binds=out)

    def _run_block_statement(self, statement: str, values: list) -> Result:
        # A single DML statement unwrapped from a BEGIN … END block — run it with
        # the binds (#517). The input values keep the bind positions aligned.
        #
        # One with RETURNING ... INTO runs without the INTO, and the rows it
        # returns go to the INTO binds -- the trailing ones -- by PL/SQL's rule
        # for a single-row RETURNING: no row leaves them NULL, and more than one
        # is ORA-01422 (#1209).
        into = sorted(returning_bind_positions(statement, len(values)))
        if into:
            statement = strip_returning_into(statement)
        sql, params = _translate_binds(
            _translate_idioms(_translate_ddl(_quote_reserved_names(statement))),
            values,
        )
        cursor = self._conn.cursor()
        cursor.execute(sql, params)
        if not into:
            return Result(out_binds=values)
        rows = cursor.fetchall()
        if len(rows) > 1:
            raise BackendError(
                'exact fetch returns more than requested number of rows',
                ora_code=ORA_TOO_MANY_ROWS,
            )
        returned = _decode_row(cursor, rows[0], self._tstz_oid) if rows else None
        out = list(values)
        for i, position in enumerate(into):
            out[position] = returned[i] if returned is not None else None
        return Result(out_binds=out)

    def _collection_outs(self, result: Result, binds: Sequence) -> Result:
        """``result`` with each collection OUT value made an object of its type.

        A routine hands a collection back as a PostgreSQL array -- orafce's
        DBMS_OUTPUT.GET_LINES its lines as text[] -- and a client that bound a
        collection there, sqlplus binding DBMSOUTPUT_LINESARRAY (#1411), reads
        an object of that type: the bind carries the type's id.
        """
        out = list(result.out_binds)
        for at, bind in enumerate(binds):
            if (
                at < len(out)
                and isinstance(bind, BindVar)
                and bind.tns_type == TNS_TYPE_ADT
                and bind.toid
                and isinstance(out[at], list)
            ):
                pg_oid = _pg_oid_of(bind.toid)
                typ = self._collection_type(pg_oid) if pg_oid is not None else None
                if typ is not None:
                    out[at] = DbObject(typ.name, elements=out[at], dbtype=typ)
        return replace(result, out_binds=out)

    def _routine_exists(self, name: str) -> bool:
        """Whether PostgreSQL has a routine of this name, in the schema the name
        gives if it gives one."""
        (schema, routine) = _pg_routine_name(name)
        row = self._conn.execute(
            'SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace '
            "WHERE p.proname = %s AND (%s = '' OR n.nspname = %s) LIMIT 1",
            (routine, schema, schema),
        ).fetchone()
        return row is not None

    def _bfile_path(self, directory: str, filename: str, operation: str) -> str:
        # The path of a BFILE's file on the PostgreSQL host (#1669): under its
        # DIRECTORY object's path, ORA-22285 when that object does not exist.
        row = self._conn.execute(
            'SELECT path FROM sys.ora_directories WHERE name = %s', (directory,)
        ).fetchone()
        if row is None:
            self._conn.rollback()
            raise BackendError(
                f'non-existent directory or file for {operation} operation',
                ora_code=ORA_NONEXISTENT_FILE,
            )
        return row[0].rstrip('/') + '/' + filename

    def _bfile_size(self, path: str) -> int | None:
        # The file's size, None for no such file. A missing file is a NULL
        # record; a present one's creation time is NULL on Linux, so a
        # whole-record test says neither.
        with self._rolled_back_on_error():
            row = self._conn.execute(
                'SELECT (pg_stat_file(%s, true)).size', (path,)
            ).fetchone()
        return None if row is None or row[0] is None else int(row[0])

    def bfile_exists(self, directory: str, filename: str) -> bool:
        """Whether a BFILE's file exists (#1669): ORA-22285 when its DIRECTORY
        object does not, else whether the file is there under the directory's
        path, on the PostgreSQL host, as pg_stat_file finds it -- the server
        that reads it, as Oracle's does."""
        return (
            self._bfile_size(self._bfile_path(directory, filename, 'FILEEXISTS'))
            is not None
        )

    def bfile_length(self, directory: str, filename: str) -> int:
        """A BFILE's length in bytes (#1672), the file's on the PostgreSQL host."""
        size = self._bfile_size(self._bfile_path(directory, filename, 'GETLENGTH'))
        if size is None:
            raise BackendError(
                'non-existent directory or file for GETLENGTH operation',
                ora_code=ORA_NONEXISTENT_FILE,
            )
        return size

    def bfile_read(
        self, directory: str, filename: str, offset: int, amount: int
    ) -> bytes:
        """``amount`` bytes of a BFILE from ``offset`` (1-based), or the rest of
        the file for an amount of 0 or less (#1672), read on the PostgreSQL
        host through pg_read_binary_file."""
        path = self._bfile_path(directory, filename, 'READ')
        size = self._bfile_size(path)
        if size is None:
            raise BackendError(
                'non-existent directory or file for READ operation',
                ora_code=ORA_NONEXISTENT_FILE,
            )
        start = max(offset - 1, 0)
        count = size - start if amount <= 0 else min(amount, size - start)
        if count <= 0:
            return b''
        with self._rolled_back_on_error():
            row = self._conn.execute(
                'SELECT pg_read_binary_file(%s, %s, %s)', (path, start, count)
            ).fetchone()
        return bytes(row[0]) if row and row[0] is not None else b''

    def _rowid_columns(self, table: str) -> frozenset[str]:
        # The ROWID columns of a table a statement names (#1624), as the
        # schema model has them (#1884): no catalog query a call.
        columns = self._relation_columns(table)
        if not columns:
            return frozenset()
        if self._rowid_type_oids is None:
            rows = self._catalog_read(
                "SELECT oid FROM pg_type WHERE typname = 'ora_rowid'"
            ).fetchall()
            self._rowid_type_oids = frozenset(oid for (oid,) in rows)
        return frozenset(
            column.name
            for column in columns.values()
            if column.type_oid in self._rowid_type_oids
        )

    def _rowid_number_error(self, sql: str, binds: Sequence) -> BackendError | None:
        """ORA-00932 for a number an INSERT ... VALUES or an UPDATE ... SET puts
        in a ROWID column (#1624), as Oracle refuses one. PostgreSQL converts
        it to its text, which the column's format check would only refuse as
        ORA-01410. A number bind or literal is caught here; one a query
        computes is left to that check."""
        (masked, contents) = _mask_quoted(sql)
        insert = _ROWID_INSERT.match(masked)
        update = None if insert else _ROWID_UPDATE.match(masked)
        if insert is None and update is None:
            return None
        if insert is not None:
            table = insert.group(1)
            names = [
                masked[a:b].strip()
                for a, b in _top_level_items(masked, insert.start(2), insert.end(2))
            ]
            close = _matching_paren(masked, insert.end() - 1)
            values = [
                masked[a:b].strip()
                for a, b in _top_level_items(masked, insert.end(), close)
            ]
            pairs = list(zip(names, values))
        else:
            assert update is not None
            table = update.group(1)
            pairs = []
            for a, b in _top_level_items(masked, update.end(), len(masked)):
                (column, eq, value) = masked[a:b].partition('=')
                if eq:
                    pairs.append(
                        (column.strip(), re.split(r'(?i)\bWHERE\b', value)[0].strip())
                    )
        rowid_columns = self._rowid_columns(_pg_name(_unmask_quoted(table, contents)))
        if not rowid_columns:
            return None
        bind_values = dict(zip(_bind_names(sql), binds))
        for column, value in pairs:
            last = re.split(r'\s*\.\s*', column)[-1]
            if _folded_name(last, contents) not in rowid_columns:
                continue
            ref = _BIND_REF.fullmatch(value)
            given = bind_values.get(_bind_name(ref)) if ref is not None else None
            number = (
                isinstance(given, (int, float, decimal.Decimal))
                and not isinstance(given, bool)
            ) or (ref is None and _NUMBER_LITERAL.fullmatch(value) is not None)
            if number:
                return BackendError(
                    'inconsistent datatypes: expected ROWID got NUMBER',
                    ora_code=ORA_INCONSISTENT_DATATYPES,
                )
        return None

    def _package_functions(self) -> dict[str, frozenset[str]]:
        # Each package's functions that take no argument a call must give
        # (#1651): package name -> function names, all lower case.
        if self._package_function_cache is None:
            found: dict[str, set[str]] = {}
            if self._has_package_catalog:
                for package, name in self._catalog_read(
                    'SELECT k.name, p.proname FROM sys.ora_packages k '
                    'JOIN pg_namespace n ON n.nspname = k.name '
                    'JOIN pg_proc p ON p.pronamespace = n.oid '
                    "WHERE p.prokind = 'f' AND p.pronargs = p.pronargdefaults"
                ).fetchall():
                    found.setdefault(package, set()).add(name)
            self._package_function_cache = {
                package: frozenset(names) for package, names in found.items()
            }
        return self._package_function_cache

    def _call_package_functions(self, sql: str) -> str:
        """A package's function named without parentheses as the call it is
        (#1651): ``pkg.f`` as ``pkg.f()``, as Oracle calls a function with no
        arguments. PostgreSQL read it as column ``f`` of a table ``pkg``. Oracle
        looks for a table or an alias first, so a statement that names ``pkg``
        anywhere but before a dot -- ``FROM t pkg`` -- is left alone."""
        if '.' not in sql:
            return sql
        (masked, contents) = _mask_quoted(sql)
        lowered = masked.lower()
        packages = {
            p: names for p, names in self._package_functions().items() if p in lowered
        }
        if not packages:
            return sql
        out = masked
        for package, names in packages.items():
            alone = re.compile(
                rf'(?<![\w$#."]){re.escape(package)}(?![\w$#])(?!\s*\.)', re.I
            )
            if alone.search(out):
                continue  # a table or an alias of that name: Oracle's first look
            call = re.compile(
                rf'(?<![\w$#."])({re.escape(package)}\s*\.\s*([A-Za-z_][\w$#]*))'
                rf'(?![\w$#])(?!\s*[(.])',
                re.IGNORECASE,
            )
            out = call.sub(
                lambda m: (
                    f'{m.group(1)}()' if m.group(2).lower() in names else m.group(0)
                ),
                out,
            )
        if out == masked:
            return sql
        return _unmask_quoted(out, contents)

    def _user_routine_names(self) -> frozenset[str]:
        # The names of the routines a user created (#1612): every function or
        # procedure but PostgreSQL's, the extensions' (orafce) and the backend's
        # own sys schema -- what a function's call of one could pass a
        # NO_DATA_FOUND up through. Read when a routine is created.
        rows = self._conn.execute(
            'SELECT DISTINCT p.proname FROM pg_proc p JOIN pg_namespace n '
            'ON n.oid = p.pronamespace '
            "WHERE n.nspname NOT IN ('pg_catalog', 'information_schema', 'sys', "
            "'oracle', 'pg_toast') AND n.nspname NOT LIKE 'pg\\_temp%%' "
            "AND p.prokind IN ('f', 'p') AND NOT EXISTS (SELECT 1 FROM pg_depend d "
            "WHERE d.classid = 'pg_proc'::regclass AND d.objid = p.oid "
            "AND d.deptype = 'e')"
        ).fetchall()
        return frozenset(name for (name,) in rows)

    def _routine_kind(self, name: str) -> str | None:
        """What PostgreSQL has under a routine name -- 'f' a function, 'p' a
        procedure -- in the schema the name gives if it gives one; None for
        nothing (#1533). A quoted part is as written (#2176)."""
        (schema, routine) = _pg_routine_name(name)
        row = self._conn.execute(
            'SELECT p.prokind FROM pg_proc p JOIN pg_namespace n '
            'ON n.oid = p.pronamespace '
            "WHERE p.proname = %s AND (%s = '' OR n.nspname = %s) "
            "AND p.prokind IN ('f', 'p') LIMIT 1",
            (routine, schema, schema),
        ).fetchone()
        return row[0] if row else None

    def _proc_signature(self, name: str) -> tuple[list | None, list, list[str], str]:
        # A routine's parameter modes ('i' IN, 'o' OUT, 'b' IN OUT), the aligned
        # argument type oids, the parameter names -- what a call's argument list
        # can name (#1368) -- and its kind ('p' procedure, 'f' function: orafce
        # has DBMS_OUTPUT's routines as functions, #1410), from one pg_proc row,
        # in the schema the call names if it names one. Modes place a CALL's result row
        # (which carries only the OUT / IN OUT values) back onto the right bind
        # positions; the types let the OUT-bind path spot an ora_intervalym argument
        # (which has no result column to trace). Modes are None for an all-IN routine
        # (PostgreSQL leaves proargmodes — and proallargtypes — NULL then).
        (schema, routine) = _pg_routine_name(name)
        row = self._conn.execute(
            'SELECT p.proargmodes, p.proallargtypes, p.proargnames, p.prokind '
            'FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace '
            "WHERE p.proname = %s AND (%s = '' OR n.nspname = %s) "
            'ORDER BY p.oid DESC LIMIT 1',
            (routine, schema, schema),
        ).fetchone()
        if not row:
            return None, [], [], 'p'
        names = list(row[2] or ())
        if not row[0]:
            return None, [], names, row[3]
        return list(row[0]), list(row[1] or ()), names, row[3]

    def _require_package_owner(self, sql: str) -> None:
        # A CREATE or DROP of a package, or of its body, that another user's
        # role owns: Oracle's needs an ANY privilege, which the Mirror does not
        # model (#1936), so ORA-01031. Refused before the package's records,
        # its owner's to write, are read and their text run on this session's
        # connection (GHSA-qmx7-qr2x-76r7).
        m = _PACKAGE_HEAD.match(sql) or _DROP_PACKAGE.match(sql)
        if m is None:
            return
        row = self._conn.execute(
            "SELECT pg_has_role(nspowner, 'USAGE') FROM pg_namespace WHERE nspname = %s",
            (m.group(3).lower(),),
        ).fetchone()
        if row is not None and not row[0]:
            raise BackendError(
                'insufficient privileges', ora_code=ORA_INSUFFICIENT_PRIVILEGES
            )

    def _require_administrator(self, privilege: str) -> None:
        # A DBA's statement in per-user mode: an account the operator
        # configured may run it (#1857), and a user holding the system
        # privilege it needs, or the DBA role (#1936), as on Oracle. In
        # single-role mode the database is one tenant, and anyone may.
        user = getattr(self, '_login_user', None) or ''
        if not self._per_user or self._accounts.configured(user):
            return
        if privilege in self._held_privileges():
            return
        raise BackendError(
            'insufficient privileges', ora_code=ORA_INSUFFICIENT_PRIVILEGES
        )

    def _held_privileges(self) -> dict[str, bool]:
        # The modelled system privileges the session's user holds (#1936),
        # directly, through PUBLIC or through DBA, each with whether it may
        # grant it on: WITH ADMIN OPTION, or as a DBA, who may grant any.
        if not self._has_sys_privs():
            return {}
        held: dict[str, bool] = {}
        for privilege, admin in self._conn.execute(
            'SELECT privilege, admin_option FROM sys.user_sys_privs UNION ALL '
            'SELECT granted_role, admin_option FROM sys.user_role_privs'
        ).fetchall():
            held[privilege] = held.get(privilege, False) or admin == 'YES'
        if _DBA_ROLE in held:
            held.update(dict.fromkeys(_SYSTEM_PRIVILEGES, True))
            held[_DBA_ROLE] = True
        return held

    def _system_grant_statement(self, statement: str) -> Result | None:
        """GRANT or REVOKE of the system privileges the Mirror models, or the
        DBA role (#1936), recorded in sys.ora_sys_privs on the installer's
        connection. Any other system privilege or role is the no-op it was;
        named beside a modelled one, it is passed over. Who may: an account
        the operator configured, a DBA, or one holding the privilege WITH
        ADMIN OPTION -- in per-user mode; anyone in single-role mode, where a
        grant enforces nothing. None for any other statement."""
        m = _SYSTEM_GRANT.match(statement)
        if m is None:
            return None
        (verb, written, listed, option) = m.groups()
        named = [' '.join(p.split()).upper() for p in written.split(',')]
        modelled = [p for p in named if p in (*_SYSTEM_PRIVILEGES, _DBA_ROLE)]
        if not modelled or not self._has_sys_privs():
            return None
        if len(set(named)) != len(named):
            raise BackendError(
                'duplicate privilege listed', ora_code=_ORA_DUPLICATE_PRIVILEGE
            )
        grantees = _grantees(listed)
        granting = verb.upper() == 'GRANT'
        user = getattr(self, '_login_user', None) or ''
        if self._per_user and not self._accounts.configured(user):
            held = self._held_privileges()
            if not all(held.get(p, False) for p in modelled):
                raise BackendError(
                    'insufficient privileges', ora_code=ORA_INSUFFICIENT_PRIVILEGES
                )
        for grantee in grantees:
            if grantee != 'PUBLIC' and not self._user_exists(grantee):
                raise BackendError(
                    f"user or role '{grantee}' does not exist",
                    ora_code=_ORA_UNKNOWN_GRANTEE,
                )
        self.commit()
        with self._administering() as conn:
            if granting:
                conn.cursor().executemany(
                    'INSERT INTO sys.ora_sys_privs VALUES (%s, %s, %s) '
                    'ON CONFLICT (grantee, privilege) DO UPDATE SET admin_option = '
                    'sys.ora_sys_privs.admin_option OR EXCLUDED.admin_option',
                    [(g, p, option is not None) for g in grantees for p in modelled],
                )
            else:
                for grantee in grantees:
                    for privilege in modelled:
                        gone = conn.execute(
                            'DELETE FROM sys.ora_sys_privs '
                            'WHERE grantee = %s AND privilege = %s',
                            (grantee, privilege),
                        ).rowcount
                        if gone:
                            continue
                        conn.rollback()
                        if privilege == _DBA_ROLE:
                            raise BackendError(
                                f"ROLE '{privilege}' not granted to '{grantee}'",
                                ora_code=_ORA_ROLE_NOT_GRANTED,
                            )
                        raise BackendError(
                            f"system privileges not granted to '{grantee}'",
                            ora_code=_ORA_SYSTEM_PRIVILEGE_NOT_GRANTED,
                        )
            if self._per_user and _DBA_ROLE in modelled:
                group = self._ensure_user_group(conn)
                for grantee in grantees:
                    if granting:
                        self._join_dbas(conn, group, grantee)
                    else:
                        self._leave_dbas(conn, group, grantee)
            conn.commit()
        return Result()

    @contextmanager
    def _administering(self) -> Iterator[psycopg.Connection]:
        # The connection a DBA's statement runs on. In per-user mode it is the
        # installer's own (#1857), opened for the statement and committed as
        # it ends; a user's role may not write what it writes. Otherwise it is
        # the session's, which the statement commits itself.
        if not self._per_user:
            yield self._conn
            return
        with psycopg.connect(self._admin_conninfo) as conn:
            yield conn

    def _ensure_user_group(self, conn: psycopg.Connection) -> str:
        # The group every user's role is a member of, and what it may use of
        # this database's installation (#1857): made once per process and
        # database, after the dictionary, whose tables it grants. Its name.
        ready = _USER_GROUP_READY.get(self._admin_conninfo)
        if ready is not None:
            return ready
        row = conn.execute(
            'SELECT current_user || %s, EXISTS (SELECT 1 FROM pg_roles '
            'WHERE rolname = current_user || %s)',
            (_USER_GROUP_SUFFIX,) * 2,
        ).fetchone()
        assert row is not None
        (group, exists) = row
        if not exists:
            conn.execute(
                sql.SQL('CREATE ROLE {} NOLOGIN').format(sql.Identifier(group))
            )
        conn.execute(_user_group_grants(group))
        dbas = _dba_group(group)
        row = conn.execute(
            'SELECT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = %s)', (dbas,)
        ).fetchone()
        if not (row and row[0]):
            conn.execute(sql.SQL('CREATE ROLE {} NOLOGIN').format(sql.Identifier(dbas)))
        conn.execute(_dba_group_grants(dbas))
        _USER_GROUP_READY[self._admin_conninfo] = group
        return group

    def _ensure_user_role(self, conn: psycopg.Connection, name: str) -> str:
        """The PostgreSQL role user `name` logs in as in per-user mode (#1857),
        made if it is not there yet, and its password.

        It is named as the user's schema, which it owns; it is marked as the
        Mirror's and is a member of the users' group. What it makes is its own:
        PostgreSQL grants a function's EXECUTE and a type's USAGE to PUBLIC,
        which an Oracle routine or type is not, so those are taken back. A role
        of that name the Mirror did not make is another's: ORA-01920.
        """
        role = sql.Identifier(name.lower())
        group = self._ensure_user_group(conn)
        # Ours only if marked so and made by this installer, whose privileges
        # it lent it: another's mark is another installation's user.
        # And a member of the group, which it may not be if it was made with
        # another installation's grants, or before the group was.
        row = conn.execute(
            "SELECT shobj_description(oid, 'pg_authid') = %s "
            "AND pg_has_role(current_user, oid, 'USAGE'), "
            "pg_has_role(oid, %s, 'MEMBER'), pg_has_role(oid, %s, 'MEMBER') "
            'FROM pg_roles WHERE rolname = %s',
            (_USER_ROLE_MARK, group, _dba_group(group), name.lower()),
        ).fetchone()
        if row is not None and not row[0]:
            raise BackendError(
                f"user name '{name}' conflicts with another user or role name",
                ora_code=ORA_USER_NAME_CONFLICT,
            )
        if row is not None and not row[1]:
            conn.execute(sql.SQL('GRANT {} TO {}').format(sql.Identifier(group), role))
        if row is not None and not row[2] and self._accounts.configured(name):
            # An administrator reads the DBA's views (#2223).
            self._join_dbas(conn, group, name)
        password = self._accounts.role_password(name)
        if row is not None and password is not None:
            # The user's role as it was made: a login's usual case.
            return password
        if row is None:
            password = secrets.token_urlsafe(32)
            # The installer gets the role's privileges, so it can set the
            # role's defaults now and drop what it owns with it later.
            conn.execute("SET LOCAL createrole_self_grant = 'set, inherit'")
            conn.execute(
                sql.SQL('CREATE ROLE {} LOGIN PASSWORD {} IN ROLE {}').format(
                    role, sql.Literal(_scram_verifier(password)), sql.Identifier(group)
                )
            )
            conn.execute(
                sql.SQL('COMMENT ON ROLE {} IS {}').format(
                    role, sql.Literal(_USER_ROLE_MARK)
                )
            )
            conn.execute(
                sql.SQL(
                    'ALTER DEFAULT PRIVILEGES FOR ROLE {0} REVOKE EXECUTE ON '
                    'FUNCTIONS FROM PUBLIC; ALTER DEFAULT PRIVILEGES FOR ROLE {0} '
                    'REVOKE USAGE ON TYPES FROM PUBLIC'
                ).format(role)
            )
            if self._accounts.configured(name):
                self._join_dbas(conn, group, name)
        elif password is None:
            # A role whose password the accounts no longer have gets a new one.
            password = secrets.token_urlsafe(32)
            conn.execute(
                sql.SQL('ALTER ROLE {} PASSWORD {}').format(
                    role, sql.Literal(_scram_verifier(password))
                )
            )
        conn.execute(
            sql.SQL(
                'CREATE SCHEMA IF NOT EXISTS {0} AUTHORIZATION {0}; '
                'ALTER SCHEMA {0} OWNER TO {0}'
            ).format(role)
        )
        self._accounts.set_role_password(name, password)
        return password

    def _join_dbas(self, conn: psycopg.Connection, group: str, name: str) -> None:
        # Make user `name`'s role -- or, for PUBLIC, the users' group -- a
        # member of the DBAs' group, which reads the DBA's views (#2223). It
        # inherits the group's SELECT; it may not act as the group.
        member = group if name == 'PUBLIC' else name.lower()
        conn.execute(
            sql.SQL('GRANT {} TO {} WITH INHERIT TRUE, SET FALSE').format(
                sql.Identifier(_dba_group(group)), sql.Identifier(member)
            )
        )

    def _leave_dbas(self, conn: psycopg.Connection, group: str, name: str) -> None:
        # Take that membership back: on REVOKE DBA, unless the account is an
        # administrator, whose right the configuration gives.
        if name != 'PUBLIC' and self._accounts.configured(name):
            return
        member = group if name == 'PUBLIC' else name.lower()
        conn.execute(
            sql.SQL('REVOKE {} FROM {}').format(
                sql.Identifier(_dba_group(group)), sql.Identifier(member)
            )
        )

    def _refuse_connected(self, conn: psycopg.Connection, name: str) -> None:
        # Oracle refuses to drop a user with a session open, ORA-01940; in
        # per-user mode a user's sessions are its role's (#1857).
        row = conn.execute(
            'SELECT EXISTS (SELECT 1 FROM pg_stat_activity WHERE usename = %s)',
            (name.lower(),),
        ).fetchone()
        if row is not None and row[0]:
            raise BackendError(
                'cannot drop a user who is currently connected',
                ora_code=_ORA_USER_CONNECTED,
            )

    def _drop_user_role(self, conn: psycopg.Connection, name: str) -> None:
        # DROP USER in per-user mode (#1857): the user's role, and what it
        # still owns, once its schema has gone -- if the Mirror made it.
        row = conn.execute(
            "SELECT shobj_description(oid, 'pg_authid') = %s FROM pg_roles "
            'WHERE rolname = %s',
            (_USER_ROLE_MARK, name.lower()),
        ).fetchone()
        if row is None or not row[0]:
            return
        role = sql.Identifier(name.lower())
        conn.execute(sql.SQL('DROP OWNED BY {} CASCADE').format(role))
        conn.execute(sql.SQL('DROP ROLE {}').format(role))

    def _become(self, user: str, proxy: str) -> None:
        # Per-user mode, once the login checked out (#1857): the session goes
        # on as its user's own role, on a connection of its own set up as the
        # installer's was, which is closed. The session's settings follow it:
        # the user's schema first on the path, the user and the proxy user.
        if self._became:
            # The session is the login user's role already (#1939), which
            # may not make another's: the installer's connection does.
            with self._administering() as admin:
                password = self._ensure_user_role(admin, user)
                admin.commit()
        else:
            try:
                password = self._ensure_user_role(self._conn, user)
                self._conn.commit()
            except BaseException:
                self._conn.rollback()
                raise
        conninfo = make_conninfo(
            self._admin_conninfo, user=user.lower(), password=password
        )
        twin = type(self)(
            conninfo,
            credentials=self._credentials,
            auth_conninfo=self._accounts.auth_conninfo,
            presents=self._presents,
        )
        (installer, self._conn) = (self._conn, twin._conn)
        installer.close()
        self._conninfo = conninfo
        self._twin = lambda: type(self)(
            conninfo,
            credentials=self._credentials,
            auth_conninfo=self._accounts.auth_conninfo,
            presents=self._presents,
        )
        self._at_once(
            sql.SQL('; ').join(
                [
                    sql.SQL('SET search_path TO {}, ' + _SEARCH_PATH_TAIL).format(
                        sql.Identifier(user.lower())
                    ),
                    sql.SQL(
                        "SELECT set_config('seerdb.session_user', {}, false), "
                        "set_config('seerdb.proxy_user', {}, false)"
                    ).format(sql.Literal(user), sql.Literal(proxy)),
                ]
            )
        )
        if proxy:
            # Who the session's proxy is, as the installer records it: the
            # session's setting is the client's to change, the record not
            # (GHSA-336m-cp9c-m2fw). Records of ended backends go with it.
            with self._administering() as admin:
                admin.execute(
                    'DELETE FROM sys.ora_session_proxies x WHERE NOT EXISTS (SELECT 1 '
                    'FROM pg_stat_activity a WHERE a.pid = x.pid '
                    'AND a.backend_start = x.started)'
                )
                admin.execute(
                    'INSERT INTO sys.ora_session_proxies SELECT pid, backend_start, %s '
                    'FROM pg_stat_activity WHERE pid = %s ON CONFLICT DO NOTHING',
                    (proxy, self._conn.info.backend_pid),
                )
                admin.commit()

    def _dba_statement(self, statement: str) -> Result | None:
        # CREATE / DROP DIRECTORY and EDITION in per-user mode (#1857): a
        # DBA's, so an administrator's only, run on the installer's connection,
        # whose records they write. In single-role mode they translate as any
        # other statement does. None for any other statement.
        if not self._per_user:
            return None
        translated = _directory_statement(statement)
        if translated is None and _ALTER_SESSION_EDITION.match(statement) is None:
            translated = _edition_statement(statement)
        if translated is None:
            return None
        verb = 'CREATE' if statement.lstrip()[:6].upper() == 'CREATE' else 'DROP'
        kind = 'DIRECTORY' if _directory_statement(statement) else 'EDITION'
        self._require_administrator(f'{verb} ANY {kind}')
        try:
            with self._administering() as conn:
                conn.execute(translated)
        except psycopg.Error as exc:
            raise _backend_error(
                exc, original=statement, translated=translated
            ) from None
        return Result()

    def _synonym_statement(self, statement: str) -> Result | None:
        """CREATE or DROP of a private synonym for a table or view (#2179),
        with Oracle's checks: the name not another object's (ORA-00955) nor
        its own target's (ORA-01471), a DROP's synonym there (ORA-01434). The
        synonym is recorded in sys.ora_synonyms, and is a view of its name
        over its target, which DML goes through as PostgreSQL updates a simple
        view; one whose target is not there is recorded with no view. DDL, so
        the transaction is committed first. None for any other statement."""
        created = _CREATE_SYNONYM.match(statement)
        dropped = None if created else _DROP_SYNONYM.match(statement)
        if created is None and dropped is None:
            return None
        public = bool(created.group(2) if created else dropped and dropped.group(1))
        self.commit()
        row = self._conn.execute(
            "SELECT sys.ora_owner(current_schema()), has_schema_privilege('public', 'CREATE')"
        ).fetchone()
        assert row is not None
        (here, may_publish) = row
        if public and not may_publish:
            # CREATE / DROP PUBLIC SYNONYM: a system privilege the Mirror does
            # not model, so CREATE on PostgreSQL's public schema, where the
            # view goes, stands for it.
            raise BackendError(
                'insufficient privileges', ora_code=ORA_INSUFFICIENT_PRIVILEGES
            )

        def named(written: str, synonym: bool = False) -> tuple[str, str, str]:
            # An owner and a name as Oracle spells them, and as written; a
            # PUBLIC synonym's owner is PUBLIC, its view in public, and its
            # target's schema, where the statement gives none, the creator's.
            parts = re.split(r'\s*\.\s*', written.strip())
            if synonym and public:
                return ('PUBLIC', _oracle_name(parts[-1]), f'public.{parts[-1]}')
            owner = _oracle_name(parts[0]) if len(parts) == 2 else here
            if public and len(parts) == 1:
                return (owner, _oracle_name(parts[0]), f'{here}.{parts[0]}')
            return (owner, _oracle_name(parts[-1]), written.strip())

        def recorded(owner: str, name: str) -> bool:
            return (
                self._conn.execute(
                    'SELECT 1 FROM sys.ora_synonyms WHERE owner = %s AND name = %s',
                    (owner, name),
                ).fetchone()
                is not None
            )

        if dropped is not None:
            (owner, name, written) = named(dropped.group(2), synonym=True)
            if not recorded(owner, name):
                raise BackendError(
                    f'{"public" if public else "private"} synonym to be dropped '
                    'does not exist',
                    ora_code=_ORA_NO_SUCH_PUBLIC_SYNONYM
                    if public
                    else _ORA_NO_SUCH_SYNONYM,
                )
            # The record first: the DROP VIEW's own DDL would otherwise find a
            # synonym without its view, and make it again.
            self._conn.execute(
                'DELETE FROM sys.ora_synonyms WHERE owner = %s AND name = %s',
                (owner, name),
            )
            self._conn.commit()
            pg_name = name.lower() if re.fullmatch(r'[A-Z][A-Z0-9_$#]*', name) else name
            if self._conn.execute(
                "SELECT to_regclass(quote_ident(lower(%s)) || '.' || quote_ident(%s))",
                (owner, pg_name),
            ).fetchone() != (None,):
                self.execute(f'DROP VIEW {written}')
            return Result()
        assert created is not None
        if created.group(5):
            raise UnsupportedFeature('a synonym for a remote object is not supported')
        (owner, name, written) = named(created.group(3), synonym=True)
        (target_owner, target, target_written) = named(created.group(4))
        if (owner, name) == (target_owner, target):
            raise BackendError(
                'cannot create a synonym with same name as object',
                ora_code=_ORA_SYNONYM_OF_ITSELF,
            )
        taken = self._conn.execute(
            'SELECT 1 FROM all_objects WHERE owner = %s AND object_name = %s '
            'AND object_type = ANY(%s)',
            (owner, name, list(_SYNONYM_NAMESPACE)),
        ).fetchone()
        if taken is not None or (not created.group(1) and recorded(owner, name)):
            self._conn.rollback()
            raise BackendError(
                _ORA_MESSAGE[ORA_NAME_ALREADY_USED], ora_code=ORA_NAME_ALREADY_USED
            )
        kind = self._conn.execute(
            'SELECT object_type FROM all_objects WHERE owner = %s AND object_name = %s '
            "AND object_type <> 'SYNONYM' ORDER BY object_type <> 'TABLE' LIMIT 1",
            (target_owner, target),
        ).fetchone()
        self._conn.rollback()
        if kind is not None and kind[0] not in (
            'TABLE',
            'VIEW',
            'MATERIALIZED VIEW',
            *_REWRITTEN_SYNONYM_KINDS,
        ):
            raise UnsupportedFeature(
                f'a synonym for a {kind[0].lower()} is not supported yet'
            )
        if kind is not None and kind[0] in _REWRITTEN_SYNONYM_KINDS:
            # No view stands in for it: its name is rewritten (#2179).
            kind = None
        previous = self._conn.execute(
            'SELECT table_owner, table_name FROM sys.ora_synonyms '
            'WHERE owner = %s AND name = %s',
            (owner, name),
        ).fetchone()

        def record(target_of: tuple[str, str]) -> None:
            self._conn.execute(
                'INSERT INTO sys.ora_synonyms (owner, name, table_owner, table_name) '
                'VALUES (%s, %s, %s, %s) ON CONFLICT (owner, name) DO UPDATE SET '
                'table_owner = EXCLUDED.table_owner, table_name = EXCLUDED.table_name',
                (owner, name, *target_of),
            )
            self._conn.commit()

        # The record first, so the view's own DDL, which makes each synonym's
        # view as its record says, finds the new target (#2179).
        record((target_owner, target))
        try:
            if kind is not None:
                self.execute(
                    f'CREATE OR REPLACE VIEW {written} AS SELECT * FROM {target_written}'
                )
            elif previous is not None:
                # Replaced by one whose target is not there: the old view goes.
                self.execute(f'DROP VIEW IF EXISTS {written}')
        except BackendError:
            if previous is None:
                self._conn.execute(
                    'DELETE FROM sys.ora_synonyms WHERE owner = %s AND name = %s',
                    (owner, name),
                )
                self._conn.commit()
            else:
                record(previous)
            raise
        return Result()

    def _object_grant_statement(self, statement: str) -> Result | None:
        """GRANT or REVOKE of object privileges (#1621, #1858), with Oracle's
        checks: the object must be there, the privilege one its kind takes, the
        grantee a user; a grant is its owner's to make, or one's who holds the
        privilege WITH GRANT OPTION, and a revoke only of what one granted, its
        cascade taking what the grantee granted on. Recorded in either mode; in
        per-user mode PostgreSQL's own GRANT or REVOKE enforces it (#1857).
        DDL, so the transaction is committed first. None for any other
        statement."""
        m = _OBJECT_GRANT.match(statement)
        if m is None:
            return None
        (verb, written, target, _to, listed, option) = m.groups()
        granting = verb.upper() == 'GRANT'
        parsed = _granted_privileges(written)
        (privileges, columns) = (None, {}) if parsed is None else parsed
        if columns and not granting:
            raise BackendError(
                'UPDATE/REFERENCES may only be REVOKEd from the whole table, '
                'not by column',
                ora_code=_ORA_COLUMN_REVOKE,
            )
        grantees = _grantees(listed)
        self.commit()
        row = self._conn.execute(
            "SELECT sys.sys_context('userenv', 'session_user'), "
            'sys.ora_owner(current_schema())'
        ).fetchone()
        assert row is not None
        # The grantor is the login's user, which the Mirror knows itself, not
        # a session setting (GHSA-336m-cp9c-m2fw).
        (me, here) = (getattr(self, '_login_user', None) or row[0], row[1])
        parts = re.split(r'\s*\.\s*', target.strip())
        owner = _oracle_name(parts[0]) if len(parts) == 2 else here
        name = _oracle_name(parts[-1])
        found = self._conn.execute(
            _GRANTED_OBJECT,
            {'schema': f'"{owner.lower()}"', 'name': name, 'owner': owner},
        ).fetchall()
        if not found:
            self._conn.rollback()
            raise BackendError(
                'table or view does not exist',
                ora_code=ORA_TABLE_OR_VIEW_DOES_NOT_EXIST,
            )
        kind = found[0][0]
        if kind in ('PROCEDURE', 'FUNCTION'):
            kinds = {'PROCEDURE', 'FUNCTION'}
        else:
            kinds = {kind}
        targets = [(t, on) for (k, t, on) in found if k in kinds]
        allowed = _OBJECT_PRIVILEGES[kind]
        if kind == 'TABLE' and self._release >= (23, 0):
            allowed = tuple(sorted((*allowed, _ASSERTION_REFERENCES)))
        if privileges is not None and any(
            p not in allowed for p in (*privileges, *columns)
        ):
            self._conn.rollback()
            raise _privilege_kind_error(kind, self._release)
        try:
            granted_columns = self._granted_columns(targets[0][0], columns)
        except BaseException:
            self._conn.rollback()
            raise
        for grantee in grantees:
            if grantee != 'PUBLIC' and not self._user_exists(grantee):
                self._conn.rollback()
                raise BackendError(
                    f"user or role '{grantee}' does not exist",
                    ora_code=_ORA_UNKNOWN_GRANTEE,
                )
        key = (owner, name)
        try:
            if granting:
                self._grant_object(
                    key,
                    kind,
                    targets,
                    list(allowed) if privileges is None else privileges,
                    granted_columns,
                    grantees,
                    me,
                    option is not None,
                )
            else:
                self._revoke_object(key, kind, targets, privileges, grantees, me)
            self._conn.commit()
        except psycopg.Error as exc:
            self._conn.rollback()
            raise _backend_error(exc, original=statement) from exc
        except BaseException:
            self._conn.rollback()
            raise
        self._collection_name_cache = None
        self._routine_synonym_cache = None
        return Result()

    def _grant_object(
        self,
        key: tuple[str, str],
        kind: str,
        targets: list[tuple[str, str]],
        privileges: list[str],
        columns: _GrantedColumns,
        grantees: list[str],
        me: str,
        grantable: bool,
    ) -> None:
        (owner, name) = key
        if me != owner:
            # Not the owner's: each privilege one holds WITH GRANT OPTION, or
            # ORA-01031 -- ORA-00942 if one holds nothing on the object.
            held = dict(
                self._conn.execute(
                    "SELECT privilege, bool_or(grantable = 'YES') FROM sys.ora_grants "
                    'WHERE owner = %s AND object_name = %s '
                    "AND grantee IN (%s, 'PUBLIC') GROUP BY privilege",
                    (owner, name, me),
                ).fetchall()
            )
            # A column's privilege WITH GRANT OPTION, on the column or the
            # whole object, grants it on (#1946).
            held_columns = {
                (p, c): g
                for (p, c, g) in self._conn.execute(
                    "SELECT privilege, column_name, bool_or(grantable = 'YES') "
                    'FROM sys.ora_col_grants WHERE owner = %s AND object_name = %s '
                    "AND grantee IN (%s, 'PUBLIC') GROUP BY privilege, column_name",
                    (owner, name, me),
                )
            }
            if not held and not held_columns:
                raise BackendError(
                    'table or view does not exist',
                    ora_code=ORA_TABLE_OR_VIEW_DOES_NOT_EXIST,
                )
            if not all(held.get(p) for p in privileges) or not all(
                held.get(p) or held_columns.get((p, column))
                for (p, named) in columns.named.items()
                for (column, _attname) in named
            ):
                raise BackendError(
                    'insufficient privileges', ora_code=ORA_INSUFFICIENT_PRIVILEGES
                )
        # A grant to oneself does nothing, as Oracle's does.
        grantees = [g for g in grantees if g != me]
        if not grantees:
            return
        flag = 'YES' if grantable else 'NO'
        with self._conn.cursor() as cursor:
            cursor.executemany(
                'INSERT INTO sys.ora_grants (owner, object_name, privilege, grantee, '
                'grantor, grantable, object_type) VALUES (%s, %s, %s, %s, %s, %s, %s) '
                'ON CONFLICT (owner, object_name, privilege, grantee, grantor) '
                "DO UPDATE SET grantable = CASE WHEN excluded.grantable = 'YES' "
                "THEN 'YES' ELSE sys.ora_grants.grantable END, "
                'object_type = excluded.object_type',
                [
                    (owner, name, p, g, me, flag, kind)
                    for g in grantees
                    for p in privileges
                ],
            )
        if columns.named:
            with self._conn.cursor() as cursor:
                cursor.executemany(
                    'INSERT INTO sys.ora_col_grants (owner, object_name, column_name, '
                    'privilege, grantee, grantor, grantable, relid, attname) '
                    'VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s) ON CONFLICT '
                    '(owner, object_name, column_name, privilege, grantee, grantor) '
                    "DO UPDATE SET grantable = CASE WHEN excluded.grantable = 'YES' "
                    "THEN 'YES' ELSE sys.ora_col_grants.grantable END",
                    [
                        (owner, name, column, p, g, me, flag, columns.relid, attname)
                        for g in grantees
                        for (p, named) in columns.named.items()
                        for (column, attname) in named
                    ],
                )
        if self._per_user:
            self._pg_object_grants(
                owner, kind, targets, privileges, grantees, grantable, columns
            )

    def _revoke_object(
        self,
        key: tuple[str, str],
        kind: str,
        targets: list[tuple[str, str]],
        privileges: list[str] | None,
        grantees: list[str],
        me: str,
    ) -> None:
        (owner, name) = key
        for grantee in grantees:
            # What one granted, on the object or its columns: a privilege
            # revoked from the whole object takes its column grants too
            # (#1946).
            mine = {
                r[0]
                for r in self._conn.execute(
                    'SELECT privilege FROM sys.ora_grants WHERE owner = %s '
                    'AND object_name = %s AND grantee = %s AND grantor = %s '
                    'UNION SELECT privilege FROM sys.ora_col_grants WHERE owner = %s '
                    'AND object_name = %s AND grantee = %s AND grantor = %s',
                    (owner, name, grantee, me) * 2,
                )
            }
            # Only what one granted, or ORA-01927; ALL is all of it.
            revoked = sorted(mine) if privileges is None else privileges
            if not revoked or any(p not in mine for p in revoked):
                raise _not_granted_by_you(self._release)
            for table in ('ora_grants', 'ora_col_grants'):
                self._conn.execute(
                    f'DELETE FROM sys.{table} WHERE owner = %s AND object_name = %s '
                    'AND grantee = %s AND grantor = %s AND privilege = ANY(%s)',
                    (owner, name, grantee, me, revoked),
                )
            if self._per_user:
                self._pg_object_revokes(key, kind, targets, revoked, grantee, me)
        self._conn.execute('SELECT sys.ora_grants_cascade(%s, %s)', (owner, name))

    def _follow_grants(self, statement: str) -> None:
        # After a committed DDL (#1858): a replaced object gets its grants
        # back in per-user mode, as Oracle keeps them; a dropped one's go.
        replaced = _REPLACED_OBJECT.match(statement)
        dropped = None if replaced else _DROPPED_OBJECT.match(statement)
        named = replaced or dropped
        if named is None:
            return
        parts = re.split(r'\s*\.\s*', named.group(1).strip())
        try:
            row = self._conn.execute(
                'SELECT sys.ora_owner(current_schema())'
            ).fetchone()
            assert row is not None
            owner = _oracle_name(parts[0]) if len(parts) == 2 else row[0]
            name = _oracle_name(parts[-1])
            found = self._conn.execute(
                _GRANTED_OBJECT,
                {'schema': f'"{owner.lower()}"', 'name': name, 'owner': owner},
            ).fetchall()
            if dropped is not None:
                if not found:
                    for table in ('ora_grants', 'ora_col_grants'):
                        self._conn.execute(
                            f'DELETE FROM sys.{table} WHERE owner = %s '
                            'AND object_name = %s',
                            (owner, name),
                        )
            elif found and self._per_user:
                kind = found[0][0]
                targets = [(t, on) for (k, t, on) in found if k == kind]
                grants = self._conn.execute(
                    "SELECT grantee, grantable = 'YES', array_agg(privilege) "
                    'FROM sys.ora_grants WHERE owner = %s AND object_name = %s '
                    "GROUP BY grantee, grantable = 'YES'",
                    (owner, name),
                ).fetchall()
                for grantee, grantable, privileges in grants:
                    self._pg_object_grants(
                        owner, kind, targets, privileges, [grantee], grantable
                    )
            self._conn.commit()
        except psycopg.Error:
            self._conn.rollback()

    def _granted_columns(
        self, relation: str, written: dict[str, list[str]]
    ) -> _GrantedColumns:
        # The columns a GRANT names for each privilege, on the relation:
        # Oracle's name and PostgreSQL's, a name as written or folded; and
        # the relation's oid (#1946). ORA-00904 for one not there, ORA-00957
        # for one named twice.
        if not written:
            return _GrantedColumns(0, {})
        rows = self._conn.execute(
            'SELECT %s::regclass::oid, array_agg(a.attname::text) FROM pg_attribute a '
            'WHERE a.attrelid = %s::regclass AND a.attnum > 0 AND NOT a.attisdropped',
            (relation, relation),
        ).fetchone()
        assert rows is not None
        (relid, attnames) = (rows[0], set(rows[1] or ()))
        named: dict[str, list[tuple[str, str]]] = {}
        for privilege, columns in written.items():
            names = [_oracle_name(c) for c in columns]
            if len(set(names)) != len(names):
                raise BackendError(
                    'duplicate column name', ora_code=_ORA_DUPLICATE_COLUMN
                )
            for column in names:
                attname = next(
                    (a for a in (column, column.lower()) if a in attnames), None
                )
                if attname is None:
                    raise BackendError(
                        f'"{column}": invalid identifier',
                        ora_code=ORA_INVALID_IDENTIFIER,
                    )
                named.setdefault(privilege, []).append((column, attname))
        return _GrantedColumns(relid, named)

    def _grantee_role(self, grantee: str) -> sql.Composable:
        # The PostgreSQL role a grant goes to in per-user mode (#1858): PUBLIC,
        # or the user's own role, made now for a user that never logged in.
        if grantee == 'PUBLIC':
            return sql.SQL('PUBLIC')
        role = grantee.lower()
        exists = self._conn.execute(
            'SELECT 1 FROM pg_roles WHERE rolname = %s', (role,)
        ).fetchone()
        if exists is None:
            with self._administering() as conn:
                self._ensure_user_role(conn, grantee)
                conn.commit()
        return sql.Identifier(role)

    def _pg_object_targets(
        self, kind: str, targets: list[tuple[str, str]], privileges: Iterable[str]
    ) -> list[sql.Composed]:
        # What PostgreSQL grants for the privileges on the object: one
        # `privileges ON object` per target, none for privileges with no
        # counterpart there. A package's EXECUTE is its schema's USAGE and its
        # routines' and types' (#1858).
        mapping = _PG_PRIVILEGES.get(kind, _PG_PRIVILEGES['EXECUTABLE'])
        mapped = sorted({mapping[p] for p in privileges if p in mapping})
        if not mapped:
            return []
        if kind == 'PACKAGE':
            schema = targets[0][0]
            on = [sql.SQL('USAGE ON SCHEMA {}').format(sql.SQL(schema))]
            on.append(
                sql.SQL('EXECUTE ON ALL ROUTINES IN SCHEMA {}').format(sql.SQL(schema))
            )
            for target, kw in self._conn.execute(
                "SELECT t.oid::regtype::text, CASE t.typtype WHEN 'd' THEN 'DOMAIN' "
                "ELSE 'TYPE' END FROM pg_type t LEFT JOIN pg_class c ON c.oid = t.typrelid "
                'WHERE t.typnamespace = to_regnamespace(%s) '
                "AND (t.typtype = 'd' OR t.typtype = 'c' AND c.relkind = 'c')",
                (schema,),
            ):
                on.append(
                    sql.SQL('USAGE ON {} {}').format(sql.SQL(kw), sql.SQL(target))
                )
            return on
        if kind in ('PROCEDURE', 'FUNCTION', 'TYPE'):
            verb = 'EXECUTE' if kind != 'TYPE' else 'USAGE'
            return [
                sql.SQL('{} ON {} {}').format(sql.SQL(verb), sql.SQL(kw), sql.SQL(t))
                for (t, kw) in targets
            ]
        return [
            sql.SQL('{} ON {} {}').format(
                sql.SQL(', '.join(mapped)), sql.SQL(kw), sql.SQL(t)
            )
            for (t, kw) in targets
        ]

    def _pg_object_grants(
        self,
        owner: str,
        kind: str,
        targets: list[tuple[str, str]],
        privileges: Iterable[str],
        grantees: list[str],
        grantable: bool,
        columns: _GrantedColumns | None = None,
    ) -> None:
        # The grant as PostgreSQL's, made as the session's role, so its
        # grantor is too; with USAGE on the owner's schema, without which the
        # grantee could reach nothing in it. A column's is PostgreSQL's column
        # privilege of the same name (#1946).
        roles = sql.SQL(', ').join(self._grantee_role(g) for g in grantees)
        tail = sql.SQL(' WITH GRANT OPTION' if grantable else '')
        on = [
            sql.SQL('USAGE ON SCHEMA {}').format(sql.Identifier(owner.lower())),
            *self._pg_object_targets(kind, targets, privileges),
        ]
        for privilege, named in (columns.named if columns else {}).items():
            on.append(
                sql.SQL('{} ({}) ON TABLE {}').format(
                    sql.SQL(privilege),
                    sql.SQL(', ').join(sql.Identifier(a) for (_c, a) in named),
                    sql.SQL(targets[0][0]),
                )
            )
        for target in on:
            self._conn.execute(sql.SQL('GRANT {} TO {}{}').format(target, roles, tail))

    def _pg_object_revokes(
        self,
        key: tuple[str, str],
        kind: str,
        targets: list[tuple[str, str]],
        privileges: Iterable[str],
        grantee: str,
        me: str,
    ) -> None:
        # PostgreSQL's REVOKE, cascading to what the grantee granted on; and
        # the schema's USAGE once the grantee holds nothing of one's in it.
        (owner, name) = key
        role = self._grantee_role(grantee)
        # A privilege that maps to one the grantee still holds of this
        # grantor stays: READ and SELECT are both SELECT.
        kept = {
            r[0]
            for r in self._conn.execute(
                'SELECT privilege FROM sys.ora_grants WHERE owner = %s '
                'AND object_name = %s AND grantee = %s AND grantor = %s',
                (owner, name, grantee, me),
            )
        }
        mapping = _PG_PRIVILEGES.get(kind, _PG_PRIVILEGES['EXECUTABLE'])
        still = {mapping[p] for p in kept if p in mapping}
        gone = [p for p in privileges if p in mapping and mapping[p] not in still]
        for target in self._pg_object_targets(kind, targets, gone):
            self._conn.execute(
                sql.SQL('REVOKE {} FROM {} CASCADE').format(target, role)
            )
        rest = self._conn.execute(
            'SELECT 1 FROM sys.ora_grants WHERE owner = %s AND grantee = %s '
            'AND grantor = %s UNION ALL SELECT 1 FROM sys.ora_col_grants '
            'WHERE owner = %s AND grantee = %s AND grantor = %s LIMIT 1',
            (owner, grantee, me) * 2,
        ).fetchone()
        if rest is None:
            self._conn.execute(
                sql.SQL('REVOKE USAGE ON SCHEMA {} FROM {} CASCADE').format(
                    sql.Identifier(owner.lower()), role
                )
            )

    def _user_exists(self, name: str) -> bool:
        # A user is an account or a schema of that name: one made before the
        # Mirror kept accounts has a schema and no password (#879).
        if self._accounts.secret(name) is not None:
            return True
        row = self._conn.execute(
            'SELECT to_regnamespace(%s) IS NOT NULL', (f'"{name.lower()}"',)
        ).fetchone()
        return bool(row and row[0])

    def _user_statement(self, statement: str) -> Result | None:
        """CREATE USER, ALTER USER ... IDENTIFIED BY and DROP USER, on the
        accounts as well as the schemas (#879), with Oracle's errors. Any other
        ALTER USER clause is accepted and does nothing, as before. None for any
        other statement."""
        created = _CREATE_USER_STATEMENT.match(statement)
        if created is not None:
            name = _user_name(created.group(1))
            self._require_administrator('CREATE USER')
            if self._user_exists(name):
                # A launcher's account is a user with no schema yet; an Oracle
                # user always has one, so it gets it here, and the statement is
                # refused all the same, as Oracle refuses it.
                with self._administering() as conn:
                    conn.execute(
                        sql.SQL('CREATE SCHEMA IF NOT EXISTS {}').format(
                            sql.Identifier(name.lower())
                        )
                    )
                    conn.commit()
                raise BackendError(
                    f"user name '{name}' conflicts with another user or role name",
                    ora_code=ORA_USER_NAME_CONFLICT,
                )
            if self._per_user:
                # The account first: its role's password is kept with it.
                self._accounts.set(
                    name,
                    _password_text(created.group(2))
                    if created.group(2) is not None
                    else secrets.token_urlsafe(32),
                )
                try:
                    with self._administering() as conn:
                        self._ensure_user_role(conn, name)
                except BaseException:
                    self._accounts.drop(name)
                    raise
                return Result()
            self._conn.execute(
                sql.SQL('CREATE SCHEMA IF NOT EXISTS {}').format(
                    sql.Identifier(name.lower())
                )
            )
            self._conn.commit()
            if created.group(2) is not None:
                self._accounts.set(name, _password_text(created.group(2)))
            return Result()
        altered = _ALTER_USER_PASSWORD.match(statement)
        if altered is not None:
            name = _user_name(altered.group(1))
            if name != getattr(self, '_login_user', None):
                # A user changes its own password; another's is a DBA's.
                self._require_administrator('ALTER USER')
            if not self._user_exists(name):
                raise BackendError(
                    f"user '{name}' does not exist", ora_code=ORA_USER_DOES_NOT_EXIST
                )
            current = self._accounts.secret(name)
            replaced = altered.group(3)
            if replaced is not None and current is not None:
                if _password_text(replaced) != current:
                    raise BackendError(
                        'invalid username/password; logon denied',
                        ora_code=ORA_INVALID_USERNAME_PASSWORD,
                    )
            self._accounts.set(name, _password_text(altered.group(2)))
            return Result()
        unlocked = _ALTER_USER_UNLOCK.match(statement)
        if unlocked is not None:
            name = _user_name(unlocked.group(1))
            self._require_administrator('ALTER USER')
            if not self._user_exists(name):
                raise BackendError(
                    f"user '{name}' does not exist", ora_code=ORA_USER_DOES_NOT_EXIST
                )
            lockout.unlock(name)
            return Result()
        proxied = _ALTER_USER_PROXY.match(statement)
        if proxied is not None:
            self._require_administrator('ALTER USER')
            return self._proxy_grant(
                _user_name(proxied.group(1)),
                proxied.group(2).upper() == 'GRANT',
                _user_name(proxied.group(3)),
            )
        dropped = _DROP_USER_STATEMENT.match(statement)
        if dropped is not None:
            name = _user_name(dropped.group(1))
            self._require_administrator('DROP USER')
            if not self._user_exists(name):
                raise BackendError(
                    f"user '{name}' does not exist", ora_code=ORA_USER_DOES_NOT_EXIST
                )
            schema = sql.Identifier(name.lower())
            proxy_grants = self._has_proxy_grants()
            sys_privs = self._has_sys_privs()
            with self._administering() as conn:
                if self._per_user:
                    self._refuse_connected(conn, name)
                if dropped.group(2):
                    conn.execute(
                        sql.SQL('DROP SCHEMA IF EXISTS {} CASCADE').format(schema)
                    )
                else:
                    owns = conn.execute(
                        'SELECT EXISTS (SELECT 1 FROM pg_class WHERE relnamespace = '
                        'to_regnamespace(%s)) OR EXISTS (SELECT 1 FROM pg_proc WHERE '
                        'pronamespace = to_regnamespace(%s))',
                        (f'"{name.lower()}"',) * 2,
                    ).fetchone()
                    if owns and owns[0]:
                        raise BackendError(
                            f"CASCADE must be specified to drop '{name}'",
                            ora_code=ORA_CASCADE_REQUIRED,
                        )
                    conn.execute(sql.SQL('DROP SCHEMA IF EXISTS {}').format(schema))
                # Its object grants too, made, received or on what it owned
                # (#1858).
                for table in ('ora_grants', 'ora_col_grants'):
                    conn.execute(
                        f'DELETE FROM sys.{table} WHERE owner = %s OR grantee = %s '
                        'OR grantor = %s',
                        (name,) * 3,
                    )
                if proxy_grants:
                    # Its grants go with it, on either side (#1860).
                    conn.execute(
                        'DELETE FROM sys.ora_proxy_grants WHERE proxy = %s OR client = %s',
                        (name, name),
                    )
                if sys_privs:
                    # And its system privileges and role (#1936).
                    conn.execute(
                        'DELETE FROM sys.ora_sys_privs WHERE grantee = %s', (name,)
                    )
                if self._per_user:
                    self._drop_user_role(conn, name)
                conn.commit()
            self._accounts.drop(name)
            return Result()
        return None

    def _has_proxy_grants(self) -> bool:
        # Whether the dictionary keeps proxy grants (#1860): an installation
        # older than them, or one that failed, does not.
        row = self._catalog_read(
            "SELECT to_regclass('sys.ora_proxy_grants') IS NOT NULL"
        ).fetchone()
        return bool(row and row[0])

    def _has_sys_privs(self) -> bool:
        # Whether the dictionary keeps system privileges (#1936): an
        # installation older than them, or one that failed, does not.
        row = self._catalog_read(
            "SELECT to_regclass('sys.ora_sys_privs') IS NOT NULL"
        ).fetchone()
        return bool(row and row[0])

    def _proxy_grant(self, client: str, grant: bool, proxy: str) -> Result:
        # ALTER USER client GRANT | REVOKE CONNECT THROUGH proxy (#1860), with
        # 23ai's errors: ORA-01918 for a user there is not, on either side, and
        # ORA-38470 for a REVOKE of a grant there is not.
        for name in (client, proxy):
            if not self._user_exists(name):
                raise BackendError(
                    f"user '{name}' does not exist", ora_code=ORA_USER_DOES_NOT_EXIST
                )
        if not self._has_proxy_grants():
            raise UnsupportedFeature('proxy grants: the dictionary has no record')
        if self._per_user:
            # The DBA's record, on the installer's connection (#1857).
            with self._administering() as conn:
                if grant:
                    conn.execute(
                        'INSERT INTO sys.ora_proxy_grants VALUES (%s, %s) '
                        'ON CONFLICT DO NOTHING',
                        (proxy, client),
                    )
                    return Result()
                row = conn.execute(
                    'DELETE FROM sys.ora_proxy_grants WHERE proxy = %s AND client = %s '
                    'RETURNING 1',
                    (proxy, client),
                ).fetchone()
        elif grant:
            self._at_once(
                'INSERT INTO sys.ora_proxy_grants VALUES (%s, %s) ON CONFLICT DO NOTHING',
                (proxy, client),
            )
            return Result()
        else:
            row = self._at_once(
                'DELETE FROM sys.ora_proxy_grants WHERE proxy = %s AND client = %s '
                'RETURNING 1',
                (proxy, client),
            ).fetchone()
        if row is None:
            raise BackendError(
                'A proxy connection cannot be revoked if it was not granted first.',
                ora_code=_ORA_PROXY_NOT_GRANTED,
            )
        return Result()

    def change_password(
        self, username: str, old_password: str, new_password: str
    ) -> None:
        # The Mirror's client auth (its accounts, #879) is separate from the
        # backend's PostgreSQL connection (a fixed conninfo), so a password change
        # updates only the account -- a fresh Mirror session then authenticates
        # with the new password and the old one is rejected -- without touching
        # a PostgreSQL role (which would break the backend's own conninfo).
        # Oracle validates the old password (ALTER USER … REPLACE); do the same
        # against the stored secret (#515).
        current = self._accounts.secret(username)
        if current is not None and old_password != current:
            raise BackendError(
                'invalid username/password; logon denied',
                ora_code=ORA_INVALID_USERNAME_PASSWORD,
            )
        # Oracle takes a password of at most 1024 bytes (12.2+; 11g far less).
        # Past that, 23ai answers ORA-28218 up to 1039 bytes (#1713) and
        # ORA-01017 from 1040 -- the 1500-character change a client may try
        # draws it from 11g and 23ai alike -- so the Mirror answers the same,
        # rather than storing a password no Oracle would (#1266).
        size = len(new_password.encode('utf-8'))
        if size >= _PASSWORD_REFUSED_BYTES:
            raise BackendError(
                'invalid username/password; logon denied',
                ora_code=ORA_INVALID_USERNAME_PASSWORD,
            )
        if size > _MAX_PASSWORD_BYTES:
            raise BackendError(
                'password length more than 1024 bytes', ora_code=ORA_PASSWORD_TOO_LONG
            )
        self._accounts.set(username, new_password)

    # The end-to-end tracing attributes a client sets over the 12c piggyback
    # (#183). Oracle keeps them on the session and reports them through
    # SYS_CONTEXT('USERENV', ...); PostgreSQL's equivalent of session-scoped
    # state is a customised option, so each lands in `seerdb.<name>` and
    # sys_context (above) reads it back.
    # dbop names the operation V$SQL_MONITOR reports (#1619).
    _END_TO_END_SETTINGS = (
        'client_identifier',
        'module',
        'action',
        'client_info',
        'dbop',
    )

    @_while_connected
    def set_app_context(self, entries: list[tuple[str, str, str]]) -> None:
        """Keep the application context the client declared at login
        (`connect(appcontext=[(namespace, attribute, value), ...])`), which
        SYS_CONTEXT(namespace, attribute) reads back (#1581).

        In a session setting, as the service name is, committed at once: a
        setting made in a transaction that rolls back is undone with it.
        """
        context = {
            f'{namespace.upper()}.{attribute.upper()}': value
            for namespace, attribute, value in entries
        }
        try:
            self._conn.execute(
                "SELECT set_config('seerdb.app_context', %s, false)",
                (json.dumps(context),),
            )
            self._conn.commit()
        except psycopg.Error:
            self._conn.rollback()

    @_while_connected
    def apply_app_context(self, namespace: str, values: dict[str, str] | None) -> None:
        """Set or clear an application context namespace mid-session, what a
        client's set_app_context() / clear_app_context() sends (#1778).

        CLIENTCONTEXT is the only namespace a session can set here: there is no
        CREATE CONTEXT, so any other is ORA-28267, as 23ai answers a namespace
        the session may not set. Like set_end_to_end, the setting is made in
        the session's transaction and not committed -- committing would commit
        the client's own work -- so a rollback of that transaction undoes it.
        """
        if namespace.upper() != 'CLIENTCONTEXT':
            raise BackendError(
                'An invalid value was provided for the context namespace.',
                ora_code=28267,
            )
        row = self._conn.execute(
            "SELECT current_setting('seerdb.app_context', true)"
        ).fetchone()
        context = json.loads(row[0]) if row and row[0] else {}
        prefix = 'CLIENTCONTEXT.'
        if values is None:
            context = {k: v for k, v in context.items() if not k.startswith(prefix)}
        else:
            context.update({prefix + k.upper(): v for k, v in values.items()})
        self._conn.execute(
            "SELECT set_config('seerdb.app_context', %s, false)", (json.dumps(context),)
        )

    def set_end_to_end(self, attrs: dict) -> None:
        """Record the session's tracing attributes (#183).

        Called by the Mirror when the client sends the tracing piggyback. Only
        the attributes the client actually sent are touched: the piggyback marks
        each one modified or not, and an unmodified attribute keeps its value
        rather than being cleared.

        A cleared attribute is stored as the empty string rather than removed --
        there is no "unset" for a customised option within a session, and
        sys_context maps '' back to NULL, which is what Oracle reports.
        """
        with self._conn.cursor() as cur:
            for name in self._END_TO_END_SETTINGS:
                if name not in attrs:
                    continue
                value = attrs[name]
                cur.execute(
                    'SELECT set_config(%s, %s, false)',
                    (f'seerdb.{name}', '' if value is None else value),
                )

    @_while_connected
    def alter_session(self, statement: str) -> None:
        """Run the ALTER SESSION a client sent with its login.

        A 12.1+ client pins the session time zone to its own UTC offset this
        way. It is committed at once: a PostgreSQL SET made inside a transaction
        is undone if that transaction rolls back, and Oracle's is not.
        """
        priority = _txn_priority_setting(statement)
        if priority is not None:
            self._txn_priority, rest = priority
            if rest is None:
                return
            statement = rest
        self._at_once(_translate_admin(statement))

    def txn_priority(self) -> str:
        """The session's transaction priority, as 23ai reports it (#1779)."""
        return self._txn_priority

    def set_txn_priority(self, value: str) -> None:
        """Set the session's transaction priority from a client's ALTER SESSION
        piggyback (#1779); an empty value restores the default, HIGH. Session
        state only: PostgreSQL has no priority transactions."""
        self._txn_priority = value or 'HIGH'

    @_while_connected
    def commit(self) -> None:
        try:
            self._conn.commit()
        except psycopg.Error as exc:
            # A deferred constraint is checked at COMMIT, which then rolls the
            # transaction back; Oracle reports that as ORA-02091 over the
            # constraint's own error (#1789).
            self._conn.rollback()
            cause = _backend_error(exc)
            raise BackendError(
                f'transaction rolled back\n{cause.ora_message}',
                ora_code=ORA_TRANSACTION_ROLLED_BACK,
            ) from exc
        finally:
            self._user_savepoint = False
            self._end_sessionless()

    @_while_connected
    def rollback(self) -> None:
        self._conn.rollback()
        self._user_savepoint = False
        self._end_sessionless()

    def sessionless_begin(self, transaction_id: bytes, timeout: int) -> None:
        """Start a sessionless transaction on this session's connection (#1746):
        an id another session has started, suspended or not, is ORA-26217."""
        key = (self._conninfo, bytes(transaction_id))
        with _SESSIONLESS_LOCK:
            _lapse_sessionless(time.monotonic())
            if key in _SESSIONLESS:
                raise _sessionless_error(26217, key[1])
            _SESSIONLESS[key] = _ParkedTransaction(self._conn, True, 0.0)
        self._sessionless_id = key[1]
        self._sessionless_timeout = timeout

    def sessionless_suspend(self) -> None:
        """Suspend this session's sessionless transaction (#1746): its connection,
        the transaction open on it, is parked for another session to resume
        until `timeout` seconds pass, and this session goes on with a fresh
        one. Session settings travel with the connection, where Oracle's stay."""
        if self._sessionless_id is None:
            return
        key = (self._conninfo, self._sessionless_id)
        fresh = self._twin()._conn
        with _SESSIONLESS_LOCK:
            parked = _SESSIONLESS.get(key)
            if parked is not None:
                parked.active = False
                parked.expires = time.monotonic() + max(self._sessionless_timeout, 0)
        self._conn = fresh
        self._sessionless_id = None

    def sessionless_resume(self, transaction_id: bytes, timeout: int) -> None:
        """Resume a suspended sessionless transaction here (#1746): its parked
        connection becomes this session's. An unknown or lapsed id is
        ORA-26218; one another session has active is waited for until
        `timeout` seconds pass, then ORA-25351 -- 23ai's answers."""
        key = (self._conninfo, bytes(transaction_id))
        deadline = time.monotonic() + max(timeout, 0)
        while True:
            with _SESSIONLESS_LOCK:
                _lapse_sessionless(time.monotonic())
                parked = _SESSIONLESS.get(key)
                if parked is None:
                    raise _sessionless_error(26218, key[1])
                if not parked.active:
                    parked.active = True
                    (old, self._conn) = (self._conn, parked.conn)
                    parked.conn = self._conn
                    break
            if time.monotonic() >= deadline:
                raise _sessionless_error(25351, key[1])
            time.sleep(0.05)
        self._sessionless_id = key[1]
        self._sessionless_timeout = timeout
        try:
            old.rollback()
            old.close()
        except psycopg.Error:
            pass

    def _end_sessionless(self) -> None:
        # A commit or rollback ends this session's sessionless transaction: the
        # id is free again, and resuming it ORA-26218 (#1746).
        if self._sessionless_id is None:
            return
        with _SESSIONLESS_LOCK:
            _SESSIONLESS.pop((self._conninfo, self._sessionless_id), None)
        self._sessionless_id = None

    def close(self) -> None:
        # A per-user login that ended before it connected has nothing to
        # close (#1939).
        if not self._connected:
            return
        # A sessionless transaction this session still holds ends with it,
        # rolled back (#1746).
        if self._sessionless_id is not None:
            try:
                self._conn.rollback()
            except psycopg.Error:
                pass
            self._end_sessionless()
        # What the translation report has not written yet goes out first (#1557).
        self._flush_report()
        if self._report_conn is not None:
            self._report_conn.close()
        self._conn.close()
